	create_from_grid(G, N, M, S, '#');
	int H = N, W = M;

	const Weight INF = std::numeric_limits<Weight>::max() / 8;

	// 最大重み を計算
	int maxCost = 0;
	int pieceCnt = 0;
	rep(y, H) {
		rep(x, W) {
			if (S[y][x] == 'o') {
				int id = y * W + x;
				auto res = dijkstra(G, id);
				bool found = false;
				for (auto i : res) {
					chmax(maxCost, i);
					if (i != INF && i != 0) {
						found = true;
					}
				}
				if (found) {
					pieceCnt++;
				}
				else {
					// 行先の無いコマは壁とみなす
					S[y][x] = '#';
				}
			}

		}
	}

	// コマの数 + グリッドのマス目の数 + 始点終点
	// [0, pieceCnt): コマ
	// [pieceCnt, H*W): マス目
	// pieceCnt + H*W: s
	// pieceCnt + H*W + 1: t
	atcoder::mcf_graph<int, int> mcf(pieceCnt + H * W + 2);

	Graph G2(H*W);
	create_from_grid(G2, H, W, S, '#');

	// left: コマがあるグリッドのID
	int left = 0;
	rep(y, H) {
		rep(x, W) {
			if (S[y][x] == 'o') {
				int id = y * W + x;
				auto res = dijkstra(G2, id);
				rep(n, H*W){
					int i = res[n];

					if (i == INF || i == 0) {
						continue;
					}

					int right = n + pieceCnt;
					mcf.add_edge(left, right, 1, maxCost - i);
				}

				left++;
			}

		}
	}

	int s = pieceCnt + H * W;
	int t = pieceCnt + H * W + 1;

	// s -> コマ
	rep(i, pieceCnt) {
		mcf.add_edge(s, i, 1, 0);
	}
	// グリッド -> t
	REP(i, pieceCnt, pieceCnt + H * W) {
		mcf.add_edge(i, t, 1, 0);
	}

	auto mcf2 = mcf;
	auto res = mcf.slope(s, t);

	int ans = 0;

	for (auto p : res) {
		int cap = p.first;
		int cost = p.second;
		int cand = -(cost - cap * maxCost);

		chmax(ans, cand);
	}

	/*
	mcf2.flow(s, t);
	auto es = mcf2.edges();
	for (auto e : es) {
		cout << "from: " << e.from << " ";
		cout << "to: " << e.to << " ";
		cout << "cap: " << e.cap << " ";
		cout << "flow: " << e.flow << " ";
		cout << "cost: " << e.cost - maxCost << "\n";

	}
	*/

	cout << ans << "\n";
}

