WeightedResidualGraph::WeightedResidualGraph(int size)
	: size_m(size), graph_m(size) {
}

int WeightedResidualGraph::size() const {
	return size_m;
}

void WeightedResidualGraph::add(int from, int to, CostType cost, FlowType capacity) {
	Edge forward{ from, to, cost, capacity };
	Edge backward{ to, from, -cost, 0 };
	edges_m.push_back(forward);
	edges_m.push_back(backward);

	int edge_count = edges_m.size();
	graph_m[from].push_back(Item(edges_m, edge_count - 2));
	graph_m[to].push_back(Item(edges_m, edge_count - 1));
}

WeightedResidualGraph::List& WeightedResidualGraph::row(int from) {
	return graph_m[from];
}

const WeightedResidualGraph::List& WeightedResidualGraph::row(int from) const {
	return graph_m[from];
}

WeightedResidualGraph::Item WeightedResidualGraph::get(EdgeID index) {
	return Item(edges_m, index);
}

FlowType WeightedResidualGraph::flow(EdgeID index, FlowType quantity) {
	FlowType capacity = edges_m[index].capacity;
	FlowType real_flow = std::min(capacity, quantity);

	Edge& forward = edges_m[index];
	Edge& backward = edges_m[index ^ 0x01];
	forward.capacity -= real_flow;
	backward.capacity += real_flow;

	return real_flow;
}

