/*-----   MinimumCostFlowSolver   -----*/
/*-------------------------------------*/

MinimumCostFlowSolver::MinimumCostFlowSolver(int size)
	: graph_m(size), distance_m(size), potential_m(size) {
}

void MinimumCostFlowSolver::add(int from, int to, CostType cost, FlowType capacity) {
	graph_m.add(from, to, cost, capacity);
}

// (単位フローあたりの費用, その条件で流せるフロー) の組を返す
std::pair<CostType, FlowType> MinimumCostFlowSolver::flow(int start, int goal, FlowType limit) {
	std::fill(distance_m.begin(), distance_m.end(), InfCost);
	std::vector<EdgeID> ids(graph_m.size());

	using State = std::tuple<CostType, int, EdgeID>;	// from はいらない気もする
	std::priority_queue<State, std::vector<State>, std::greater<State>> queue;
	queue.push(State(0, start, -1));

	while (!queue.empty()) {
		State state = queue.top(); queue.pop();
		CostType cost = std::get<0>(state);
		int from = std::get<1>(state);
		EdgeID id = std::get<2>(state);

		if (distance_m[from] < InfCost) continue;
		distance_m[from] = cost;
		ids[from] = id;

		const auto& row = graph_m.row(from);
		for (const auto& edge : graph_m.row(from)) {
			if (edge.capacity() == 0) continue;

			int to = edge.to();
			CostType next_cost = cost + edge.cost() + potential_m[from] - potential_m[to];
			queue.push(State(next_cost, to, edge.getId()));
		}
	}

	if (distance_m[goal] == InfCost) return std::make_pair(InfCost, 0);

	// 最大で流せる量を確定
	FlowType max_flow = limit;
	{
		int curr = goal;
		while (curr != start) {
			EdgeID id = ids[curr];

			max_flow = std::min(max_flow, graph_m.get(id).capacity());
			curr = graph_m.get(id).from();
		}
	}

	// 実際に流す
	{
		int curr = goal;
		while (curr != start) {
			EdgeID id = ids[curr];

			graph_m.flow(id, max_flow);
			curr = graph_m.get(id).from();
		}
	}

	CostType min_cost = distance_m[goal] + potential_m[goal];
	return std::make_pair(min_cost, max_flow);
}

CostType MinimumCostFlowSolver::solve(int from, int to, FlowType quantity) {
	FlowType remain = quantity;
	CostType sum = 0;

	while (remain > 0) {
		auto result = flow(from, to, remain);
		CostType cost = result.first;
		FlowType flow = result.second;

		if (flow == 0) return InfCost;
		remain -= flow;
		sum += cost * flow;

		for (int i = 0; i < graph_m.size(); ++i) {
			potential_m[i] += distance_m[i];
		}
	}

	return sum;
}

