                    used[x.F][x.S] = 1;
                    g.add_edge(z, tt + x.S + x.F * m, 1, n * m - x.S - x.F + i + j);
                    for (int l = 0; l < 2; l++){
                        int nx = x.F + dx[l];
                        int ny = x.S + dy[l];
                        if (!used[nx][ny] && nx < n && nx >= 0 && ny < m && ny >= 0 && s[nx][ny] != '#'){
                            q.push({nx, ny});
                            used[nx][ny] = 1;
                        }
                    }
                }
                z++;
            }
        }
    }
    for (int i = 0; i < n; i++){
        for (int j = 0; j < m; j++){
            g.add_edge(z + j + m * i, z + n * m, 1, 0);
        }
    }
    for (int i = 0; i < z; i++){
        g.add_edge(n * m + z + 1, i, 1, 0);
    }
    auto x = g.flow(n * m + z + 1, n * m + z);
    cout << z * n * m - x.S;
}

