    for (i64 i = 0; i < n; i++) {
        vector<pair<i64, i64>> q;

        q.push_back(o[i]);

        i64 len = q.size();
        i64 ans = 0;

        for (i64 k = 0; k < q.size(); k++) {
            if (len == k) {
                ans += 1;
                len = q.size();
            }

            i64 x = q[k].first;
            i64 y = q[k].second;

            a[1 + i][1 + x * mx + y] = -ans;

