const int mn = 55;

namespace Min_Cost_Max_Flow {
    const int INF = 0x3f3f3f3f;  // INF flow
    const int N = 2503;          //最大点数
    const int M = 50000;         //最大边数
    int S, T, cnt, from[N], g[N], flow;
    ll d[N];  // 这里的 flow 就是最大流量
    ll ans;   // 费用，即为答案
    struct edge {
        int from, to, nxt, v;
        ll c;
    } e[M];  // c 是价格 v 是流量
    void add(int u, int v, int w, ll c) {
        e[++cnt].from = u;
        e[cnt].to = v;
        e[cnt].nxt = g[u];
        g[u] = cnt;
        e[cnt].c = c;
        e[cnt].v = w;
    }

    void add_edge(int u, int v, int w, ll c) {
        //printf("add_edge %d %d %d %lld\n", u, v, w, c);
        add(u, v, w, c);
        add(v, u, 0, -c);
    }

    bool spfa() {
        fill_n(d, N, INF);
        d[S] = 0;
        memset(from, 0, sizeof(from));
        queue<int> q;
        q.push(S);
        while (!q.empty()) {
            int now = q.front();
            q.pop();
            for (int i = g[now]; i; i = e[i].nxt) {
                if (e[i].v && d[e[i].to] > d[now] + e[i].c) {
                    d[e[i].to] = d[now] + e[i].c;
                    from[e[i].to] = i;
                    q.push(e[i].to);
                }
            }
        }
        return (d[T] != INF);
        // 改为return(d[T]<=0)即为最小费用可行流
    }

    void mcf() {
        int x = INF;
        for (int i = from[T]; i; i = from[e[i].from]) x = min(x, e[i].v);
        flow += x;
        for (int i = from[T]; i; i = from[e[i].from]) {
            e[i].v -= x;
            e[i ^ 1].v += x;
            ans += e[i].c * x;
        }
    }

    void Initialize(int s, int t) {  //源点和汇点
        S = s;
        T = t;
        memset(g, 0, sizeof(g));
        memset(e, 0, sizeof(e));
        ans = flow = 0;
        cnt = 1;
    }

    void doit() {
        while (spfa()) mcf();
    }
}  // namespace Min_Cost_Max_Flow


