    return (x - 1) * m + y;
}

int vis[mn][mn];
int to_end[mn][mn];

int head_count = 0;

void calc(int x, int y) {
    struct node {
        int x, y, t;

        bool operator<(const node &p) const {
            return t > p.t;
        }
    };
    memset(vis, 0, sizeof vis);
    queue<node> q;
    q.push({x, y, 0});
    vector<node> v;
    while (!q.empty()) {
        node u = q.front();
        q.pop();
        //printf("%d %d\n", u.x, u.y);
        v.push_back(u);
        if (u.x < n) {
            node nxt = {u.x + 1, u.y, u.t + 1};
            if (!(vis[nxt.x][nxt.y] || s[nxt.x][nxt.y] == '#')) {
                vis[nxt.x][nxt.y] = 1;
                q.push(nxt);
            }
        }
        if (u.y < m) {
            node nxt = {u.x, u.y + 1, u.t + 1};
            if (vis[nxt.x][nxt.y] || s[nxt.x][nxt.y] == '#') continue;
            vis[nxt.x][nxt.y] = 1;
            q.push(nxt);
        }
    }
    sort(begin(v), end(v));

    using namespace Min_Cost_Max_Flow;
    for (int i = 0; i < v.size() && i < head_count; i++) {
        node &p = v[i];
        if (p.t == 0) break;
        //printf("%d %d -> %d %d : %d\n", x, y, p.x, p.y, p.t);
        add_edge(getid(x, y), getid(p.x, p.y), 1, -p.t);
        if (!to_end[p.x][p.y]) {
            to_end[p.x][p.y] = 1;
            add_edge(getid(p.x, p.y), n * m + 1, 1, 0);
        }
    }
    if (!to_end[x][y]) {
        to_end[x][y] = 1;
        add_edge(getid(x, y), n * m + 1, 1, 0);
    }
}

