const int _ = 1e5 + 7; struct Edge{int end , upEd , f , c;}Ed[_]; int head[_] , cntEd = 1 , S , T;
void addEd(int a , int b , int c , int d){Ed[++cntEd] = (Edge){b , head[a] , c , d}; head[a] = cntEd;}
void addE(int a , int b , int c , int d){addEd(a , b , c , d); addEd(b , a , 0 , -d);}

queue < int > q; int pre[_] , dis[_] , fl[_]; bool vis[_];
bool SPFA(){
	q.push(S); for(int i = 1 ; i <= T + 1 ; ++i) dis[i] = -(1ll << 31) + 1;
	dis[S] = 0; fl[S] = (1ll << 31) - 1;
	while(!q.empty()){
		int t = q.front(); q.pop(); vis[t] = 0;
		for(int i = head[t] ; i ; i = Ed[i].upEd)
			if(Ed[i].f && dis[t] + Ed[i].c > dis[Ed[i].end]){
				dis[Ed[i].end] = dis[t] + Ed[i].c; fl[Ed[i].end] = min(Ed[i].f , fl[t]); pre[Ed[i].end] = i;
				if(!vis[Ed[i].end]){vis[Ed[i].end] = 1; q.push(Ed[i].end);}
			}
	}
	return dis[T] != dis[T + 1];
}

void EK(){
	int sum1 = 0 , sum2 = 0;
	while(SPFA()){
		sum1 += fl[T]; sum2 += fl[T] * dis[T]; int cur = T;
		while(cur != S){int p = pre[cur]; Ed[p].f -= fl[T]; Ed[p ^ 1].f += fl[T]; cur = Ed[p ^ 1].end;}
	}
	cout << sum2 << endl;
}

