using namespace std;

const int SPACE = 0;
const int BLOCK = 1;
const int PIECE = 2;

int main(void){
	int N, M;
	cin >> N >> M;

	vector<vector<int>> grid;
	for(int y = 0; y < N; y ++){
		vector<int> line(M);
		string s;
		cin >> s;
		for(int x = 0; x < M; x ++){
			switch(s[x]){
			case '.':
				line[x] = SPACE;
				break;
			case '#':
				line[x] = BLOCK;
				break;
			default:
				line[x] = PIECE;
				break;
			}
		}
		grid.push_back(move(line));
	}

	vector<vector<vector<pair<int, int>>>> dist_table;

	int count = 0;
	set<pair<int, int>> used;

	for(int y = 0; y < N; y ++){
		for(int x = 0; x < M; x ++){
			if(grid[y][x] == PIECE){
				vector<vector<pair<int, int>>> dists(N * M);
				for(int i = 0; i < N * M; i ++){
					dists[i] = vector<pair<int, int>>();
				}
				bool found = false;
				vector<tuple<int, int, int>> queue;
				queue.push_back(make_tuple(x, y, 0));
				int i = 0;
				while(i < queue.size()){
					int cx = get<0>(queue[i]);
					int cy = get<1>(queue[i]);
					int cd = get<2>(queue[i]);
					i ++;
					if(cx < M - 1 && grid[cy][cx + 1] != BLOCK){
						dists[cd + 1].push_back(make_pair(cx + 1, cy));
						queue.push_back(make_tuple(cx + 1, cy, cd + 1));
						found = true;
					}
					if(cy < N - 1 && grid[cy + 1][cx] != BLOCK){
						dists[cd + 1].push_back(make_pair(cx, cy + 1));
						queue.push_back(make_tuple(cx, cy + 1, cd + 1));
						found = true;
					}
				}
				if(found){
					dist_table.push_back(dists);
				}else{
					used.insert(make_pair(x, y));
				}
			}
		}
	}



	for(const auto& dists: dist_table){
		bool found = false;
		for(int d = N * M - 1; d >= 0; d --){
			for(const auto& point: dists[d]){
				if(used.find(point) == used.end()){
					count += d;
					used.insert(point);
//					print(point, d);
					found = true;
					break;
				}
			}
			if(found){
				break;
			}
		}
	}
	cout << count << endl;


	return 0;
}

