int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<string> grid(N);

    for (int i = 0; i < N; ++i) {
        cin >> grid[i];
    }

    mcf_graph<int, int> g(N * M + 2);
    int s = N * M;
    int t = N * M + 1;
    int ans = 0;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            int v1 = i * M + j;
            if (grid[i][j] == 'o') {
                g.add_edge(s, v1, 1, 0);
                ans += (N + M - 2) - i - j;
            }
            g.add_edge(v1, t, 1, (N + M - 2) - i - j);

        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (grid[i][j] == 'o') {
                vector<vector<int>> cost(N, vector<int>(M));
                for (int k = 0; k < N; ++k) {
                    for (int l = 0; l < M; ++l) {
                        cost[k][l] = -1;
                    }
                }
                cost[i][j] = 0;
                queue<pair<int, int>> que;
                pair<int, int> p0 = make_pair(i, j);
                que.push(p0);
                while (!que.empty()) {
                    auto cur = que.front();
                    int cost_cur = cost[cur.first][cur.second];
                    que.pop();
                    if (cur.first + 1 < N && grid[cur.first + 1][cur.second] != '#' &&
                        cost[cur.first + 1][cur.second] == -1) {
                        pair<int, int> p1 = make_pair(cur.first + 1, cur.second);
                        cost[cur.first + 1][cur.second] = cost_cur + 1;
                        que.push(p1);
                    }
                    if (cur.second + 1 < M && grid[cur.first][cur.second + 1] != '#' &&
                        cost[cur.first][cur.second + 1] == -1) {
                        pair<int, int> p1 = make_pair(cur.first, cur.second + 1);
                        cost[cur.first][cur.second + 1] = cost_cur + 1;
                        que.push(p1);
                    }
                }
                int v0 = i * M + j;
                for (int k = 0; k < N; ++k) {
                    for (int l = 0; l < M; ++l) {
                        int v1 = k * M + l;
                        if (cost[k][l] >= 0 && grid[k][l] != '#') {
                            g.add_edge(v0, v1, 1, 0);

                        }
                    }
                }
            }
        }
    }

    auto f = g.flow(s, t);

    cout << (ans - f.second) << endl;

    return 0;
}

