vl dfs(int i,int j){

	int maxd=0;
	deque<pi> que;
	// 初期条件 (頂点 0 を初期ノードとする)
	int start=i*M+j;
	que.push_back({start,0}); 
	vector<ll> visited(N*M,INF);
	while (!que.empty()) {
		pi vd = que.front(); //backにするとDFSになる
		que.pop_front();//pop_backにするとDFSになる
		int v=vd.first; int d=vd.second;
		int ci=v/M,cj=v%M;

		if (visited[v] != INF) continue;

		visited[v] = d;
		// v から辿れる頂点をすべて調べる
		if (ci<N-1 && s[ci+1][cj]!='#'){
			que.pb({(ci+1)*M+cj,d+1});
		}
		if (cj<M-1 && s[ci][cj+1]!='#'){
			que.pb({(ci)*M+cj+1,d+1});
		}
	}
	return visited;
}

