bool spfa()
{
    fill(dis + 1, dis + 1 + tim, -INF);
    dis[s] = 0;
    in[s] = true;
    que.push(s);
    while (!que.empty())
    {
        int now = que.front();
        in[now] = false;
        que.pop();
        for (int i = head[now]; i; i = e[i].nxt)
        {
            if (e[i].cap && dis[e[i].to] < dis[now] + e[i].cost)
            {
                dis[e[i].to] = dis[now] + e[i].cost;
                if (!in[e[i].to])
                {
                    in[e[i].to] = true;
                    que.push(e[i].to);
                }
            }
        }
    }
    return dis[t] != -INF;
}
int dfs(int now, int v)
{
    // cout << now << ' ' << v << endl;
    if (now == t)
    {
        ans += v;
        return v;
    }
    in[now] = true;
    int res = 0;
    for (int i = head[now]; i && v; i = e[i].nxt)
    {
        if (!in[e[i].to] && e[i].cap && dis[now] + e[i].cost == dis[e[i].to])
        {
            int tmp = dfs(e[i].to, min(v, e[i].cap));
            e[i ^ 0].cap -= tmp;
            e[i ^ 1].cap += tmp;
            v -= tmp;
            res += tmp;
            cost += e[i].cost * tmp;
        }
    }
    in[now] = false;
    return res;
}
