	std::vector<std::string> s(n);
	for(int i = 0; i < n; i++) cin >> s[i];

	int offset = n * m;
	auto idx = [&](int i, int j) { return i * m + j; };
	const int S = offset + offset;
	const int T = offset + offset + 1;
	const i64 INF = 1e9;

	i64 cnt = 0;
	atcoder::mcf_graph<int, i64> g(offset * 2 + 2);
