			if(j + 1 < m and s[i][j + 1] != '#') {
				g.add_edge(idx(i, j), idx(i, j + 1), INF, -1);
			}
			if(s[i][j] == 'o') {
				g.add_edge(S, idx(i, j), 1, INF);
				cnt++;
			}
			g.add_edge(idx(i, j), T, 1, INF);
		}
	}
	auto [flow, cost] = g.flow(S, T);

	printf("%lld\n", 2 * cnt * INF - cost);
