void sol(int x,int y)
{
	for(int i=0;i<=n;i++)
		for(int j=0;j<=m;j++)
			dp[i][j]=-1;
	dp[x][y]=0;
	int ax=x,ay=y;
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=m;j++)
		{
			if(s[i][j]!='.')
				continue;
			if(dp[i-1][j]!=-1)
				dp[i][j]=max(dp[i][j],dp[i-1][j]+1);
			if(dp[i][j-1]!=-1)
				dp[i][j]=max(dp[i][j],dp[i][j-1]+1);
			if(dp[i][j]>dp[ax][ay])
				ax=i,ay=j;
		}
	}	
	s[x][y]='.';
	s[ax][ay]='@';
	ans+=dp[ax][ay];
}
