int head[V], to[E], cap[E], cst[E], nxt[E], eid;
void Init() {
	memset(head, -1, sizeof(head));
	eid = 0;
}
void _add_edge(int u, int v, int w, int c) {
	to[eid] = v;
	cap[eid] = w;
	cst[eid] = c;
	nxt[eid] = head[u];
	head[u] = eid++;
}
void add_edge(int u, int v, int w, int c) {
	_add_edge(u, v, w, c);
	_add_edge(v, u, 0, -c);
}
queue<int> que;
int dist[V], pre[V], inq[V];
bool SPFA(int s, int t) {
	memset(dist, 0x3f, sizeof(dist));
	memset(inq, 0, sizeof(inq));
	memset(pre, -1, sizeof(pre));
	dist[s] = 0;
	que.push(s);
	inq[s] = 1;
	while (!que.empty()) {
		int u = que.front();
		que.pop();
		inq[u] = 0;
		for (int i = head[u]; ~i; i = nxt[i]) {
			int v = to[i];
			if (cap[i] > 0 && dist[v] > dist[u] + cst[i]) {
				dist[v] = dist[u] + cst[i];
				pre[v] = i;
				if (!inq[v]) {
					que.push(v);
					inq[v] = 1;
				}
			}
		}
	}
	return pre[t] != -1;
}
void MCMF(int s, int t) {
	int flow = 0, cost = 0;
	while (SPFA(s, t)) {
		int mn = INF;
		for (int u = t; u != s; u = to[pre[u] ^ 1]) mn = min(mn, cap[pre[u]]);
		flow += mn;
		for (int u = t; u != s; u = to[pre[u] ^ 1]) {
			cost += mn * cst[pre[u]];
			cap[pre[u]] -= mn;
			cap[pre[u] ^ 1] += mn;
		}
	}
	printf("%d\n", -cost);
}
