namespace KM{
	const int maxl=105;
	const int maxr=2505;
	int vl,vr,a[maxl][maxr];
	bool visx[maxl],visy[maxr];
	int x[maxl],matx[maxl];
	int y[maxr],maty[maxr],home[maxr],slack[maxr];
	int work(){
		for(int i=1;i<=vl;i++)
			x[i]=INF,matx[i]=0;
		for(int i=1;i<=vr;i++)
			y[i]=maty[i]=0;
		for(int s=1;s<=vl;s++){
			for(int i=1;i<=vr;i++){
				visy[i]=false;
				home[i]=0;
				slack[i]=INF;
			}
			for(int i=1;i<=vl;i++){
				if(!matx[i]){
					visx[i]=true;
					for(int j=1;j<=vr;j++){
						int val=x[i]+y[j]-a[i][j];
						if(val<slack[j]){
							slack[j]=val;
							home[j]=i;
						}
					}
				}
				else visx[i]=false;
			}
			bool f=false;
			while(!f){
				int dlt=INF;
				for(int i=1;i<=vr;i++)if(!visy[i])dlt=min(dlt,slack[i]);
				for(int i=1;i<=vl;i++)if(visx[i])x[i]-=dlt;
				for(int i=1;i<=vr;i++){
					if(visy[i])y[i]+=dlt;
					else slack[i]-=dlt;
				}
				for(int i=1;i<=vr;i++){
					if(!visy[i]&&slack[i]==0){
						visy[i]=true;
						if(!maty[i]){
							f=true;
							int pos=i,fa=home[pos];
							while(pos){
								int nxt=matx[fa];
								matx[fa]=pos;
								maty[pos]=fa;
								pos=nxt;fa=home[pos];
							}
							break;
						}
						else{
							int pos=maty[i];
							visx[pos]=true;
							for(int i=1;i<=vr;i++){
								if(visy[i])continue;
								int val=x[pos]+y[i]-a[pos][i];
								if(val<slack[i]){
									slack[i]=val;
									home[i]=pos;
								}
							}
						}
					}
				}
			}
		}
		int res=0;
		for(int i=1;i<=vl;i++)res+=a[i][matx[i]];
		return res;
	}
}

