                    add(id[j][k], i, -(j - g[i].x) - (k - g[i].y), 0);
                }
            }
        }
    }
    while (spfa())
    {
        int l = dfs(s, INF);
        while (l)
        {
            l = dfs(s, INF);
        }
    }
    cout << cost << endl;
    return 0;
}

