              vis[a][b + 1] = vis[a][b] + 1;
              P.emplace_back(a, b + 1);
            }
          }
        };
        bfs(i, j);
      }
      if (R[i][j]) {
        F.AddEdge(R[i][j], t, 1, 0);
      }
    }
  }
  int cost, flow;
  flow = F.MaxcostMaxflow(s, t, cost);
  //cout<<flow<<'\n';
  cout << -cost << '\n';
  return 0;
}
