void solve() {
    int n,m;
    cin >> n >> m;
    VS s(n);
    REP(i,0,n) cin >> s[i];
    int ans = 0;
    VP ps;
    REP(i,0,n) REP(j,0,m) if (s[i][j] == 'o') ps.pb(i,j);
    reverse(all(ps));
    VVI d(n,VI(m));
    for (auto &p: ps) {
        int x = p.first, y = p.second;
        REP(i,0,n) REP(j,0,m) d[i][j] = 1<<30;
