pair<int, pair<int, int> > findLongestPath(int i, int j) {
    for (int d = n - 1; d >= i; d--) {
        for (int d1 = m - 1; d1 >= j; d1--) {
            if (s[d][d1] == '#' || (s[d][d1] == 'o' && !(d == i && d1 == j))) {
                dp[d][d1] = -1;
                continue;
            }
            dp[d][d1] = 0;
            pre[d][d1] = mp(d, d1);
            if (d + 1 < n) {
                if (chkmax(dp[d][d1], 1 + dp[d + 1][d1])) {
                    pre[d][d1] = pre[d + 1][d1];
                }
            }
            if (d1 + 1 < m) {
                if (chkmax(dp[d][d1], 1 + dp[d][d1 + 1])) {
                    pre[d][d1] = pre[d][d1 + 1];
                }
            }
        }
    }
    return mp(dp[i][j], pre[i][j]);
}


