  for(int i = 0; i < N; ++i){
    cin >> S[i];
  }
  MinCostFlowGraph G(N*M+2);
  int source = N*M, sink = source+1;
  int c = 0, INF = 1e9;
  for(int i = 0; i < N; ++i){
    for(int j = 0; j < M; ++j){
      if(S[i][j] == '#') continue;
      int v = i*M+j;
      if(S[i][j] == 'o'){
        ++c;
        G.add_edge(source,v,1,0);
      }
      if(i+1 < N)
        G.add_edge(v,v+M,INF,-1);
      if(j+1 < M)
        G.add_edge(v,v+1,INF,-1);
      G.add_edge(v,sink,1,0);
    }
  }
  cout << -G.min_cost_flow(source,sink,c) << '\n';
}

