int minCostFlow(flows &F, int s, int t, int f) {
	int res = 0;
	vector< int > h(F.size(), 0);
	vector< int > d(F.size());
	vector< int > prevv(F.size());
	vector< int > preve(F.size());
	while (f > 0) {
		priority_queue< pii, vector< pii >, greater< pii > > q;
		d.assign(F.size(), LINF);
		d[s] = 0;
		q.push(pii(0, s));
		while (!q.empty()) {
			pii p = q.top();
			q.pop();
			int v = p.second;
			if (d[v] < p.first)
				continue;
			rep(i, F[v].size()) {
				flow &f = F[v][i];
				if (f.cap > 0 && d[f.to] > d[v] + f.cost + h[v] - h[f.to]) {
					d[f.to] = d[v] + f.cost + h[v] - h[f.to];
					prevv[f.to] = v;
					preve[f.to] = i;
					q.push(pii(d[f.to], f.to));
				}
			}
		}
		if (d[t] == LINF) {
			return -1;
		}
		rep(v, F.size()) h[v] += d[v];
		int tmp = f;
		for (int v = t; v != s; v = prevv[v]) {
			tmp = min(tmp, F[prevv[v]][preve[v]].cap);
		}
		f -= tmp;
		res += tmp * h[t];
		for (int v = t; v != s; v = prevv[v]) {
			flow &f = F[prevv[v]][preve[v]];
			f.cap -= tmp;
			F[v][f.rev].cap += tmp;
		}
	}
	return res;
}
