const int INF = 1e9 + 7;

struct MinCost {
    struct Edge {
        int u, f, mf, cost; // f -- flow, mf -- max flow
    };
    vector<Edge> edges;
    vector<vector<int>> e;
    int ALL;
    MinCost(int ALL): ALL(ALL) {
        e.resize(ALL);
    }

    void add_edge(int v, int u, int mf, int cost) {
        assert(v != u);
        e[v].push_back(edges.size());
        edges.push_back({u, 0, mf, cost});
        e[u].push_back(edges.size());
        edges.push_back({v, 0, 0, -cost});
    }

    pair<int,int> get_flow(int S, int T) {
        int f_size = 0;
        int sum_cost = 0;
        queue<int> q;
        vector<int> dist;
        vector<int> par;

        int last_min_dist = -INF;
        while (true) {
            dist.assign(ALL, INF);
            par.assign(ALL, -1);
            dist[S] = 0;
            q.push(S);
            while (!q.empty()) {
                int v = q.front();
                q.pop();
                for (auto eid: e[v]) {
                    auto E = edges[eid];
                    if (E.f < E.mf && dist[E.u] > dist[v] + E.cost) {
                        dist[E.u] = dist[v] + E.cost;
                        q.push(E.u);
                        par[E.u] = eid;
                    }
                }
            }
            if (dist[T] == INF) {
                break;
            }

            sum_cost += dist[T];
            f_size++;
            int v = T;
            while (v != S) {
                int eid = par[v];
                assert(eid != -1);
                edges[eid].f += 1;
                edges[eid ^ 1].f -= 1;
                v = edges[eid ^ 1].u;
            }
        }
        return {f_size, sum_cost};
    }
};


