char a[60][60];
int vis[60][60];
int S, T;
int n, m;
int head[3000], nxt[600000], to[600000], w[600000], f[600000], TOT;
queue <int> q;
int dist[3000], edge[3000], lst[3000], inq[3000];

void add_edge(int x, int y, int W, int F) {
	w[TOT] = W, f[TOT] = F, to[TOT] = y, nxt[TOT] = head[x], head[x] = TOT++;
	w[TOT] = 0, f[TOT] = -F, to[TOT] = x, nxt[TOT] = head[y], head[y] = TOT++;
}

void dfs(int x, int y, int id, int val) {
	vis[x][y] = 1, add_edge(id, x * n + y, 1, val - x - y);
	if (x + 1 < n && a[x + 1][y] != '#' && !vis[x + 1][y]) dfs(x + 1, y, id, val);
	if (y + 1 < m && a[x][y + 1] != '#' && !vis[x][y + 1]) dfs(x, y + 1, id, val);
}

bool spfa() {
	for (int i = 0; i <= T; i++) {
		dist[i] = 0x3f3f3f3f;
	}
	q.push(S), inq[S] = 1, dist[S] = 0;
	while (!q.empty()) {
		int x = q.front(); q.pop();
		inq[x] = 0;
		for (int i = head[x]; ~i; i = nxt[i]) {
			if (!w[i]) continue;
			int v = to[i];
			if (dist[v] > dist[x] + f[i]) {
				dist[v] = dist[x] + f[i];
				edge[v] = i, lst[v] = x;
				if (!inq[v]) q.push(v), inq[v] = 1;
			}
		}
	}
	return dist[T] != 0x3f3f3f3f;
}

int min_cost() {
	int cost = 0;
	while (spfa()) {
		int now = T;
		while (now != S) {
			int tmp = edge[now];
			w[tmp]--, w[tmp ^ 1]++;
			cost += f[tmp];
			now = lst[now];
		}
	}
	return cost;
}

int main () {
	memset(head, -1, sizeof(head));
	scanf("%d%d", &n, &m);
	for (int i = 0; i < n; i++) {
		scanf("%s", a[i]);
	}
	int tot = n * m, ans = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (a[i][j] == 'o') {
				memset(vis, 0, sizeof(vis));
				dfs(i, j, tot, i + j);
				tot++, ans -= i + j;
			}
		}
	}
	S = tot++, T = tot++;
	for (int i = n * m; i < tot - 2; i++) {
		add_edge(S, i, 1, 0);
	}
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			add_edge(i * n + j, T, 1, 0);
		}
	}
	ans = -min_cost();
	printf("%d\n", ans);
	return 0;
}

