    int ans = 0;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            int v1 = i * M + j;
            if (grid[i][j] == 'o') {
                g.add_edge(s, v1, 1, 0);
                ans += (N + M - 2) - i - j;
            }
            if (grid[i][j] != '#'){
                g.add_edge(v1, t, 1, (N + M - 2) - i - j);
            }
        }
