            dat[i] += v[i - 1];
            if (i + (i & -i) <= size) dat[i + (i & -i)] += dat[i];
        }
    }
    void add(int i, ll x) {
        i++;
        while (i <= size) {
            dat[i] += x;
            i += i & -i;
        }
    }
    void change(int i, ll x) {
        i++; int t = x - dat[i];
        while (i <= size) {
            int k = dat[i];
            dat[i] += t;
            t = dat[i] - k;
            i += i & -i;
        }
    }
    //[l,r)
    void add(int l, int r, ll x) {
        add(l, x); add(r, -x);
    }
    //[0,i]
    T query(int i) {
        i++;
        T sum = 0;
        while (i > 0) {
            sum += dat[i];
            i -= i & -i;
        }
        return sum;
    }
    //[l,r)
    T query(int l, int r) {
        return query(r - 1) - query(l - 1);
    }
    //[0,x) >= w
    int lower_bound(T w) {
        if (w <= 0) return 0;
        int x = 0, k = 1;
