int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll N, M;
  cin >> N >> M;
  vector<pll> start;
  vector<vector<char>> maze(N + 2, vector<char>(M + 2, '#'));
  ll cnt = 0;
  for (ll i = 0; i < N; ++i) {
    string s;
    cin >> s;
    for (ll j = 0; j < M; ++j) {
      maze.at(i + 1).at(j + 1) = s.at(j);
      if (s.at(j) == 'o') {
        cnt += 1;
        start.push_back({i + 1, j + 1});
      }
    }
  }
  mcf_graph<ll, ll> graph(cnt + N * M + 2);
  vector<pll> move = {{0, 1}, {1, 0}};
  ll MAX = 100000;
  for (ll i = 0; i < cnt; ++i) {
    ll x = start.at(i).first, y = start.at(i).second;
    //graph.add_edge(from, to, cap, cost)
    // cout << "i" << i << "\n";
    graph.add_edge(cnt + N * M, i, 1, 0);
    graph.add_edge(i, cnt + M * (x - 1) + (y - 1), 1, MAX);
    queue<pll> q;
    q.push({x, y});
    vector<vector<bool>> already(N + 2, vector<bool>(M + 2, false));
    already.at(x).at(y) = true;
    while (!q.empty()) {
      ll x1 = q.front().first, y1 = q.front().second;
      q.pop();
      for (ll j = 0; j < 2; ++j) {
        ll nx = x1 + move.at(j).first, ny = y1 + move.at(j).second;
        if (maze.at(nx).at(ny) == '#' || already.at(nx).at(ny)) {
          continue;
        }
        already.at(nx).at(ny) = true;
        q.push({nx, ny});
        // cout << nx << ' ' << ny << "\n";
        graph.add_edge(i, cnt + M * (nx - 1) + (ny - 1), 1, MAX - (abs(nx - x) + abs(ny - y)));
      }
    }
    // cout << "\n";
  }
  for (ll i = 0; i < N; ++i) {
    for (ll j = 0; j < M; ++j) {
      graph.add_edge(cnt + M * i + j, cnt + N * M + 1, 1, 0);
    }
  }
  //graph.flow(start, tink, flow_limit) pll{流量, cost}
  cout << MAX * cnt - graph.flow(cnt + N * M, cnt + N * M + 1, cnt).second << "\n";
}

