int l[105][105], r[105][105]; // id, diag
bool ban[105][51]; // ban[dd][0 <= pos < n]

vector<int> s[105]; // set of all chosed by d
int ans;

vector<pii> ev;

bool ok(int diag) {
    vector<int> ids = s[diag];
    sort(all(ids), [&](int i, int j){
        return l[i][diag] < l[j][diag];
    });

    int j = 0;
    multiset<int> rs;

    for (int i = 0; i < n; i++) {
        while (j < ids.size() && l[ids[j]][diag] == i) {
            // turn on
            rs.insert(r[ids[j]][diag]);
            j++;
        }
        if (!ban[diag][i]) {
            // close one
            if (rs.size() && *rs.begin() < i) {
                // bad
                return false;
            }
            if (rs.size()) {
                rs.erase(rs.begin());
            }
        }
    }

    return rs.size() == 0;
}

