ll W, H;
string S[55];
int dh[2] = {1, 0};
int dw[2] = {0, 1};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> H >> W;
    for(int i = 0; i < H; i++) cin >> S[i];
    int s = H * W;
    int t = s + 1;
    atcoder::mcf_graph<ll, ll> g(t + 1);
    ll ans = 0;
    ll num = 0;
    for(int h = 0; h < H; h++) {
        for(int w = 0; w < W; w++) {
            if(S[h][w] == '#') continue;
            if(S[h][w] == 'o') {
                g.add_edge(s, h*W+w, 1, 0);
                ans += (H-1-h) + (W-1-w);
                num++;
            }
            g.add_edge(h*W+w, t, 1, (H-1-h) + (W-1-w));
            for(int k = 0; k < 2; k++) {
                int newh = h + dh[k];
                int neww = w + dw[k];
                if(newh >= H) continue;
                if(neww >= W) continue;
                if(S[newh][neww] == '#') continue;
                g.add_edge(h*W+w, newh*W+neww, 100, 0);
            }
        }
    }
    auto tmp = g.flow(s, t, num);
    assert(tmp.first == num);
    ans -= tmp.second;
    cout << ans << endl;
    return 0;
}

