const vector<pair<int,int>> delta = {{1,0},{0,1}};
void solve(){
    int n,m;
    cin>>n>>m;
    vector<vector<char>> grid(n+2, vector<char>(m+2, '#'));
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            cin>>grid[i][j];
        }
    }
    ll ans = 0;
    function<int(int,int)> bfs = [&](int x,int y){
        queue<pair<int,int>> bfs;
        bfs.push({x,y});
        vector<vector<int>> dist(n+2, vector<int>(m+2, -1));
        dist[x][y] = 0;
        int ans = 0;
        pair<int,int> furthest;
        while(!bfs.empty()){
            const auto &[u,v] = bfs.front();
            for(const auto &[du, dv] : delta){
                if(grid[u+du][v+dv]=='#' || ~dist[u+du][v+dv]) continue;
                dist[u+du][v+dv] = dist[u][v] + 1;
                bfs.push({u+du, v+dv});
            }
            furthest = bfs.front();
            bfs.pop();
        }
        grid[furthest.first][furthest.second] = '#';
        return dist[furthest.first][furthest.second];
    };
    vector<pair<int,int>> order;
    order.reserve(n*m);
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            order.push_back({i,j});
        }
    }
    sort(order.begin(), order.end(), [&](const pair<int,int> &x, const pair<int,int> &y){
        return x.first + x.second > y.first + y.second;
    });
    for(const auto &[i,j] : order){
        if(grid[i][j]=='o'){
            ans+=bfs(i,j);
        }
    }
    cout<<ans<<"\n";
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    solve();
}

