#ifndef ATCODER_FENWICKTREE_HPP
#define ATCODER_FENWICKTREE_HPP 1
#include <cassert>
#include <vector>
namespace atcoder {

template <class T> struct fenwick_tree {
    using U = internal::to_unsigned_t<T>;
  public:
    fenwick_tree() : _n(0) {}
    fenwick_tree(int n) : _n(n), data(n) {}
    void add(int p, T x) {
        assert(0 <= p && p < _n);
        p++;
        while (p <= _n) {
            data[p - 1] += U(x);
            p += p & -p;
        }
    }
    void change(int p,T x){
        add(p,x-data[p]);
    }
    T sum(int l, int r) {
        assert(0 <= l && l <= r && r <= _n);
        return sum(r) - sum(l);
    }
  private:
    int _n;
    std::vector<U> data;
    U sum(int r) {
        U s = 0;
        while (r > 0) {
            s += data[r - 1];
            r -= r & -r;
        }
        return s;
    }
};
struct fenwickd{
private:
    ll u;
    vector<double> bit;
public:
    fenwickd(ll n){
        u=1;while(u<n)u*=2;
        bit.resize(u+10,0);

    }
    void add(ll n,double x){
        ll i=n;
        bit[i]+=x;
        //bit[i]%=mod;
        while(i<u){
            i+=i&(-i);
            bit[i]+=x;
            //bit[i]%=mod;
        }

    }
    void change(ll n,double x){
        add(n,x-bit[n]);
    }
    double sum(ll n){
        ll i=n;
        double ret=0;
        while(i>0){
            ret+=bit[i];
            i-=i&(-i);
            //ret%=mod;
        }
        return ret;
    }
    ll lb(double w){
        if(w<=0)return 0;
        ll x=0;
        for(ll k=u;k>0;k/=2){
            if(x+k<=u&&bit[x+k]<w){
                w-=bit[x+k];
                x+=k;
            }
        }
        return x+1;
    }
};
