using namespace std;

const int SPACE = 0;
const int BLOCK = 1;
const int PIECE = 2;

int main(void){
	int N, M;
	cin >> N >> M;

	vector<vector<int>> grid;
	for(int y = 0; y < N; y ++){
		vector<int> line(M);
		string s;
		cin >> s;
		for(int x = 0; x < M; x ++){
			switch(s[x]){
			case '.':
				line[x] = SPACE;
				break;
			case '#':
				line[x] = BLOCK;
				break;
			default:
				line[x] = PIECE;
				break;
			}
		}
		grid.push_back(move(line));
	}

	int count = 0;

	for(int y = 0; y < N; y ++){
		for(int x = 0; x < M; x ++){
			if(grid[y][x] == PIECE){
				vector<vector<pair<int, int>>> dists(N * M);
				for(int i = 0; i < N * M; i ++){
					dists[i] = vector<pair<int, int>>();
				}
				vector<tuple<int, int, int>> queue;
				queue.push_back(make_tuple(x, y, 0));
				set<pair<int, int>> visited;
				int i = 0;
				while(i < queue.size()){
					int cx = get<0>(queue[i]);
					int cy = get<1>(queue[i]);
					int cd = get<2>(queue[i]);
					i ++;
					const auto pair_r = make_pair(cx + 1, cy);
					if(cx < M - 1 && grid[cy][cx + 1] != BLOCK && visited.find(pair_r) == visited.end()){
						dists[cd + 1].push_back(pair_r);
						visited.insert(pair_r);
						queue.push_back(make_tuple(cx + 1, cy, cd + 1));
					}
					const auto pair_d = make_pair(cx, cy + 1);
					if(cy < N - 1 && grid[cy + 1][cx] != BLOCK && visited.find(pair_d) == visited.end()){
						dists[cd + 1].push_back(pair_d);
						visited.insert(pair_d);
						queue.push_back(make_tuple(cx, cy + 1, cd + 1));
					}
				}
				for(int d = N * M - 1; d >= 0; d --){
					bool found = false;
					for(const auto& point: dists[d]){
						int cx = point.first;
						int cy = point.second;
						if(grid[cy][cx] == SPACE){
							grid[y][x] = SPACE;
							grid[cy][cx] = BLOCK;
							count += d;
							found = true;
							break;
						}
					}
					if(found){
						break;
					}
				}
			}
		}
	}

	cout << count << endl;


	return 0;
}

