        for (i64 j = 0; j < mx; j++) {
            if (ax[i][j] == 'o') {
                o.push_back({ i, j });
            }
        }
    }

    n = o.size();
    m = nx * mx;

    a = vector<vector<i16>>(n + 1, vector<i16>(m + 1, 10'500));

    for (i64 i = 0; i < n; i++) {
        vector<pair<i64, i64>> q;

        q.push_back(o[i]);

        i64 len = q.size();
        i64 ans = 0;

        for (i64 k = 0; k < q.size(); k++) {
            if (len == k) {
                ans += 1;
                len = q.size();
            }

            i64 x = q[k].first;
            i64 y = q[k].second;

            a[1 + i][1 + x * mx + y] = -ans;

            if (x + 1 < nx && ax[x + 1][y] != '#') {
                q.push_back({ x + 1, y });
            }

            if (y + 1 < mx && ax[x][y + 1] != '#') {
                q.push_back({ x, y + 1});
            }
        }
    }
