struct flow_network {
	struct edge { ll to, cap, cost; };

	ll n, s, t;
	vvl adj;
	vector<edge> e;

	flow_network(ll n, ll s, ll t): n(n), s(s), t(t), adj(n) { }

	void add_edge(ll a, ll b, ll cap, ll cost) {
		adj[a].pb(sz(e));
		e.pb({b,cap,cost});
		adj[b].pb(sz(e));
		e.pb({a,0,-cost});
	}

	pll mcmf() {
		vl pot(n);
		FOR(t,0,n) FOR(i,0,n) for (ll k: adj[i]) if (e[k].cap) {
			pot[e[k].to] = min(pot[e[k].to],pot[i] + e[k].cost);
		}
		ll flow = 0, cost = 0;
		while (true) {
			vl dist(n,oo), pred(n);
			set<pll> q;
			dist[s] = 0, q.insert({0,s});
			while (sz(q)) {
				ll i = begin(q)->yy;
				q.erase(begin(q));
				for (ll k: adj[i]) if (e[k].cap) {
					ll j = e[k].to, ndist = dist[i] + e[k].cost + pot[i] - pot[j];
					if (ndist >= dist[j]) continue;
					q.erase({dist[j],j});
					dist[j] = ndist, pred[j] = k;
					q.insert({dist[j],j});
				}
			}
			if (dist[t] == oo) break;

			ll cap = oo, cost1 = 0;
			for (ll i = t; i != s; i = e[pred[i]^1].to) {
				cap = min(cap,e[pred[i]].cap), cost1 += e[pred[i]].cost;
			}
			flow += cap, cost += cap*cost1;
			for (ll i = t; i != s; i = e[pred[i]^1].to) {
				e[pred[i]].cap -= cap, e[pred[i]^1].cap += cap;
			}
			FOR(i,0,n) pot[i] += dist[i];
		}
		return {flow,cost};
	}
};

