const char newl = '\n';

int const MAX_N = 2510;
ll const INF = 1e18;

struct edge {
    int to,cap;
    ll cost;
    int rev;
};

ostream& operator<<(ostream& os,const edge& a) {os << "(" << a.to << ", " << a.cap << ", " << a.cost << ", " << a.rev << ")";return os;}

vector<edge> G[MAX_N];
ll dist[MAX_N];
int prevv[MAX_N],preve[MAX_N];

void add_edge(int from,int to,int cap,ll cost) {
    G[from].push_back(edge{to,cap,cost,(int)G[to].size()});
    G[to].push_back(edge{from,0,-cost,(int)G[from].size()-1});
}

ll min_cost_flow(int s,int t,int f,int n) {
    ll res = 0;
    while (f > 0) {
        fill(dist,dist+n,INF);
        dist[s] = 0;
        bool update = true;
        while (update) {
            update = false;
            for (int v = 0;v < n;++v) {
                if (dist[v] == INF) continue;
                // cout << "aaa" << v << newl;
                for (int i = 0;i < G[v].size();++i) {
                    edge& e = G[v][i];
                    if (e.cap > 0 && dist[e.to] > dist[v]+e.cost) {
                        dist[e.to] = dist[v]+e.cost;
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        update = true;
                    }
                }
            }
        }
        // p_ary(dist,0,n);
        // if (dist[t] == INF) return -1;
        if (dist[t] == INF) break;
        int d = f;
        for (int v = t;v != s;v = prevv[v]) d = min(d,G[prevv[v]][preve[v]].cap);
        f -= d;
        res += d*dist[t];
        for (int v = t;v != s;v = prevv[v]) {
            edge& e = G[prevv[v]][preve[v]];
            e.cap -= d;
            G[v][e.rev].cap += d;
        }
    }
    return res;
}

