int dy[4] = {1,0,-1,0},dx[4]={0,1,0,-1},ddy[8] = {1,0,-1,0,1,1,-1,-1},ddx[8] = {0,1,0,-1,1,-1,1,-1};
string arr[55];
int vis[55][55],ck1[2555],ck2[111];
bool tmr(pair<pi,pi> a,pair<pi,pi> b){
	if(a.x.x!=b.x.x) return a.x.x < b.x.x;
	return a.x.y > b.x.y;
}
int main(void){
	int n,m;
	scanf("%d%d",&n,&m);
	for(int e=0;e<n;e++) cin >> arr[e];
	vector<pair<pi,pi> > dp;
	int num = 1;
	for(int e=0;e<n;e++){
		for(int p=0;p<m;p++){
			if(arr[e][p]=='o'){
				memset(vis,0,sizeof(vis));
				int tot = 0;
				vector<pair<int,pi> > v;
				vis[e][p] = 1;
				v.push_back(mk(0,mk(e,p)));
				for(int y=e;y<n;y++){
					for(int x=p;x<m;x++){
						if(y==e&&x==p) continue;
						if(arr[y][x]=='#') continue;
						bool suc = false;
						if(y>e&&vis[y-1][x]) suc = true;
						if(x>p&&vis[y][x-1]) suc = true;
						if(!suc) continue;
						vis[y][x] = 1; 
						v.push_back(mk(abs(y-e)+abs(x-p),mk(y,x)));
						tot++;
					}
				}
				for(int q=0;q<sz(v);q++) dp.push_back(mk(mk(tot,v[q].x),mk(v[q].y.x*m+v[q].y.y,num)));
				num++;
			}
		}
	}
	sort(all(dp),tmr);
	int ans = 0;
	for(int e=0;e<sz(dp);e++){
		int wh1 = dp[e].y.x;
		int wh2 = dp[e].y.y;
		if(ck1[wh1]||ck2[wh2]) continue;
		ck1[wh1] = 1;
		ck2[wh2] = 1;
		ans += dp[e].x.y;
	}
	printf("%d",ans);
	return 0;
}

