const int N = 55;
int n, m, vis[N][N];
char s[N][N];

int main() {
	scanf("%d%d", &n, &m);
	REP(i,1,n) scanf("%s", s[i]+1);
	int ans = 0;
	PER(i,1,n) PER(j,1,m) {
		if (s[i][j]=='o') {
			memset(vis,0,sizeof vis);
			queue<pii> q;
			q.push({i,j});
			vis[i][j]=1;
			while (q.size()) {
				pii u = q.front(); q.pop();
				pii v(u.x+1,u.y);
				if (!vis[v.x][v.y]&&s[v.x][v.y]=='.') {
					vis[v.x][v.y] = 1;
					q.push(v);
				}
				v = pii(u.x,u.y+1);
				if (!vis[v.x][v.y]&&s[v.x][v.y]=='.') {
					vis[v.x][v.y] = 1;
					q.push(v);
				}
			}
			int mx = 0, xx=i, yy=j;
			PER(x,1,n) PER(y,1,n) if (vis[x][y]) {
				if (abs(x-i)+abs(y-j)>mx) {
					mx = abs(x-i)+abs(y-j);
					xx = x, yy = y;
				}
			}
			swap(s[i][j],s[xx][yy]);
			ans += mx;
		}
	}
	printf("%d\n", ans);
}

