    vector<string> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    auto id = [&](int i, int j) { return i * m + j; };

    int s = n * m, t = n * m + 1;
    atcoder::mcf_graph<int, int> graph(n * m + 2);

    int offset = 0;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
        {
            if (a[i][j] == '#') continue;

            if (a[i][j] == 'o')
            {
                offset += i + j;
                graph.add_edge(s, id(i, j), 1, 0);
            }

            graph.add_edge(id(i, j), t, 1, n + m - (i + j));

            if (i + 1 < n && a[i + 1][j] != '#')
                graph.add_edge(id(i, j), id(i + 1, j), INF, 0);

            if (j + 1 < m && a[i][j + 1] != '#')
                graph.add_edge(id(i, j), id(i, j + 1), INF, 0);
        }

    auto [flow, cost] = graph.flow(s, t);

    int ans = -(cost - flow * (n + m)) - offset;

    cout << ans << endl;

    exit(0);
}

