queue<Z> Q;


void bfs2(int flag){
  while(!Q.empty()){
    Z now = Q.front(); Q.pop();
    y = now.y, x = now.x, depth = now.depth;
    for(ll i=0; i<2; i++){
      Z next={y + y_vec2[i], x + x_vec2[i], depth + 1};
      if (A[next.y][next.x] == -1) continue;
      if (D[next.y][next.x]) continue;
      C[next.y][next.x] += flag;
      D[next.y][next.x] = true;
      Q.push(next);
    }
  }
}

ll bfs(){
  ll keep = 0, point = 0, px=0, py=0;
  while(!Q.empty()){
    Z now = Q.front(); Q.pop();
    y = now.y, x = now.x, depth = now.depth;
    if(A[y][x] == block){
      if (keep < C[y][x]){
        point = C[y][x] * depth;
        keep = C[y][x];
        px = x;
        py = y;
      }
      continue;
    }
    for(ll i=0; i<2; i++){
      Z next={y + y_vec[i], x + x_vec[i], depth + 1};
      if(B[next.y][next.x] == -1) continue;
      if(B[next.y][next.x] <= next.depth) continue;
      B[next.y][next.x] = next.depth;
      Q.push(next);
//cout << " d:" << next.depth << endl;          
    }
  }
  if (keep > 0){
    A[py][px] = oo;
    D.assign(H+2, vector<bool>(W+2, false));    
    Z st = {py, px, 0};
    Q.emplace(st);
    bfs2(-1);
  }
  return point;
}


