					F.add_edge(i*M+j,k*M+l,1,mod-(k-i+l-j));
				}
				if(c[k+1][l]!='#')used[k+1][l]|=used[k][l];
				if(c[k][l+1]!='#')used[k][l+1]|=used[k][l];
			}
		}else F.add_edge(i*M+j,N*M+1,1,0);
	}
	cout<<cnt*mod-F.minCostFlow(N*M,N*M+1,cnt)<<"\n";
}

