const ll oo = 1e12 + 10;

template <int N>
struct Mcmf {
    struct edge {
        int from, to, flow, cap, cost;
    };
    vector<edge> e;
    vi g[N];

    inline void add_edge(int from, int to, int cap, int cost) {
//        cout << from << " , " << to << " = (" << cap << ", " << cost << ")" << endl;
        g[from].push_back(e.size());
        e.push_back({from, to, 0, cap, cost});
        g[to].push_back(e.size());
        e.push_back({to, from, 0, 0, -cost});
    }

    int d[N];
    bool in_que[N];
    int from[N];

    pii mcmf(int s, int t) {
        int flow = 0, cost = 0;
        while (1) {
            fill(d, d + t + 1, oo);
            fill(in_que, in_que + t + 1, 0);
            d[s] = 0;
            in_que[s] = 1;
            queue<int> q;
            q.push(s);
            while (!q.empty()) {
                int v = q.front();
                q.pop();
                in_que[v] = 0;
                for (int id : g[v]) {
                    int to = e[id].to;
                    if (e[id].cap > e[id].flow && d[to] > d[v] + e[id].cost) {
                        d[to] = d[v] + e[id].cost;
                        from[to] = id;
                        if (!in_que[to]) {
                            q.push(to);
                            in_que[to] = 1;
                        }
                    }
                }
            }
            if (d[t] == oo) break;
            int v = t;
            vi ids;
            int pushed = oo;
            while (v != s) {
                int id = from[v];
                ids.push_back(id);
                v = e[id].from;
                inmin(pushed, e[id].cap - e[id].flow);
            }
            flow += pushed;
            for (auto id : ids) {
                e[id].flow += pushed;
                e[id ^ 1].flow -= pushed;
                cost += pushed * e[id].cost;
            }
        }
        return {flow, cost};
    };
};


