    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (s[i][j] != '#') f.add_edge(piece + i * m + j, t, 1, n + m - i - j);
        }
    }

    cout << offset - f.flow(st, t).second << endl;
