int spfa(int n)
{
    rep(i,1,n) dis[i]=inf;
    rep(i,1,n) pre[i]=-1;
    deque<int> q; q.pb(src);
    dis[src]=0; mark[src]=1;
    while(q.size())
    {
        int now=q.front(); q.pop_front(); mark[now]=0;
        for(auto i: to[now])
        {
            int v=e[i].v;
            if(dis[v]>dis[now]+e[i].w && e[i].c>0)
            {
                dis[v]=dis[now]+e[i].w;
                pre[v]=i;
                if(!mark[v])
                {
                    if(!q.empty() && dis[v]>=dis[q.front()]) q.pb(v);
                    else q.push_front(v);
                    mark[v]=1;
                }
            }
        }
    }
    return dis[sink]!=inf;
}
int costflow(int n)
{
    FLOW=0;
    int ans=0;
    while(spfa(n))
    {
        int mf=inf;
        for(int i=pre[sink];~i;i=pre[e[i].u]) mf=min(mf,e[i].c);
        for(int i=pre[sink];~i;i=pre[e[i].u]) e[i].c-=mf,e[i^1].c+=mf;
        ans+=dis[sink]*mf;
        FLOW+=mf;
    }
    return ans;
}

