        scanf("%s", str[i]);
    }
#define POSI(i,j) ((i)*m+(j))

    int num = n * m;

    vector<vector<pair<int, int> > > gg(num);
    vector<int> v;
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
            if (str[i][j] == '#') continue;
            if (str[i][j] == 'o') v.push_back(POSI(i, j));

            {
                int i2 = i + 1, j2 = j;
                if (i2 < n && str[i2][j2]!='#') {
                    gg[POSI(i, j)].push_back(make_pair(POSI(i2, j2),1));
                }
            }
            {
                int i2 = i, j2 = j+1;
                if (j2 < m && str[i2][j2] != '#') {
                    gg[POSI(i, j)].push_back(make_pair(POSI(i2, j2), 1));
                }
            }
        }
    }

    int sizv = v.size();
    vector<vector<ll> > dist(sizv);
    for (i = 0; i < sizv; i++) {
         dist[i] = dijkstra(v[i], gg);
    }

    /**
     * generate (s -> o -> all -> t) graph
     * i-th o    correspond to vertex i
     * i-th posi correspond to vertex sizv + i
     **/
    mcf_graph<int, long long> g(sizv + num + 2);
    int s = sizv+num, t = s+1;
    const long long BIG = 1'000'000'000;

    // we can "waste" the flow
    g.add_edge(s, t, sizv, BIG);

    int k;
    for (k = 0; k < sizv; k++) {
        g.add_edge(s, k, 1, 0);
    }
    for (i = 0; i < num; i++) {
        g.add_edge(sizv+i, t, 1, 0);
    }
    for (k = 0; k < sizv; k++) {
        for (i = 0; i < num; i++) {
            if (dist[k][i] != LINF) {
                g.add_edge(k, sizv + i, 1, -dist[k][i]);
            }
            else {
                g.add_edge(k, sizv + i, 1, 0);
            }
        }
    }
    auto result = g.flow(s, t, sizv);
    printf("%lld\n", -result.second);

    return;
}

