void add_edge(int x, int y, int W, int F) {
	w[TOT] = W, f[TOT] = F, to[TOT] = y, nxt[TOT] = head[x], head[x] = TOT++;
	w[TOT] = 0, f[TOT] = -F, to[TOT] = x, nxt[TOT] = head[y], head[y] = TOT++;
}

void dfs(int x, int y, int id) {
	vis[x][y] = 1, add_edge(id, x * m + y, 1, 0);
	if (x + 1 < n && a[x + 1][y] != '#' && !vis[x + 1][y]) dfs(x + 1, y, id);
	if (y + 1 < m && a[x][y + 1] != '#' && !vis[x][y + 1]) dfs(x, y + 1, id);
}

bool spfa() {
	for (int i = 0; i <= T; i++) {
		dist[i] = 0x3f3f3f3f;
	}
	q.push(S), inq[S] = 1, dist[S] = 0;
	while (!q.empty()) {
		int x = q.front(); q.pop();
		inq[x] = 0;
		for (int i = head[x]; ~i; i = nxt[i]) {
			if (!w[i]) continue;
			int v = to[i];
			if (dist[v] > dist[x] + f[i]) {
				dist[v] = dist[x] + f[i];
				edge[v] = i, lst[v] = x;
				if (!inq[v]) q.push(v), inq[v] = 1;
			}
		}
	}
	return dist[T] != 0x3f3f3f3f;
}

int min_cost() {
	int cost = 0;
	while (spfa()) {
		int now = T;
		while (now != S) {
			int tmp = edge[now];
			w[tmp]--, w[tmp ^ 1]++;
			cost += f[tmp];
			now = lst[now];
		}
	}
	return cost;
}

