  }
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      graph.add_edge(2 + K + i * w + j, 1, 1, 0);
    }
  }

  vector<pair<int, int>> v;
  vector<vector<bitset<K>>> b(h, vector<bitset<K>>(w));
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (s[i][j] == '#') continue;
