      if (j - 1 >= 0) b[i][j] |= b[i][j - 1];

      for (int k = 0; k < v.size(); k++) {
        if (!b[i][j][k]) continue;
        graph.add_edge(2 + k, 2 + K + i * w + j, 1, O - ((i - v[k].first) + (j - v[k].second)));
      }
    }
  }

