    auto pos = [&](ll u) -> tuple<ll, ll, ll> { 
        ll i = u/(w*2);
        ll j = u / 2 % w;
        ll k = u % 2;
        return {i, j, k};
    };
    ll ans = 0;
    mcf_graph<int, long long> g(2 * n + 2);
    int start = 2 * n, target = 2 * n + 1;

    ll cnt = 0;
    rep(i, h){
        rep(j, w){
            if (s[i][j] == '.'){
                g.add_edge(nid(i, j, 1), target, 1, 0);
            }
            else if (s[i][j] == 'o'){
                ans -= (i+j);
                g.add_edge(start, nid(i, j, 0), 1, 0);
                g.add_edge(nid(i, j, 0), nid(i, j, 1), 1, 1000-(i+j));
                g.add_edge(nid(i, j, 1), target, 1, 0);
                cnt++;
                stack<pll> st;
                st.push(mp(nid(i, j, 0), 0));
                vvl used = make_table(h, w, 0LL);
                used[i][j] = 1;
                while(sz(st)>0){
