                                    g.add_edge(nid(i, j, 0), nid(nx, ny, 1), 1, 1000-(nx+ny));
                                }
                            }
                        }
                    };
                    update(x+1, y);
                    update(x, y+1);
                }
            }
        }
    }
    auto d = g.flow(start, target, cnt);
    ans += (1000*cnt - d.second);
    cout << ans << endl;
