void my_change_cap0(mf_graph<int> &g) { // init
	rep(i, N) rep(j, M) {
		// これ以上動かせないところ
		if (S[i][j] == '#') continue;
		if (i == N - 1 and j == M - 1) {
			g.change_edge(p(i, j), 1, 0); // (0,0)->(1,0)
		} else if (i == N - 1 and j < M - 1) {
			if (S[i][j + 1] == '#') g.change_edge(p(i, j), 1, 0); // (0,0)->(1,0)
		} else if (i < N - 1 and j == M - 1) {
			if (S[i + 1][j] == '#') g.change_edge(p(i, j), 1, 0); // (0,0)->(1,0)
		} else if (i < N - 1 and j < M - 1) {
			if (S[i][j + 1] == '#' and S[i + 1][j] == '#') g.change_edge(p(i, j), 1, 0); // (0,0)->(1,0)
		}
	}
}

bool my_change_cap1(mf_graph<int> &g) { // 
	// 水を流した結果，これ以上動かせなくなったところ
	bool f = false;
	rep(i, N) rep(j, M) {
		if (S[i][j] == '#') continue;
		if (g.get_edge(p(i, j)).cap == 1) continue;

		if (i < N - 1 and j < M - 1) {
			if ((S[i][j + 1] == '#' or g.get_edge(p(i, j + 1)).flow == 1) and (S[i + 1][j] == '#' or g.get_edge(p(i + 1, j)).flow == 1)) {
				g.change_edge(p(i, j), 1, 0); // (0,0)->(1,0)
				f = true;
			}
		} else if (i == N - 1 and j < M - 1) {
			if (S[i][j + 1] == '#' or g.get_edge(p(i, j + 1)).flow == 1) {
				g.change_edge(p(i, j), 1, 0);
				f = true;
			}
		} else if (i < N - 1 and j == M - 1) {
			if (S[i + 1][j] == '#' or g.get_edge(p(i + 1, j)).flow == 1) {
				g.change_edge(p(i, j), 1, 0);
				f = true;
			}
		}
	}
	return f;
}



