	int k = 1;
	rep(i, N) rep(j, M) {
		if (S[i][j] == '#') {
			grid[i][j] = -1;
		} else if (S[i][j] == 'o') {
			grid[i][j] = k++;
		}
	}
	atcoder::mcf_graph< int, int > F(N * M + k + 2);
	int s = N * N + k, t = s + 1;
	rep(i, N) rep(j, M) if (grid[i][j] > 0) {
		int k = grid[i][j];
		int si = i, sj = j;
		vector< vector< int > > done(N, vector< int >(M, 0));
		queue< pii > q;
		q.emplace(si, sj);
		while (!q.empty()) {
			int i, j;
			tie(i, j) = q.front();
			q.pop();
			F.add_edge(N * M + k - 1, i * M + j, 1, sj - j + si - i);
			if (i + 1 < N && !done[i + 1][j]) {
				done[i + 1][j] = 1;
				q.emplace(i + 1, j);
			}
			if (j + 1 < M && !done[i][j + 1]) {
				done[i][j + 1] = 1;
				q.emplace(i, j + 1);
			}
