int main()
{
    int n , m ;
    scanf("%d %d",&n,&m) ;

    for(int i=0 ; i<n ; i++)
    {
        scanf("%s",s[i]) ;
    }

    for(int i=n-1 ; i>=0; i--)
    {
        for(int j=m-1 ; j>=0 ; j--)
        {
            if( s[i][j]=='#' ) continue ;
            dp[i][j][i][j] = 1 ;

            if( i< n-1 )
            {
                for(int k=0 ; k<n; k++)
                {
                    for(int l=0 ; l<m ; l++) dp[i][j][k][l] |= dp[i+1][j][k][l] ;
                }
            }
            if( j< m-1 )
            {
                for(int k=0 ; k<n; k++)
                {
                    for(int l=0 ; l<m ; l++) dp[i][j][k][l] |= dp[i][j+1][k][l] ;
                }
            }
        }
    }

    int cntob = 0 ;
    for(int i=0 ; i<n ; i++)
    {
        for(int j=0 ; j<m ; j++) if( s[i][j] == 'o' ) cnt[i][j] = cntob++ ;
    }

    int src = cntob + n*m  , sink = cntob + n*m+1 ;

    mcmf::init( cntob + n*m + 2 , src,sink ) ;

    for(int i=0 ; i<n ; i++)
    {
        for(int j=0 ; j<m ; j++)
        {
            if(s[i][j]!='o') continue ;

            for(int k=0 ; k<n ; k++)
            {
                for(int l=0 ; l<m ; l++)
                {
                    if( dp[i][j][k][l]  ) mcmf::addEdge( cnt[i][j] , cntob+ k*m + l , 1, -((k+l) - (i+j)) ) ;
                }
            }
        }
    }

    for(int i=0 ; i<n ; i++)
    {
        for(int j=0; j<m ; j++)
        {
            if( s[i][j]=='o' ) mcmf::addEdge(src , cnt[i][j],1,0) ;
            if( s[i][j] != '#' ) mcmf::addEdge( cntob+i*m+j , sink , 1 , 0 ) ;
        }
    }

    pair<int,int> ans = mcmf::solve() ;

    printf("%d\n",-ans.xx) ;

    return 0 ;
}

