namespace flow {

using graph::Node;
using graph::Weight;
using graph::Capacity;

template <typename FlowGraph>
class MinCostFlow {
    using prev_node_t = std::pair<Node, ll>;
    using pq_ele_t = std::pair<Weight, Node>;
    FlowGraph fgraph;
    const Weight dinf = 5e15;
    vec<Weight> dists, potential;
    vec<prev_node_t> pnode;

    void dijk(Node start) {
        std::priority_queue<pq_ele_t, vec<pq_ele_t>, std::greater<pq_ele_t>> pq;
        std::fill(ALL(dists), dinf);
        dists[start] = 0;
        pq.emplace(0, start);
        while (pq.size()) {
            Weight d;
            Node from;
            std::tie(d, from) = pq.top();
            pq.pop();
            if (dists[from] < d) continue;
            for (ll i = 0; i < fgraph[from].size(); i++) {
                const auto &edge = fgraph[from][i];
                auto to = edge.to();
                Weight dnxt = d + edge.weight() + potential[from] - potential[to];
                if (edge.cap() <= 0 || dists[to] <= dnxt) continue;
                dists[to] = dnxt;
                pnode[to] = prev_node_t(from, i);
                pq.emplace(dnxt, to);
            }
        }
    }

public:

    MinCostFlow(const FlowGraph &fgraph)
        : fgraph(fgraph), dists(fgraph.size()), 
          potential(fgraph.size(), 0), pnode(fgraph.size())
    {
    }

    Weight solve(Node start, Node goal, Capacity flow) {
        Weight ret = 0;
        while (0 < flow) {
            dijk(start);
            if (dists[goal] == dinf) return -1;
            for (ll i = 0; i < fgraph.size(); i++) potential[i] += dists[i];

            Capacity max_flow = flow;
            for (Node cur = goal; cur != start; cur = pnode[cur].first) {
                Node pre;
                ll pidx;
                std::tie(pre, pidx) = pnode[cur];
                const auto &edge = fgraph[pre][pidx];
                chmin(max_flow, edge.cap());
            }

            if (max_flow == 0) return -1;
            flow -= max_flow;
            ret += max_flow * potential[goal];
            for (Node cur = goal; cur != start; cur = pnode[cur].first) {
                Node pre;
                ll pidx;
                std::tie(pre, pidx) = pnode[cur];
                auto &edge = fgraph[pre][pidx];
                edge.cap() -= max_flow;
                auto &redge = fgraph[cur][edge.rev_idx()];
                redge.cap() += max_flow;
            }
        }

        return ret;
    }

    const FlowGraph& get_graph() const {
        return fgraph;
    }
};

}

int main() {
    ll n, m;
    std::cin >> n >> m;
    vec<std::string> vs(n);
    for (auto &e : vs) std::cin >> e;

    const ll inf = 1e13;

    ll di[2] = { 1, 0 };
    ll dj[2] = { 0, 1 };
    auto make_id = [&](ll i, ll j) { return m * i + j; };
    auto valid = [&](ll i, ll j) {
        if (!(0 <= i && i < n)) return false;
        if (!(0 <= j && j < m)) return false;
        if (vs[i][j] == '#') return false;
        return true;
    };

    auto dijk = [&](ll s) {
        vec<ll> dists(n * m, inf);
        std::priority_queue<pll, vec<pll>, std::greater<pll>> pq;
        dists[s] = 0;
        pq.emplace(0, s);
        while (pq.size()) {
            auto [ d, cur ] = pq.top();
            pq.pop();
            if (dists[cur] < d) continue;
            ll i = cur / m;
            ll j = cur % m;
            for (ll k = 0; k < 2; k++) {
                ll ni = i + di[k];
                ll nj = j + dj[k];
                if (!valid(ni, nj)) continue;
                ll nd = d + 1;
                ll nxt = make_id(ni, nj);
                if (dists[nxt] <= nd) continue;
                dists[nxt] = nd;
                pq.emplace(nd, nxt);
            }
        }
        return dists;
    };

    vvec<ll> dists;
    for (ll i = 0; i < n; i++) for (ll j = 0; j < m; j++) {
        if (vs[i][j] != 'o') continue;
        ll id = make_id(i, j);
        auto d = std::move(dijk(id));
        dists.push_back(std::move(d));
    }

    ll sz = dists.size();

    graph::FlowGraph<true> fg(sz + n * m + 2);
    ll sink = fg.size() - 1;
    ll src = sink - 1;

    for (ll i = 0; i < sz; i++) {
        const auto &d = dists[i];
        fg.add_edge(src, i, 1, 0);
        for (ll j = 0; j < d.size(); j++) {
            ll nxt = j + sz;
            if (d[j] == inf) continue;
            fg.add_edge(i, nxt, 1, inf - d[j]);
        }
    }
    for (ll j = 0; j < n * m; j++) {
        ll id = j + sz;
        fg.add_edge(id, sink, 1, 0);
    }

    flow::MinCostFlow<graph::FlowGraph<true>> mcf(fg);
    ll ans = mcf.solve(src, sink, sz);
    ans = -ans + sz * inf;
    std::cout << ans << "\n";
    return 0;
}

