int main() {
	int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
    }

    ll ans = 0;
    for (int i = n-1; i >= 0; --i) {
        for (int j = m-1; j >= 0; --j) {
            if(grid[i][j] != 'o') continue;
            vector<vector<int>> poss(n, vector<int>(m, 0));
            queue<pair<int, int>> q;
            q.emplace(i, j);
            while(q.size()) {
                auto p = q.front();
                q.pop();
                int cx = p.first, cy = p.second;
                poss[cx][cy] = 1;
                for (int di = 0; di < 2; ++di) {
                    int nx = cx + di;
                    int ny = cy + (di ^ 1);
                    if(nx >= n || ny >= m) continue;
                    if(grid[nx][ny] == '#') continue;
                    q.emplace(nx, ny);
                }
            }
            int maxi = i, maxj = j;
            for (int ii = 0; ii < n; ++ii) {
                for (int jj = 0; jj < m; ++jj) {
                    if(poss[ii][jj] == 0) continue;
                    int score = (ii - i) + (jj - j);
                    if(score >= (maxi - i) + (maxj - j)) {
                        maxi = ii;
                        maxj = jj;
                    }
                }
            }
            ans += (maxi - i) + (maxj - j);
            grid[maxi][maxj] = '#';
        }
    }
    cout << ans << endl;
}

