template <typename Flow, typename Cost>
class min_cost_flow {
 public:
  min_cost_flow(int n) : graph_(n) {}

  void add_edge(int from, int to, Flow cap, Cost cost) {
    graph_[from].emplace_back(to, (int)graph_[to].size(), cap, cost);
    graph_[to].emplace_back(from, (int)graph_[from].size() - 1, 0, -cost);
    m_ += 2;
  }

  std::pair<Flow, Cost> solve(
      int source, int sink, Flow max_flow = std::numeric_limits<Flow>::max()) {
    std::vector<Cost> costs;
    costs.reserve(m_);
    for (std::vector<edge>& edges : graph_) {
      for (edge& e : edges) {
        e.flow = 0;
        costs.push_back(e.cost);
      }
    }
    int n = (int)graph_.size();
    std::vector<Cost> dist(n, INF_COST);
    dist[source] = 0;
    std::vector<std::pair<int, edge*>> pred(n);
    std::queue<int> q;
    q.push(source);
    std::vector<bool> active(n, false);
    active[source] = true;
    while (!q.empty()) {  // Bellman-Ford shortest paths
      int u = q.front();
      q.pop();
      active[u] = false;
      for (edge& e : graph_[u]) {
        if (e.flow < e.cap && dist[u] + e.cost < dist[e.to]) {
          dist[e.to] = dist[u] + e.cost;
          pred[e.to] = {u, &e};
          if (!active[e.to]) {
            q.push(e.to);
            active[e.to] = true;
          }
        }
      }
    }
    constexpr auto comp = [](const std::pair<int, Cost>& lhs,
                             const std::pair<int, Cost>& rhs) {
      return lhs.second > rhs.second;
    };
    std::priority_queue<std::pair<int, Cost>, std::vector<std::pair<int, Cost>>,
                        decltype(comp)>
        pq(comp);
    Flow total_flow = 0;
    Cost total_cost = 0, curr_cost = 0;
    while (dist[sink] != INF_COST) {
      Flow delta = max_flow - total_flow;
      for (int v = sink; v != source;) {
        const auto& [u, e] = pred[v];
        delta = std::min(delta, e->cap - e->flow);
        v = u;
      }
      for (int v = sink; v != source;) {
        const auto& [u, e] = pred[v];
        e->flow += delta;
        graph_[v][e->rev].flow -= delta;
        v = u;
      }
      total_cost += delta * (curr_cost += dist[sink]);
      if ((total_flow += delta) == max_flow) {
        break;
      }
      for (int u = 0; u < n; ++u) {
        for (edge& e : graph_[u]) {
          e.cost += dist[u] - dist[e.to];
        }
      }
      std::fill(dist.begin(), dist.end(), INF_COST);
      dist[source] = 0;
      pq.emplace(source, 0);
      while (!pq.empty()) {  // Dijkstra's shortest paths
        auto [u, d_u] = pq.top();
        pq.pop();
        if (d_u > dist[u]) {
          continue;
        }
        for (edge& e : graph_[u]) {
          if (e.flow < e.cap && dist[u] + e.cost < dist[e.to]) {
            pq.emplace(e.to, dist[e.to] = dist[u] + e.cost);
            pred[e.to] = {u, &e};
          }
        }
      }
    }
    int k = 0;
    for (std::vector<edge>& edges : graph_) {
      for (edge& e : edges) {
        e.cost = costs[k++];
      }
    }
    return std::pair(total_flow, total_cost);
  }

 private:
  struct edge {
    int to, rev;
    Flow cap, flow;
    Cost cost;

    constexpr edge(int _to, int _rev, Flow _cap, Cost _cost)
        : to(_to), rev(_rev), cap(_cap), cost(_cost) {}
  };

  static constexpr Cost INF_COST = std::numeric_limits<Cost>::max();
  int m_;
  std::vector<std::vector<edge>> graph_;
};

int main() {
  auto start_time = std::chrono::steady_clock::now();
  std::mt19937 thanos(
      (std::uint_fast32_t)start_time.time_since_epoch().count());
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  std::cout.precision(24);
  int n, m;
  cin >> n >> m;
  vector<string> board(n);
  for (int i = 0; i < n; ++i) {
    cin >> board[i];
  }
  min_cost_flow<int, int> flow(n * m + 2);
  int s = n * m, t = n * m + 1;
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      if (board[i][j] == 'o') {
        flow.add_edge(s, i * m + j, 1, 0);
      }
      if (board[i][j] == '.') {
        flow.add_edge(i * m + j, t, 1, 0);
      }
      if (board[i][j] != '#') {
        if (i + 1 < n && board[i + 1][j] != '#') {
          flow.add_edge(i * m + j, (i + 1) * m + j, n * m, -1);
        }
        if (j + 1 < m && board[i][j + 1] != '#') {
          flow.add_edge(i * m + j, i * m + (j + 1), n * m, -1);
        }
      }
    }
  }
  cout << -flow.solve(s, t).second << '\n';
  return 0;
}

#include <stdio.h>
#include <queue>
#include <vector>
#define MAX 123456789
struct MCMF{
	struct Edge{
		int first;
		int second;
		int capacity;
		int cost;
	};
	std::vector<int> V[5010][5010];
	std::vector<Edge> E;
	std::vector<int> V2[5010];

	void setEdge(int first, int second, int capacity, int cost)
	{
		int n = E.size();
		E.push_back({first,second,capacity,cost});
		E.push_back({second,first,0,-cost});
		V[first][second].push_back(n);
		V[second][first].push_back(n+1);
	}

	int vSize;
	int source,sink;

	int dist[5010],check[5010],prev[5010];
	void init()
	{
		for(int i=0;i<=vSize;i++)
		{
			for(int j=0;j<=vSize;j++)
			{
				if(V[i][j].size()>0) V2[i].push_back(j);
			}
		}
	}
	std::vector<int> SPFA()
	{
		for(int i=0;i<=vSize;i++) check[i] = 0;
		for(int i=0;i<=vSize;i++) dist[i] = MAX;
		std::queue<int> Q;
		Q.push(source);
		dist[source] = 0;
		while(!Q.empty())
		{
			int v = Q.front();
			Q.pop();

			check[v] = 0;
			for(int j=0;j<V2[v].size();j++)
			{
				int i = V2[v][j];
				for(int k=0;k<V[v][i].size();k++)
				{
					int e = V[v][i][k];
					if(E[e].capacity>0)
					{
						if(dist[i]>dist[v]+E[e].cost)
						{
							dist[i] = dist[v] + E[e].cost;
							prev[i] = e;
							if(check[i]==0)
							{
								check[i] = 1;
								Q.push(i);
							}
						}
					}
				}
			}
		}

		std::vector<int> path;
		if(dist[sink]==MAX) return path;
		else
		{
			int v = sink;
			while(v!=source)
			{
				path.push_back(prev[v]);
				v = E[prev[v]].first;
			}
			return path;
		}
	}

	std::pair<int,int> getMCMF() // <Flow,Cost>
	{
		int flow = 0, cost = 0;
		while(1)
		{
			std::vector<int> path = SPFA();
			if(path.size()==0) return std::make_pair(flow,cost);
			else
			{
				int f = MAX, c = 0;
				for(int i=0;i<path.size();i++)
				{
					f = f<E[path[i]].capacity?f:E[path[i]].capacity;
					c += E[path[i]].cost;
				}
				flow += f;
				cost += f*c;
				for(int i=0;i<path.size();i++)
				{
					E[path[i]].capacity -= f;
					E[path[i]^1].capacity += f;
				}
			}
		}
	}	
}G;

