bool kuhn (int u) {
	if (bs[u]) return 0;

	bs[u] = 1;

	for (int v : adj[u])
		if (match[v] == -1) {
			match[v] = u;
			return 1;
		}

	for (int v : adj[u])
		if (kuhn(match[v])) {
			match[v] = u;
			return 1;
		}

	return 0;
}

