int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    li r, c;
    cin >> r >> c;
    vector<string> field(r);
    for (int i = 0; i < r; ++i) {
        cin >> field[i];
    }

    atcoder::mcf_graph<li, li> g(r * c + 2);
    const li source = r * c;
    const li sink = source + 1;

    li total_offset = 0;
    for (int i = 0; i < r; ++i) {
        for (int j = 0; j < c; ++j) {
            const li v = i * c + j;
            const li dist = abs(r - 1 - i) + abs(c - 1 - j);
            if (field[i][j] == 'o') {
                g.add_edge(source, v, 1, 0);
                total_offset += dist;
            }

            g.add_edge(v, sink, 1, dist);

            if (field[i][j] == '#') {
                continue;
            }
            if (i + 1 < r && field[i + 1][j] != '#') {
                g.add_edge(v, v + c, 100, 0);
            }
            if (j + 1 < c && field[i][j + 1] != '#') {
                g.add_edge(v, v + 1, 100, 0);
            }
        }
    }

    const auto flow = g.flow(source, sink);
    const li ans = total_offset - flow.second;
    cout << ans << endl;

    return 0;
}

