int getidx(const int M, const int i, const int j) {
    return M * i + j;
}

int main()
{
    int N, M;
    cin >> N >> M;
    vector<string> S(N);
    rep(i, N)cin >> S[i];

    const int SIZE = N * M;
    mcf_graph<int, int> graph(SIZE + 2);

    // Source, Sink付近のbuild
    rep(i, N)rep(j, M) {
        if (S[i][j] == 'o') {
            graph.add_edge(SIZE, getidx(M, i, j), 1, 0);
            S[i][j] = '.';
        }
        int manhattan = (N - 1 - i) + (M - 1 - j);
        graph.add_edge(getidx(M, i, j), SIZE + 1, 1, manhattan * 2);
    }
    // 隣接2項のbuild
    rep(i, N)rep(j, M) if (S[i][j] == '.') {
        // 右方向
        if (j + 1 < M && S[i][j + 1] == '.') {
            graph.add_edge(getidx(M, i, j), getidx(M, i, j + 1), 100, 1);
        }
        // 下方向
        if (i + 1 < N&&S[i + 1][j] == '.') {
            graph.add_edge(getidx(M, i, j), getidx(M, i + 1, j), 100, 1);
        }
    }
    graph.flow(SIZE, SIZE + 1);
    int res = 0;
    for (auto edge : graph.edges()) if (edge.from < SIZE && edge.to < SIZE) {
        res += edge.flow;
    }
    cout << res << endl;
    return 0;
}

