{
	std::size_t N, M;
	std::cin >> N >> M;
	std::stack<lib::pair<index_t>>stack;
	boost::multi_array<bool, 2> field(boost::extents[N][M]);
	for (auto i : boost::irange(N))
	{
		std::string data;
		std::cin >> data;
		for (auto j : boost::irange(M))
		{
			if (data[j] == '#')
			{
				field[i][j] = true;
			}
			else if (data[j] == 'o')
			{
				stack.emplace(i, j);
			}
		}
	}
	int sum = 0;
	while (stack.size())
	{
		auto [sx, sy] = stack.top();
		stack.pop();
		auto lx = sx;
		auto ly = sy;
		int lc = 0;
		boost::multi_array<bool, 2> flag(boost::extents[N][M]);
		std::queue<std::tuple<index_t, index_t, int>> queue;
		queue.emplace(sx, sy, 0);
		while (queue.size())
		{
			auto [x, y, c] = queue.front();
			queue.pop();
			lx = x;
			ly = y;
			lc = c;
			if (x + 1 < N && !field[x + 1][y] && !flag[x + 1][y])
			{
				queue.emplace(x + 1, y, c + 1);
				flag[x + 1][y] = true;
