int mind[100][50][50]; // [start][y][x];
int dy[] = {0,1}, dx[] = {1,0};

int main() {
	int N, M;
	cin >> N >> M;

	vector<string> maps(N);
	REP(i, N) cin >> maps[i];

	fill(mind[0][0], mind[N][0], INF);

	auto isin = [&](int y, int x) -> bool {
		return x >= 0 && x < M && y >= 0 && y < N;
	};

	vector<pii> starts;
	REP(sty, N) REP(stx, M) {
		if (maps[sty][stx] == 'o') {
			queue<pii> que;
			mind[starts.size()][sty][stx] = 0;
			que.emplace(sty, stx);

			while (!que.empty()) {
				int cy = que.front().first, cx = que.front().second;
				que.pop();

				REP(i, 2) {
					int ny = cy + dy[i], nx = cx + dx[i];
					if (!isin(ny, nx) || maps[ny][nx] == '#') continue;
					if (chmin(mind[starts.size()][ny][nx], mind[starts.size()][cy][cx] + 1)) {
						que.emplace(ny, nx);
					}
				}
			}

			// printf("sty = %d, stx = %d\n", sty, stx);
			// REP(i, N) {
			// 	REP(j, M) {
			// 		printf("%d ", mind[starts.size()][i][j] == INF ? -1 : mind[starts.size()][i][j]);
			// 	}
			// 	puts("");
			// }

			starts.emplace_back(sty, stx);
		}
	}

	int source = N * M + starts.size(), sink = N * M + starts.size() + 1;
	atcoder::mcf_graph<int, int> g(sink + 1);

	// int mx_flow = N * M * starts.size() + 1000;
	int ansbase = 0;
	// koma i は N * M + i
	REP(i, starts.size()) {
		int sty = starts[i].first, stx = starts[i].second;
		int dmax = 0;
		REP(y, N) REP(x, M) if (mind[i][y][x] != INF) chmax(dmax, mind[i][y][x]);
		ansbase += dmax;
		REP(y, N) REP(x, M) if (mind[i][y][x] != INF) {
			// コマ i から (y, x)
			g.add_edge(N * M + i, y * N + x, 1, dmax - mind[i][y][x]);

			// printf("koma %d -> (y,x)=(%d,%d)\n", i, y, x);
		}

		// source から コマ i
		g.add_edge(source, N * M + i, 1, 0);
	}

	REP(y, N) REP(x, M) {
		if (maps[y][x] != '#') {
			// (y, x) から sink
			g.add_edge(y * N + x, sink, 1, 0);
		}
	}

	pii fdat = g.flow(source, sink, starts.size());

	// printf("flow = %d\n", fdat.first);
	cout << ansbase - fdat.second;
	return 0;
}

