//NetWorkFlow
const int tN=252;
int tn,s,t;
vector<int> e[tN],to,fw,co;
void adde(int u,int v,int w,int c){
	e[u].pb(sz(to)),to.pb(v),fw.pb(w),co.pb(+c);
	e[v].pb(sz(to)),to.pb(u),fw.pb(0),co.pb(-c);
}
bool vis[tN]; int pre[tN],dep[tN];
bool spfa(){
	fill(vis,vis+tn,false);
	fill(pre,pre+tn,-1);
	fill(dep,dep+tn,-iinf);
	queue<int> q; q.push(s),dep[s]=0,vis[s]=true;
	while(sz(q)){
		int u=q.front(); q.pop(),vis[u]=false;
		for(int v:e[u])if(fw[v]&&dep[to[v]]<dep[u]+co[v]){
			dep[to[v]]=dep[u]+co[v],pre[to[v]]=v;
			if(!vis[to[v]]) vis[to[v]]=true,q.push(to[v]);
		}
	}
	return dep[t]!=-iinf;
}
pair<int,int> mcmf(){
	pair<int,int> res(0,0);
	while(spfa()){
//		cout<<"lycfucking.\n";
		int f=iinf;
		for(int i=t;i!=s;i=to[pre[i]^1]) f=min(f,fw[pre[i]]);
		for(int i=t;i!=s;i=to[pre[i]^1]) fw[pre[i]]-=f,fw[pre[i]^1]+=f;
		res.x+=f,res.y+=dep[t]*f;
//		cout<<"fengyangyang\n";
	}
	return res;
}

