#define INF 0x3f3f3f3f

using namespace std;

struct Edge {
  int u, v, c, w;
  Edge(int u, int v, int c, int w) : u(u), v(v), c(c), w(w) {}
};
class Graph {
  int n, s, t;
  vector<int> flow, dist, pre, last;
  vector<bool> vis;
  vector<Edge> edges;
  vector<vector<int>> adj;

public:
  Graph(int n, int s, int t) : n(n), s(s), t(t) {
    adj = vector<vector<int>>(n);
    flow.reserve(n);
    dist.reserve(n);
    pre.reserve(n);
    last.reserve(n);
    vis.reserve(n);
  }
  void add_edge(int u, int v, int c, int w) {
    int m = edges.size();
    edges.emplace_back(u, v, c, w);
    edges.emplace_back(v, u, 0, -w);
    adj[u].emplace_back(m);
    adj[v].emplace_back(m | 1);
  }

  bool spfa() {
    dist.assign(n, INF);
    flow.assign(n, INF);
    vis.assign(n, false);
    queue<int> q;
    q.push(s);
    vis[s] = true;
    dist[s] = 0;
    pre[t] = -1;

    while (!q.empty()) {
      int u = q.front();
      q.pop();
      vis[u] = false;
      for (int e : adj[u]) {
        auto [_, v, c, w] = edges[e];
        if (c > 0 && dist[v] > dist[u] + w) {
          dist[v] = dist[u] + w;
          pre[v] = u;
          last[v] = e;
          flow[v] = min(flow[u], c);
          if (!vis[v]) {
            vis[v] = true;
            q.push(v);
          }
        }
      }
    }

    return pre[t] != -1;
  }

  pair<int, int> min_cost_max_flow() {
    int mincost = 0;
    int maxflow = 0;
    while (spfa()) {
      int now = t;
      mincost += flow[t] * dist[t];
      while (now != s) {
        edges[last[now]].c -= flow[t];
        edges[last[now] ^ 1].c += flow[t];
        now = pre[now];
      }
      maxflow += flow[t];
    }
    return {maxflow, mincost};
  }
};

