int main() {
  int n, m;
  cin >> n >> m;
  vector<string> s(n);
  for (int i = 0; i < n; ++i)
    cin >> s[i];
  int ball = 0;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j)
      if (s[i][j] == 'o')
        ball++;
  int nodes = ball + n * m + 2;
  Graph g(nodes, 0, nodes - 1);
  int hi = n + m;
  for (int i = 1; i <= ball; ++i)
    g.add_edge(0, i, 1, 0);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j) {
      int idx = ball + i * m + j + 1;
      g.add_edge(idx, nodes - 1, 1, 0);
    }
  int ball_idx = 1;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j) {
      if (s[i][j] != 'o')
        continue;
      vector<vector<int>> dp(n, vector<int>(m, INF));
      dp[i][j] = 0;
      for (int p = i; p < n; ++p)
        for (int q = j; q < m; ++q) {
          if (s[p][q] == '#')
            continue;
          if (p > i && dp[p - 1][q] != INF)
            dp[p][q] = dp[p - 1][q] + 1;
          if (q > j && dp[p][q - 1] != INF)
            dp[p][q] = dp[p][q - 1] + 1;
          if (dp[p][q] != INF) {
            int idx = ball + p * m + q + 1;
            g.add_edge(ball_idx, idx, 1, hi - dp[p][q]);
          }
        }
      ball_idx++;
    }
  auto [flow, cost] = g.min_cost_max_flow();
  int ans = hi * flow - cost;
  cout << ans;
}

