struct Convert_ID_HW {
    ll H, W;
    Convert_ID_HW(ll H, ll W) : H(H), W(W) {}
    ll id(ll h_, ll w_) { return h_*W + w_;}
    ll h(ll id_) { return id_/W;}
    ll w(ll id_) { return id_%W;}
};

ll solve() {
    ll N, M;
    cin >> N >> M;
    vector<string> S(N);
    for ( int i = 0; i < N; i++ ) cin >> S[i];

    ll NM = N*M;
    Convert_ID_HW ix(N,M);
    atcoder::mcf_graph<ll,ll> g(2*NM+2);
    int id_f = 2*NM, id_t = 2*NM+1;
    ll n_o = 0;
    for ( int i = 0; i < N; i++ ) {
        for ( int j = 0; j < M; j++ ) {
            if ( S[i][j] == 'o' ) {
                g.add_edge(id_f, ix.id(i,j),1,0);
                n_o++;
            }
            g.add_edge(NM+ix.id(i,j),id_t,1,0);
        }
    }    
    for ( int i0 = 0; i0 < N; i0++ ) {
        for ( int j0 = 0; j0 < M; j0++ ) {
            if ( S[i0][j0] == 'o' ) {
                vector<vector<int>> d(N, vector<int>(M,-1));
                priority_queue<pii> q;
                d[i0][j0] = 0;
                q.push(pii(0,ix.id(i0,j0)));
                for ( int i = 0; i < N; i++ ) {
                    for ( int j = 0; j < M; j++ ) {
                        if ( i+1 < N && d[i][j] >= 0 && S[i+1][j] != '#') {
                            if ( d[i+1][j] < d[i][j]+1 ) {
                                d[i+1][j] = d[i][j]+1;
                                q.push(pii(d[i+1][j],ix.id(i+1,j)));
                            }
                        }
                        if ( j+1 < M && d[i][j] >= 0 && S[i][j+1] != '#') {
                            if ( d[i][j+1] < d[i][j]+1 ) {
                                d[i][j+1] = d[i][j]+1;
                                q.push(pii(d[i][j+1],ix.id(i,j+1)));
                            }
                        }
                    }
                }
                ll n_e = 0;
                while ( !q.empty() && n_e < n_o + min(N,M)) {
                    int id = q.top().second;
                    ll dd = q.top().first;
                    int i = ix.h(id), j = ix.w(id);
                    q.pop();
                    if ( d[i][j] == dd ) {
                        g.add_edge(ix.id(i0,j0), NM+ix.id(i,j), 1, N+M-dd);
                        n_e++;
                    }
                }
            }
        }
    }

    auto c = g.flow(id_f,id_t);
    auto v = g.edges();
    ll ans = (N+M)*n_o - c.second;
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int INF = 100;

template< typename flow_t, typename cost_t >
struct PrimalDual {
  const cost_t INF;

  struct edge {
    int to;
    flow_t cap;
    cost_t cost;
    int rev;
    bool isrev;
  };
  vector< vector< edge > > graph;
  vector< cost_t > potential, min_cost;
  vector< int > prevv, preve;

  PrimalDual(int V) : graph(V), INF(numeric_limits< cost_t >::max()) {}

  void add_edge(int from, int to, flow_t cap, cost_t cost) {
    graph[from].emplace_back((edge) {to, cap, cost, (int) graph[to].size(), false});
    graph[to].emplace_back((edge) {from, 0, -cost, (int) graph[from].size() - 1, true});
  }

  cost_t min_cost_flow(int s, int t, flow_t f) {
    int V = (int) graph.size();
    cost_t ret = 0;
    using Pi = pair< cost_t, int >;
    priority_queue< Pi, vector< Pi >, greater< Pi > > que;
    potential.assign(V, 0);
    preve.assign(V, -1);
    prevv.assign(V, -1);

    while(f > 0) {
      min_cost.assign(V, INF);
      que.emplace(0, s);
      min_cost[s] = 0;
      while(!que.empty()) {
        Pi p = que.top();
        que.pop();
        if(min_cost[p.second] < p.first) continue;
        for(int i = 0; i < graph[p.second].size(); i++) {
          edge &e = graph[p.second][i];
          cost_t nextCost = min_cost[p.second] + e.cost + potential[p.second] - potential[e.to];
          if(e.cap > 0 && min_cost[e.to] > nextCost) {
            min_cost[e.to] = nextCost;
            prevv[e.to] = p.second, preve[e.to] = i;
            que.emplace(min_cost[e.to], e.to);
          }
        }
      }
      if(min_cost[t] == INF) return -1;
      for(int v = 0; v < V; v++) potential[v] += min_cost[v];
      flow_t addflow = f;
      for(int v = t; v != s; v = prevv[v]) {
        addflow = min(addflow, graph[prevv[v]][preve[v]].cap);
      }
      f -= addflow;
      ret += addflow * potential[t];
      for(int v = t; v != s; v = prevv[v]) {
        edge &e = graph[prevv[v]][preve[v]];
        e.cap -= addflow;
        graph[v][e.rev].cap += addflow;
      }
    }
    return ret;
  }

  void output() {
    for(int i = 0; i < graph.size(); i++) {
      for(auto &e : graph[i]) {
        if(e.isrev) continue;
        auto &rev_e = graph[e.to][e.rev];
        cout << i << "->" << e.to << " (flow: " << rev_e.cap << "/" << rev_e.cap + e.cap << ")" << endl;
      }
    }
  }
};


int main(){
    int h, w;
    cin >> h >> w;
    vector<string> s(h);
    for(auto& i : s) cin >> i;
    PrimalDual<int, int> g(h * w + 2);
    const int S = h * w, T = S + 1;
    int cnt = 0;
    for(int i = 0; i < h; i++) for(int j = 0; j < w; j++){
        const int at = i * w + j;
        if(s[i][j] == 'o'){
            g.add_edge(S, at, 1, 0);
            cnt++;
        }
        if(s[i][j] != '#'){
            g.add_edge(at, T, 1, 0);
            if(i + 1 < h && s[i + 1][j] != '#') g.add_edge(at, at + w, INF, -1);
            if(j + 1 < w && s[i][j + 1] != '#') g.add_edge(at, at + 1, INF, -1);
        }
    }
    cout << -g.min_cost_flow(S, T, cnt) << endl;
}

