            rep(k, n) rep(l, m) dp[i][j][k][l] |= dp[i][j+1][k][l];
        }
    }
    int cnt = 0;
    int sv = 2 * n * m, tv = sv + 1;
    mcf_graph<ll, ll> g(tv + 1);
    rep(i, n) rep(j, m) if (s[i][j] == 'o') {
        cnt++;
        g.add_edge(sv, i * n + j, 1, 0);
        rep(k, n) rep(l, m) if (dp[i][j][k][l]) {
            if (s[k][l] == '#') continue;
            assert(i <= k && j <= l);
            assert(100 - (k - i + l - j) >= 0);
            g.add_edge(i * n + j, n * m + k * n + l, 1, 100 - (k - i + l - j));
        }
    }
    rep(i, n) rep(j, m) if (s[i][j] != '#') g.add_edge(n * m + i * n + j, tv, 1, 0);
    auto t = g.flow(sv, tv, cnt);
    assert(t.first == cnt);
    ll ans = -(t.second - 100 * cnt);
    cout << ans << endl;
}

