#include <bits/stdc++.h>
using namespace std;

const int maxn = 2510;
int n, m;
int cnt, ans, head[maxn], incf[maxn], dist[maxn], inq[maxn], pre[maxn];
struct edge { int to, cap, cost, nxt; } e[100000];
char str[55][55];

void add(int from, int to, int cap, int cost) {
    e[cnt] = (edge){to, cap, cost, head[from]}, head[from] = cnt++;
    e[cnt] = (edge){from, 0, -cost, head[to]}, head[to] = cnt++;
}

bool spfa(int s, int t) {
    fill(dist, dist + t + 1, -1e9);
    queue<int> q;
    q.push(s), dist[s] = 0, incf[s] = INT_MAX;
    while (!q.empty()) {
        int v = q.front(); q.pop(), inq[v] = 0;
        for (int i = head[v]; ~i; i = e[i].nxt) {
            if (e[i].cap && dist[e[i].to] < dist[v] + e[i].cost) {
                dist[e[i].to] = dist[v] + e[i].cost, pre[e[i].to] = i;
                incf[e[i].to] = min(incf[v], e[i].cap);
                if (!inq[e[i].to]) q.push(e[i].to), inq[e[i].to] = 1;
            }
        }
    }
    return dist[t] != -1e9;
}

void upd(int s, int t) {
	for (int i = t; i ^ s; i = e[pre[i] ^ 1].to) {
		e[pre[i]].cap -= incf[t], e[pre[i] ^ 1].cap += incf[t];
	}
	ans += dist[t] * incf[t];
}

void EK(int s, int t) {
    while (spfa(s, t)) upd(s, t);
}

int main() {
    memset(head, -1, sizeof(head));
    scanf("%d %d", &n, &m);
    for (int i = 1; i <= n; i++) {
        scanf("%s", str[i] + 1);
    }
    auto id = [&](int x, int y) {
        return (x - 1) * m + y;
    };
    int s = 0, t = n * m + 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (str[i][j] == 'o') {
                add(s, id(i, j), 1, 0);
            }
            if (str[i][j] != '#') {
                add(id(i, j), t, 1, 0);
            }
            if (i < n && str[i][j] != '#' && str[i + 1][j] != '#') {
                add(id(i, j), id(i + 1, j), 100, 1);
            }
            if (j < m && str[i][j] != '#' && str[i][j + 1] != '#') {
                add(id(i, j), id(i, j + 1), 100, 1);
            }
        }
    }
    EK(s, t), printf("%d\n", ans);
    return 0;
}

