int N,M,K;

void bfs(int k, pair<int,int> p, vector<vector<bool>> &V, mcf_graph<int,int> &G){
  priority_queue<pair<int,int>> PQ;
  vector<vector<int>> W(N,vector<int>(M,-1));

  queue<pair<int,int>> Q;
  Q.push(p);
  W[p.first][p.second] = 0;
  PQ.push(make_pair(0,p.first*M+p.second));
  while(!Q.empty()){
    pair<int,int> u = Q.front();Q.pop();
    int ux = u.first, uy = u.second;
    if(V[ux+1][uy] && W[ux+1][uy]==-1){
      W[ux+1][uy] = W[ux][uy] + 1;
      Q.push(make_pair(ux+1,uy));
      PQ.push(make_pair(W[ux+1][uy],(ux+1)*M+uy));
    }
    if(V[ux][uy+1] && W[ux][uy+1]==-1){
      W[ux][uy+1] = W[ux][uy] + 1;
      Q.push(make_pair(ux,uy+1));
      PQ.push(make_pair(W[ux][uy+1],ux*M+uy+1));
    }
  }

  for(int i=0;i<K;i++){
    if(PQ.empty()) break;
    pair<int,int> now = PQ.top();PQ.pop();
    G.add_edge(N*M+k, now.second, 1, N+M-now.first);
  }

  return;
}

int main(){
  cin >> N >> M;
  vector<string> S(N);
  for(int i=0;i<N;i++) cin >> S[i];
  vector<vector<bool>> V(N+1,vector<bool>(M+1,false));
  vector<pair<int,int>> P(0);
  for(int i=0;i<N;i++){
    for(int j=0;j<M;j++){
      if(S[i][j]!='#') V[i][j] = true;
      if(S[i][j]=='o') P.push_back(make_pair(i,j));
    }
  }
  K = P.size();

  mcf_graph<int,int> G(N*M + K + 2);
  for(int i=0;i<K;i++) G.add_edge(N*M+K, N*M+i, 1, 0);
  for(int i=0;i<N*M;i++) G.add_edge(i, N*M+K+1, 1, 0);

  for(int i=0;i<K;i++){
    bfs(i,P[i],V,G);
  }

  auto ans = G.flow(N*M+K,N*M+K+1);
  cout << (N+M)*K - ans.second << endl;
  return 0;
}

