/*
	MCMF O(VEf), Min Cost, Using SPFA Version
	주의 : 문제가 MCF를 요구하는 경우도 있으니 잘 확인하자.
	MCMF mcmf(V) : 정점 V개로 그래프를 생성한다.
	mcmf.AddEdge(a, b, c, w) : (a, b) 간선을 용량 c, 비용 w로 생성한다.
	mcmf.Run(src, snk) : MCMF를 찾고 {flow, cost}를 리턴한다.
*/
struct MCMF_Edge {
	int next, rev, c, f;
	ll w;
};
struct MCMF {
	vector<vector<MCMF_Edge> > g;
	vector<int> p, pp;
	queue<int> q;
	vector<ll> dist;
	vector<bool> inq;
	int V;
	MCMF(int _V) { V = _V; g.resize(V); }
	void AddEdge(int a, int b, int c, ll w) {
		g[a].push_back({ b, (int)g[b].size(), c, 0, w });
		g[b].push_back({ a, (int)g[a].size() - 1, 0, 0, -w });
	}
	pair<int, ll> Run(int src, int snk) {
		pair<int, ll> ret = { 0, 0 };
		while (1) {
			p = vector<int>(V, -1); p[src] = src;
			pp = vector<int>(V, -1); pp[src] = src;
			while (!q.empty()) q.pop(); q.push(src);
			dist = vector<ll>(V, 4e18); dist[src] = 0; // 4e18?
			inq = vector<bool>(V, false); inq[src] = true;
			while (!q.empty()) {
				int n = q.front(); q.pop(); inq[n] = false;
				for (int i = 0; i < g[n].size(); i++) {
					int next = g[n][i].next;
					ll ncost = dist[n] + g[n][i].w;
					if (g[n][i].c - g[n][i].f > 0) {
						if (dist[next] > ncost) {
							dist[next] = ncost;
							p[next] = n;
							pp[next] = i;
							if (inq[next] == false) {
								q.push(next);
								inq[next] = true;
							}
						}
					}
				}
			}
			if (p[snk] == -1) break;
			//if (dist[snk] >= 0) break; // Min Cost Flow?
			int flow = 1234567890; // 1234567890?
			for (int i = snk; i != src; i = p[i])
				flow = min(flow, g[p[i]][pp[i]].c - g[p[i]][pp[i]].f);
			for (int i = snk; i != src; i = p[i]) {
				auto &edg = g[p[i]][pp[i]];
				edg.f += flow; g[edg.next][edg.rev].f -= flow;
				ret.second += flow * edg.w;
			}
			ret.first += flow;
		}
		return ret;
	}
};

