    vector<vector<int>> dist(N * M, vector<int>(N * M, INF));
    auto conv = [&](int h, int w) {
        return h * M + w;
    };

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            cin >> S[i][j];
            if (S[i][j] != '#') {
                int to = conv(i, j);
                dist[to][to] = 0;
            }
        }
    }

    for (int from = 0; from < N * M; ++from) {
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < M; ++j) {
                if (dist[from][conv(i, j)] != INF) {
                    int cost = dist[from][conv(i, j)];
                    if (i + 1 < N && S[i + 1][j] != '#') {
                        dist[from][conv(i + 1, j)] = cost + 1;
                    }
                    if (j + 1 < M && S[i][j + 1] != '#') {
                        dist[from][conv(i, j + 1)] = cost + 1;
                    }
                }
            }
        }
    }

    ll BIG = (ll) 1e6;

    mcf_graph<ll, ll> mcf(2 * N * M + 2);
    int start = 2 * N * M;
    int term = start + 1;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            if (S[i][j] == 'o') {
                {
                    int to = 2 * conv(i, j);
                    ll cap = 1;
                    ll cost = 0;
                    mcf.add_edge(start, to, cap, cost);
                }
                for (int ni = i; ni < N; ++ni) {
                    for (int nj = j; nj < M; ++nj) {
                        int from = 2 * conv(i, j);
                        int to = 2 * conv(ni, nj) + 1;
                        ll cap = 1;
                        ll cost = dist[conv(i, j)][conv(ni, nj)];
                        if (cost != INF) {
                            ll d_cost = BIG - cost;
                            mcf.add_edge(from, to, cap, d_cost);
                        }
                    }
                }
            }
            {
                int from = 2 * conv(i, j) + 1;
                ll cap = 1;
                ll cost = 0;
                mcf.add_edge(from, term, cap, cost);
            }
        }
    }

    int cnt = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            if (S[i][j] == 'o') cnt++;
        }
    }
    auto ret = mcf.flow(start, term, cnt);
    ll ans = BIG * cnt - ret.second;
    cout << ans << endl;

