void solve() {
    ll n, m;
    cin >> n >> m;
    for(int i=0;i<n;i++){
        cin >> table[i];
    }
    int s = n * m, t = n * m + 1;
    mcf_graph<ll, ll> graph(n * m + 2);
    ll cnt = 0, sum = 0;
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            int x = i, y = j;
            int id = x * m + y;
            if (table[i][j] == '#') continue;

            int nx = x + 1, ny = y;
            if (nx < n) {
                int nid = nx * m + ny;
                graph.add_edge(id, nid, 100, 0);
            }

            nx = x, ny = y + 1;
            if (ny < m) {
                int nid = nx * m + ny;
                graph.add_edge(id, nid, 100, 0);
            }

            int res = (n - i) + (m - j);
            graph.add_edge(id, t, 1, res);

            if (table[i][j] == 'o') {
                cnt ++;
                sum += res;
                graph.add_edge(s, id, 1, 0);
            }
        }
    }
    ll res = graph.flow(s, t, cnt).second;
    ll ans = sum - res;
    p(ans);

    return;
}

