const int N = 55, INF = 0x7fffffff;

struct edge_t { int u, v, next, cap, flow, cost; } G[N * N * 8];

int dis[N * N], head[N * N], fr[N * N], used[N * N], maxflow[N * N];
char c[N][N];
int n, m, s, t, tot = 1, ans;

inline void addedge(int u, int v, int cap, int cost) {
    G[++tot] = (edge_t) {u, v, head[u], cap, 0, cost}, head[u] = tot;
    G[++tot] = (edge_t) {v, u, head[v], 0, 0, -cost}, head[v] = tot;
}

int spfa() {
    memset(dis, -0x3f, sizeof(dis));
    queue <int> q; q.push(s);
    used[s] = 1, dis[s] = 0, maxflow[s] = INF;
    while (!q.empty()) {
        int u = q.front(); q.pop(); used[u] = 0;
        for (int i = head[u]; i; i = G[i].next) {
            int v = G[i].v;
            if (G[i].cap > G[i].flow && dis[v] < dis[u] + G[i].cost) {
                dis[v] = dis[u] + G[i].cost; fr[v] = i;
                maxflow[v] = min(maxflow[u], G[i].cap - G[i].flow);
                if (!used[v]) {
                    q.push(v);
                    used[v] = 1;
                } 
            }
        }
    }
    return dis[t] != dis[t + 1];
}

void solve() {
    int tmp = t;
    while (tmp != s) {
        int i = fr[tmp];
        G[i].flow += maxflow[t];
        G[i ^ 1].flow -= maxflow[t];
        tmp = G[i].u;
    }
    ans += maxflow[t] * dis[t];
}

void EK() {
    while (spfa()) solve();
}

inline int ss(int x, int y) { return (x - 1) * m + y; }

int main() {
    read(n); read(m); s = 0; t = n * m + 1;
    for (int i = 1; i <= n; i++) scanf("%s", c[i] + 1);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (c[i][j] == '#') continue;
            if (c[i][j] == 'o') addedge(s, ss(i, j), 1, 0);
            if (i != n) addedge(ss(i, j), ss(i + 1, j), INF, 1);
            if (j != m) addedge(ss(i, j), ss(i, j + 1), INF, 1);
            addedge(ss(i, j), t, 1, 0);
        }
    }
    EK();
    print(ans, '\n');
    return 0;
}

