const ll BIG = 1e12;
mcf_graph<int,ll> g(2*55*55);
int H,W;
vector<string> grid;
set<pii> visited;

int id(int r, int c, int type) {
    return type*55*55+r*55+c;
}
int source = id(54,0, 0);
int sink = id(54,0, 1);

void dfs(int origin, int d, int r, int c) {
    if(visited.count({r,c}))
        return;
    visited.insert({r,c});

    if(grid[r][c]=='#')
        return;

    g.add_edge(origin, id(r,c,1), 1, BIG-d);

    if(r+1<H && grid[r+1][c]!='#') {
        dfs(origin, d+1, r+1, c);
    }

    if(c+1<W && grid[r][c+1]!='#') {
        dfs(origin, d+1, r, c+1);
    }
}

signed main() {
    FASTIO

    cin>>H>>W;
    grid = READ<string>(H);
    int pieces=0;

    FOR(r,H)
    FOR(c,W) {
        g.add_edge(id(r,c,1), sink, 1, 0);

        if(grid[r][c]=='o') {
            visited.clear();
            dfs(id(r,c,0), 0, r, c);
            g.add_edge(source, id(r,c,0), 1, 0);
            pieces++;
        }
    }

    auto f = g.flow(source, sink);
    ll ans = f.first*BIG - f.second;
    cout<<ans<<endl;

}

