        q.push_back(o[i]);

        i64 len = q.size();
        i64 ans = 0;

        for (i64 k = 0; k < q.size(); k++) {
            if (len == k) {
                ans += 1;
                len = q.size();
            }

            i64 x = q[k].first;
            i64 y = q[k].second;

            a[ind(i)][ind(x, y)] = -ans;

            if (x + 1 < nx && ax[x + 1][y] != '#') {
