            i64 i0 = p[j0], delta = inf, j1;
            for (i64 j = 1; j <= m; ++j)
                if (!used[j]) {
                    i64 cur = a[i0][j] - u[i0] - v[j];
                    if (cur < minv[j])
                        minv[j] = cur, way[j] = j0;
                    if (minv[j] < delta)
                        delta = minv[j], j1 = j;
                }
            for (i64 j = 0; j <= m; ++j)
                if (used[j])
                    u[p[j]] += delta, v[j] -= delta;
                else
                    minv[j] -= delta;
            j0 = j1;
        } while (p[j0] != 0);
        do {
            i64 j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }

    i64 cost = v[0];
