void solve()
{
    cin>>nn>>mm;
    s=vector <string>(nn);
    rep(i,nn)
    cin>>s[i];
    for (int i=0;i<nn;i++)
    {
        for (int j=0;j<mm;j++)
            k+=s[i][j]=='o';
    }
    a=vector <vector <ll> >(k+1,vll(nn*mm+1,INF));
    for (int i=0;i<nn;i++)
    {
        for (int j=0;j<mm;j++)
        {
            if (s[i][j]!='o')
                continue;
            dfs(i,j,0);
            curr++;
        }
    }
    //cout<<"ahha\n";
    ll ans;
    {
        int n = k;
        int m = nn * mm;
        vector<ll> u(n + 1), v(m + 1), p(m + 1), way(m + 1);
        for (int i = 1; i <= n; ++i) {
            p[0] = i;
            int j0 = 0;
            vector<ll> minv(m + 1, INF);
            vector<char> used(m + 1, false);
            do {
                used[j0] = true;
                int i0 = p[j0], delta = INF, j1;
                for (int j = 1; j <= m; ++j)
                    if (!used[j]) {
                        ll cur = a[i0][j] - u[i0] - v[j];
                        if (cur < minv[j])
                            minv[j] = cur, way[j] = j0;
                        if (minv[j] < delta)
                            delta = minv[j], j1 = j;
                    }
                for (int j = 0; j <= m; ++j)
                    if (used[j])
                        u[p[j]] += delta, v[j] -= delta;
                    else
                        minv[j] -= delta;
                j0 = j1;
            } while (p[j0] != 0);
            do {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0);
        }
        ans=v[0];
    }
//    for (int i=0;i<nn;i++)
