struct Mcf_graph{
	mcf_graph<int,ll> mcfg;
	Mcf_graph(){}
	Mcf_graph(ll n): mcfg(int(n)) {}
	ll add_edge(ll from,ll to,ll cap,ll cost) {
		return (ll)mcfg.add_edge(int(from),int(to),int(cap),cost);
	}
	mcf_graph<int,ll>::edge get_edge(ll i){ return mcfg.get_edge(int(i)); }
	vector<mcf_graph<int,ll>::edge> edges() { return mcfg.edges(); }
	pair<ll,ll> flow(ll s,ll t) {
		pair<int,ll> ret=mcfg.flow(int(s),int(t));
		return pair<ll,ll>{ret.first,ret.second};
	}
	pair<ll,ll> flow(ll s,ll t,ll flow_limit) {
		pair<int,ll> ret=mcfg.flow(int(s),int(t),int(flow_limit));
		return pair<ll,ll>{ret.first,ret.second};
	}
	vector<pair<int,ll>> slope(ll s,ll t) { return mcfg.slope(int(s),int(t)); }
	vector<pair<int,ll>> slope(ll s,ll t,ll flow_limit) {
		return mcfg.slope(int(s),int(t),int(flow_limit));
	}
};

vvll bfs2d(vector<string> &mz, pll st){
	ll h=mz.size(), w=mz[0].size();
	ll di[2]={0,1};
	ll dj[2]={1,0};
	vvll dist(h, vll(w, INF));
	queue<pll> Q;
	dist[st.first][st.second]=0;
	Q.push(st);
	while (!Q.empty()){
		ll i, j;  tie(i, j) = Q.front(); Q.pop();
		rep(k, 0, 1){
			ll ii=i+di[k], jj=j+dj[k];
			if (ii<0 or h<=ii or jj<0 or w<=jj) continue;

			if (mz[ii][jj]=='#') continue; //壁ならskip

			if (chmin(dist[ii][jj], dist[i][j]+1)) Q.push({ii,jj});
		}
	}
	return dist;
}

void solve()
{
	const ll BIG=1000000000;
	ll n,m;  cin >> n >> m;
	vector<string> S(n);  rep(i,0,n-1){ string S_; cin>>S_; S[i]=S_; }

	ll km=0;//コマ数
	rep(i,0,n-1){
		rep(j,0,m-1){
			if (S[i][j]=='o')km++;
		}
	}

	Mcf_graph graph(n*m+km+2); //n:頂点数 s,tも含む
	ll s=n*m+km;
	ll t=n*m+km+1;

	ll kmidx=0;
	rep(i,0,n-1){
		rep(j,0,m-1){
			if (S[i][j]!='o')continue;

			vvll dist=bfs2d(S,{i,j});

			ll kmv=n*m+kmidx;

			rep(ii,0,n-1){
				rep(jj,0,m-1){
					if (dist[ii][jj]==INF)continue;

					ll v=ii*m+jj;
					graph.add_edge(kmv,v,1,BIG-dist[ii][jj]);
				}
			}
			graph.add_edge(s,kmv,1,0);

			kmidx++;
		}
	}
	rep(i,0,n-1){
		rep(j,0,m-1){
			ll v=i*m+j;
			graph.add_edge(v,t,1,0);
		}
	}

	ll f,c; tie(f,c)=graph.flow(s,t,km); //戻り値 f:流せた量、c:最小コスト
	ll ans=BIG*km-c;
	cout << ans << '\n';
}


