string board[51];
int emptyIdx[51][51];
bool visited[51][51];

struct Item
{
    Item(int xx, int yy, int ss) : x(xx), y(yy), step(ss) {}
    int x;
    int y;
    int step;
};

int main()
{
    int m, n;
    cin >> n >> m;
    vector<pair<int, int>> chess;
    int emptyCount = 0;
    FROM_0(i, n)
    {
        cin >> board[i];
        FROM_0(j, m)
        {
            emptyIdx[i][j] = -1;
            if (board[i][j] == 'o')
                chess.push_back(make_pair(j, i));
            if (board[i][j] == 'o' || board[i][j] == '.')
            {
                emptyIdx[i][j] = emptyCount;
                emptyCount++;
            }
        }
    }

    // graph
    atcoder::mcf_graph<int, int> graph(chess.size() + emptyCount + 2);
    FROM_0(idx, chess.size())
    {
        const auto & c = chess[idx];
        list<Item> buffer;
        buffer.push_back(Item(c.first, c.second, 0));
        FROM_0(i, n)
        {
            FROM_0(j, m)
                visited[i][j] = false;
        }
        while (!buffer.empty())
        {
            int x = buffer.front().x, y = buffer.front().y, step = buffer.front().step;
            buffer.pop_front();
            if (visited[y][x])
                continue;
            visited[y][x] = true;
            //cout << idx << ' ' << chess.size() + emptyIdx[y][x] << ' ' << -step << endl;
            graph.add_edge(idx, chess.size() + emptyIdx[y][x], 1, 200 - step);
            if (x + 1 < m && board[y][x + 1] != '#' && !visited[y][x + 1])
                buffer.push_back(Item(x + 1, y, step + 1));
            if (y + 1 < n && board[y + 1][x] != '#' && !visited[y + 1][x])
                buffer.push_back(Item(x, y + 1, step + 1));
        }
    }
    // max flow
    int start = chess.size() + emptyCount;
    int end = start + 1;
    FROM_0(i, chess.size())
    {
        //cout << i << ' ' << start << endl;
        graph.add_edge(start, i, 1, 0);
    }
    FROM_0(i, emptyCount)
    {
        //cout << i + chess.size() << ' ' << end << endl;
        graph.add_edge(i + chess.size(), end, 1, 0);
    }
    auto ret = graph.flow(start, end);
    cout << 200 * chess.size() - ret.second << endl;

    return 0;
}

