int main() {
	int h, w;
    cin >> h >> w;
    vector<string> grid(h);
    for (int i = 0; i < h; ++i) {
        cin >> grid[i];
    }

    mcf_graph<int, int> P(h * w + 2);
    int s = h * w, t = h * w + 1;
    int fst = 0, cnt = 0;
    const int inf = 1e5;
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            if(grid[i][j] == 'o') {
                P.add_edge(s, i * w + j, 1, 0);
                fst += i + j;
                cnt++;
            }
            if(grid[i][j] != '#') {
                for (int d = 0; d < 2; ++d) {
                    int x = i + d, y = j + (d ^ 1);
                    if(x >= h || y >= w) continue;
                    if(grid[x][y] == '#') continue;
                    P.add_edge(i * w + j, x * w + y, h * w, 0);
                }
                P.add_edge(i * w + j, t, 1, inf - (i + j));
            }
        }
    }
    int lst = P.flow(s, t).second;
    cout << inf * cnt - lst - fst << endl;
}

