// Implementation of the Hungarian algorithm for the matching of minimum
// cost.
// Complexity: N³
//
// This source code was heavily inspired (stands for copy-pasted) from:
//      https://e-maxx.ru/algo/assignment_hungary

#include <vector>
#include <limits>
using namespace std;

// This class accepts a complete weighted bipartite graph (as a NxM matrix)
// and solves the assignment problem.
// The costs can be both positive or negative (this way also the max-cost
// problem can be handled).
// The matrix need not to be a square-matrix, but it must hold N <= M.
// Hence the matching will always have size equal to N.
// The class is templatized over T that is the type of the costs.
//
// To compute the minimum cost call GetMinCostMatching().
// If you are also interested in the actual matching, just look at the
// prec vector, that associates to any column its row (prec[c] = N if the
// column is not matched).

template <typename T>
struct Hungarian {
    const T INF = numeric_limits<T>::max()/2;

    int N, M;
    const vector<vector<T>>& aa; // the cost matrix NxM.
    // Instead of having sizes N and M, the sizes are N+1 and M+1.
    // The reason is that we add a fictitious row and column (with indexes N and
    // M) because the algorithm is much shorter in this way.
    vector<T> u, v; // potentials
    // prec stores the matching col->row
    // way is used internally
    vector<int> prec, way;

    // ACTHUNG: It must hold N <= M.
    Hungarian(int N, int M, const vector<vector<T>>& aa):
        N(N), M(M), aa(aa), u(N+1, 0), v(M+1, 0), prec(M+1, N), way(M+1, M) {}    

    // Returns the minimum cost of a maximum matching.
    T GetMinCostMatching() {
        for (int i = 0; i < N; i++) {
            prec[M] = i;
            int j0 = M;
            vector<T> minv (M+1, INF);
            vector<bool> used (M+1, false);

            do {
                used[j0] = true;
                int i0 = prec[j0], j1;
                T delta = INF;
                for (int j = 0; j < M; j++) {
                    if (!used[j]) {
                        T cur = aa[i0][j]-u[i0]-v[j];
                        if (cur < minv[j]) minv[j] = cur,  way[j] = j0;
                        if (minv[j] < delta) delta = minv[j],  j1 = j;
                    }
                }
                for (int j = 0; j <= M; j++) {
                    if (used[j]) u[prec[j]] += delta,  v[j] -= delta;
                    else minv[j] -= delta;
                }
                j0 = j1;
            } while (prec[j0] != N);
            do {
                int j1 = way[j0];
                prec[j0] = prec[j1];
                j0 = j1;
            } while (j0 != M);
        }
        return -v[M];
    }
};

