                            v[j] -= delta ;
                        }
                        else {
                            dist[j] -= delta ;
                        }
                }
                cur_per = nxt_per ;
            }
            while(cur_per) { // Flip the matching
                int prev_per = way[cur_per] ;
                mtch[cur_per] = mtch[prev_per] ;
                cur_per = prev_per ;
            }
    }
    return -v[0];
}
