    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (s[i][j] == 'o') {
                mp[{i, j}] = start++;
                pre_sum += i + j;
            }
        }
    }
    int v = start + n * m + 2;
    mcf_graph<int, int> g(v);
    int a = v - 2, b = v - 1;

    int cost_max = 10000;
    vector<vector<bool>> seen(n, vector<bool>(m));
    auto bfs = [&](int i, int j) {
        seen.assign(n, vector<bool>(m, false));
        queue<pair<int, int>> q;
        q.emplace(i, j);
        seen[i][j] = true;
        g.add_edge(mp[{i, j}], start + m * i + j, 1, 0);
        while (!q.empty()) {
            auto [vi, vj] = q.front();
            q.pop();
            for (int k = 0; k < 2; ++k) {
                int ni = vi + k, nj = vj + (1 - k);
                if (ni >= n || nj >= m) continue;
                if (s[ni][nj] == '#') continue;
