                q.emplace(ni, nj);
                seen[ni][nj] = true;
                g.add_edge(mp[{i, j}], start + m * ni + nj, 1, 0);
            }
        }
    };

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
