            if (s[i][j] == 'o') bfs(i, j);
        }
    }

    for (int i = 0; i < start; ++i) g.add_edge(a, i, 1, 0);

    auto [flow, cost] = g.flow(a, b);
    int ans = -(cost - flow * cost_max);
    ans -= pre_sum;
    cout << ans << '\n';

}

