inline bool spfa(int s,int t){
	memset(vis,0,sizeof(vis));
	memset(pre,-1,sizeof(pre));
	memset(dep,128,sizeof(dep));
	std::queue<int> q;
	q.push(s),dep[s]=0,vis[s]=1;
