int max1(vector<string > &s,int x,int y)
{
	queue<pair<int,pair<int,int> > > q;
	q.push({0,{x,y}});
	int maxx=-1;
	int xf=x,yf=y;
	while(!q.empty())
	{
		pair<int,pair<int,int> > p=q.front();
		q.pop();

		int x1=p.se.fi,y1=p.se.se;
		if(p.fi>maxx)
		{
			maxx=p.fi;
			xf=x1;
			yf=y1;
		}
		else if(p.fi==maxx && x1>xf)
		{
			maxx=p.fi;
			xf=x1;
			yf=y1;
		}
		if(valid(x1+1,y1,n,m) && s[x1+1][y1]!='o' && s[x1+1][y1]!='#')
