#include <atcoder/mincostflow>

int main() {
	int n, m; scanf("%d%d", &n, &m);
	std::vector<std::string> s(n);
	for(int i = 0; i < n; i++) cin >> s[i];

	int offset = n * m;
	auto idx = [&](int i, int j) { return i * m + j; };
	const int S = offset + offset;
	const int T = offset + offset + 1;
	const i64 INF = 1 << 30;

	i64 cnt = 0;
	atcoder::mcf_graph<i64, i64> g(offset * 2 + 2);
	for(int i = 0; i < n; i++) {
		for(int j = 0; j < m; j++) {
			if(s[i][j] == '#') continue;
			if(i + 1 < n and s[i + 1][j] != '#') {
				g.add_edge(idx(i, j), idx(i + 1, j), INF, -1);
			}
			if(j + 1 < m and s[i][j + 1] != '#') {
				g.add_edge(idx(i, j), idx(i, j + 1), INF, -1);
			}
			if(s[i][j] == 'o') {
				g.add_edge(S, idx(i, j), 1, INF);
				cnt++;
			}
			g.add_edge(idx(i, j), T, 1, INF);
		}
	}
	auto [flow, cost] = g.flow(S, T);
	assert(cnt == flow);

	printf("%lld\n", 2 * cnt * INF - cost);
	return 0;
}

