int cal(vector<string>&arr,int i,int j){
    int ans=0;
    vector<vector<int>>dp(arr.size(),vector<int>(arr[i].size(),0));
    dp[i][j]=0;
    int ei=i,ej=j;
    for(int k=i;k<arr.size();k++){
        for(int l=j;l<arr[k].size();l++){
            if(i==k&&j==l)continue;
            else if(i==k&&arr[k][l]=='.'){
                if(l-1==j||dp[k][l-1]!=0){
                    dp[k][l]=dp[k][l-1]+1;
                    if(ans<dp[k][l]){
                        ans=dp[k][l];
                        ei=k;
                        ej=l;
                    }
                }
            }
            else if(j==l&&arr[k][l]=='.'){
                if(k-1==i||dp[k-1][l]!=0){
                    dp[k][l]=dp[k-1][l]+1;
                    if(ans<dp[k][l]){
                        ans=dp[k][l];
                        ei=k;
                        ej=l;
                    }
                }
            }
            else if(arr[k][l]=='.'){
                if(l-1==j||dp[k][l-1]!=0){
                    dp[k][l]=dp[k][l-1]+1;
                    if(ans<dp[k][l]){
                        ans=dp[k][l];
                        ei=k;
                        ej=l;
                    }
                }
                if(k-1==i||dp[k-1][l]!=0){
                    dp[k][l]=dp[k-1][l]+1;
                    if(ans<dp[k][l]){
                        ans=dp[k][l];
                        ei=k;
                        ej=l;
                    }
                }
            }
        }
    }
    swap(arr[i][j],arr[ei][ej]);
    return ans;
}
