constexpr char newl = '\n';
constexpr int INF = 1e9;

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n, m;
    cin >> n >> m;

    vector<string> s(n);
    for (int i = 0; i < n; i++) {
        cin >> s[i];
    }

    int ans = 0;
    for (int hoge = 0; hoge <= n + m - 2; hoge++) {
        for (int i = n - 1; i >= 0; i--) {
            int fuga = hoge - (n - 1 - i);
            if (fuga >= m) continue;
            if (fuga < 0) break;
            int j = m - 1 - fuga;

            if (s[i][j] != 'o') continue;
            vector< vector<int> > memo(n - i, vector<int>(m - j, false));
            memo[0][0] = true;
            int cnt = 0, posi = i, posj = j;
            for (int k = i; k < n; k++) {
                for (int l = j; l < m; l++) {
                    if (s[k][l] != '.') continue;
                    if (k > i && memo[k - 1 - i][l - j]) {
                        memo[k - i][l - j] = true;
                    }
                    if (l > j && memo[k - i][l - 1 - j]) {
                        memo[k - i][l - j] = true;
                    }
                    if (memo[k - i][l - j]) {
                        int tmp = k - i + l - j;
                        if (cnt < tmp) {
                            cnt = tmp;
                            posi = k;
                            posj = l;
                        }
                    }
                }
            }
            ans += cnt;
            s[i][j] = '.';
            s[posi][posj] = '#';
        }
    }
    cout << ans << newl;

    return 0;
}

