char c[51][51];
bool us[51][51];
int id[51][51];

int n, m;
void go(int x, int y) {
    if (us[x][y])
        return;
    us[x][y] = 1;
    if (x + 1 < n && c[x + 1][y] != '#') {
        go(x+1,y);
    }
    if (y + 1 < m && c[x][y + 1] != '#') {
        go(x, y+1);
    }
}

int l[105][105], r[105][105]; // id, diag
bool ban[105][51]; // ban[dd][0 <= pos < n]

vector<int> s[105]; // set of all chosed by d
int ans;

vector<pii> ev;

bool ok(int diag) {
    vector<int> ids = s[diag];
    sort(all(ids), [&](int i, int j){
        return l[i][diag] < l[j][diag];
    });

    int j = 0;
    multiset<int> rs;

    for (int i = 0; i < n; i++) {
        while (j < ids.size() && l[ids[j]][diag] == i) {
            // turn on
            rs.insert(r[ids[j]][diag]);
            j++;
        }
        if (!ban[diag][i]) {
            // close one
            if (rs.size() && *rs.begin() < i) {
                // bad
                return false;
            }
            if (rs.size()) {
                rs.erase(rs.begin());
            }
        }
    }

    return rs.size() == 0;
}

int main() {
    // files1;
    fast_io;

    cin >> n >> m;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> c[i][j];
        }
    }

    int cc = 0;

    memset(l, -1, sizeof(l));
    memset(r, -1, sizeof(r));

    for (int diag = n - 1 + m - 1; diag >= 0; diag--)
        for (int i = 0; i < n; i++){
            int j = diag - i;
            if (j >= 0 && j < m) {
                if (c[i][j] == 'o') {
                    memset(us, 0, sizeof(us));
                    id[i][j] = cc;
                    ev.push_back({i, j});

                    go(i, j);

                    for (int k = 0; k < n; k++)
                        for (int h = 0; h < m; h++) {
                            if (us[k][h]) {
                                int dd = k + h;

                                if (l[cc][dd] == -1) {
                                    l[cc][dd] = k;
                                    r[cc][dd] = k;
                                }

                                l[cc][dd] = min(l[cc][dd], k);
                                r[cc][dd] = max(r[cc][dd], k);
                            }
                        }

                    for (int k = 0; k < n; k++)
                        for (int h = 0; h < m; h++) {
                            if (us[k][h]) {
                                int dd = k + h;

                                if (k >= l[cc][dd] && k <= r[cc][dd] && !us[k][h]) {
                                    ban[dd][k] = 1;
                                }
                            }
                        }

                    cc++;
                }
            }
        }


    // return 0;

    for (int i = 0; i < ev.size(); i++) {
        auto [x, y] = ev[i];
        int diag = x + y;

        bool fnd = 0;
        for (int diag_to = n - 1 + m - 1; diag_to >= diag; diag_to--) {
            if (l[i][diag_to] != -1) {
                s[diag_to].push_back(i);
                if (ok(diag_to)) {
                    ans += diag_to - diag;
                    fnd = 1;
                    break;
                }
                s[diag_to].pop_back();
            }
        }
        assert(fnd);
    }

    cout << ans;
