                vis[cur_per] = true ;
                ll delta = infl ;
                int nxt_per ;
                rep(j,1,m) {
                        if(!vis[j]) {
                            ll val = a[cur_job][j] - u[cur_job] - v[j] ;
                            if(val < dist[j]) {
                                dist[j] = val ;
                                way[j] = cur_per ;
                            }
                            if(dist[j] < delta) {
                                delta = dist[j] ;
                                nxt_per = j ;
                            }
                        }
                }
                rep(j,0,m) {
                        if(vis[j]) {
                            u[mtch[j]] += delta ;
                            v[j] -= delta ;
                        }
                        else {
                            dist[j] -= delta ;
                        }
                }
                cur_per = nxt_per ;
            }
            while(cur_per) { // Flip the matching
                int prev_per = way[cur_per] ;
                mtch[cur_per] = mtch[prev_per] ;
                cur_per = prev_per ;
            }
    }
    return -v[0];
}
