const int MAXV = 10000;
const int MAXE = 1000000;
typedef int flow_type;
typedef int cost_type;
const int MAX_FLOW = oo;
const int MAX_COST = 0x7f7f7f7f;
typedef struct struct_edge *edge;
struct struct_edge {
	int v;
	flow_type c;
	cost_type d;
	edge n, b;
} pool[MAXE];
edge top;
int V = MAXV, S, T;
edge adj[MAXV];
void build_graph(int v, int s, int t) {
	top = pool, clr(adj);
	V = v, S = s, T = t; //点的编号的范围为[0,v),源,汇
	//add_edge(u,v,c,d);
}
void add_edge(int u, int v, flow_type c, cost_type d) {
	top->v = v, top->c = c, top->d = d, top->n = adj[u], adj[u] = top++;
	top->v = u, top->c = 0, top->d = -d, top->n = adj[v], adj[v] = top++;
	adj[u]->b = adj[v], adj[v]->b = adj[u];
	if (u == v)
		adj[u]->n->b = adj[u], adj[v]->b = adj[v]->n;//防止add_edge(u,u,c,d)时出现RE
}
cost_type h[MAXV], d[MAXV];
int q[MAXV];
bool inq[MAXV];
int qh, qt;
edge p[MAXV];
void min_cost_max_flow(flow_type &flow, cost_type &cost,
		bool has_negative_edges = true) {
	if (has_negative_edges) {
		fl(h,MAX_COST), fl(inq, false), qh = 0, qt = -1;
		rep(i,V)
			h[i] = 0, q[++qt] = i, inq[i] = true;
		whl(qh<=qt) {
			int u = q[(qh++) % MAXV];
			inq[u] = false;
			for (edge i = adj[u]; i; i = i->n)
				if (i->c && cmin(h[i->v], h[u] + i->d)) {
					p[i->v] = i;
					if (cmax(inq[i->v], true))
						q[(++qt) % MAXV] = i->v;
				}
		}
	} else
		clr(h);
	lp {
		fl(d,MAX_COST), fl(inq, false);
		prq<pr<cost_type, int> > Q;
		d[S] = 0, p[S] = 0, Q.push(mp(-d[S], S));
		whl(sz(Q)) {
			int u = Q.top().y;
			Q.pop();
			if (cmax(inq[u], true))
				for (edge i = adj[u]; i; i = i->n)
					if (i->c && !inq[i->v]
							&& cmin(d[i->v], d[u] + i->d + h[u] - h[i->v]))
						p[i->v] = i, Q.push(mp(-d[i->v], i->v));
		}
		if (d[T] == MAX_COST)
			break;
		else {
			flow_type delta = MAX_FLOW;
			for (edge i = p[T]; i; i = p[i->b->v])
				cmin(delta, i->c);
			for (edge i = p[T]; i; i = p[i->b->v])
				i->c -= delta, i->b->c += delta, cost += delta * i->d;
			flow += delta;
			rep(i,V)
				h[i] += d[i];
		}
	}
}

int main() {
	int n, m;
	cin >> n >> m;
	vs map(n);
	rep(i,n)
		cin >> map[i];
	build_graph(n * m + 2, n * m, n * m + 1);
	rep(i,n)
		rep(j,m)
		{
			int id = i * m + j;
			if (map[i][j] == 'o') {
				add_edge(S, id, 1, 0);
			}
			if (map[i][j] != '#') {
				add_edge(id, T, 1, 0);
				if (i + 1 < n) {
					add_edge(id, id + m, n * m, -1);
				}
				if (j + 1 < m) {
					add_edge(id, id + 1, n * m, -1);
				}
			}
		}
	int flow = 0, cost = 0;
	min_cost_max_flow(flow, cost);
	cout << -cost << endl;
	prt(flow);
}

