#include <climits>
class MinimumCostFlow
{
private:
	struct Edge
	{
		int to, cap, cost, rev;
		Edge( int t, int c, int d, int r ) : to( t ), cap( c ), cost( d ), rev( r ) {}
	};

	const int V;
	vector< vector<Edge> > G;

public:
	MinimumCostFlow( int v ) : V( v ), G( V ) {};

	void connect( int from, int to, int cap, int cost )
	{
		G[ from ].push_back( Edge( to, cap, cost, G[ to ].size() ) );
		G[ to ].push_back( Edge( from, 0, -cost, G[ from ].size() - 1 ) );
		return;
	}

	int solve( int s, int t, int f )
	{
		int res = 0;
		vector<int> h( V, 0 ), prevv( V ), preve( V );

		while ( 0 < f )
		{
			vector<int> distance( V, INT_MAX );
			distance[s] = 0;

			priority_queue< pair<int,int>, vector< pair<int,int> >, greater< pair<int,int> > > que;
			que.push( make_pair( 0, s ) );

			while ( !que.empty() )
			{
				int d = que.top().first;
				int v = que.top().second;
				que.pop();

				if ( distance[v] < d )
				{
					continue;
				}

				for ( int i = 0; i < (int)G[v].size(); ++i )
				{
					Edge &e = G[v][i];
					if ( 0 < e.cap && distance[v] + e.cost + h[v] - h[ e.to ] < distance[ e.to ] )
					{
						distance[ e.to ] = distance[v] + e.cost + h[v] - h[ e.to ];
						prevv[ e.to ] = v;
						preve[ e.to ] = i;
						que.push( make_pair( distance[ e.to ], e.to ) );
					}
				}
			}

			if ( distance[t] == INT_MAX )
			{
				return -1;
			}

			for ( int i = 0; i < V; ++i )
			{
				h[i] += distance[i];
			}

			int d = f;
			for ( int v = t; v != s; v = prevv[v] )
			{
				d = min( d, G[ prevv[v] ][ preve[v] ].cap );
			}
			f -= d;
			res += d * h[t];
			for ( int v = t; v != s; v = prevv[v] )
			{
				Edge &e = G[ prevv[v] ][ preve[v] ];
				e.cap -= d;
				G[v][ e.rev ].cap += d;
			}
		}

		return res;
	}

	int solve2( const int s, const int t, int f )
	{
		const int INF = INT_MAX / 2;
		int res = 0;

		while ( f > 0 )
		{
			vector<int> dist( V, INF );
			dist[s] = 0;
			vector<int> prevv( V ), preve( V );

			bool update = true;
			while ( update )
			{
				update = false;

				for ( int v = 0; v < V; v++ )
				{
					if ( dist[v] == INF )
					{
						continue;
					}
					for ( int i = 0; i < (int)G[v].size(); i++ )
					{
						Edge &e = G[v][i];
						if ( e.cap > 0 && dist[ e.to ] > dist[v] + e.cost )
						{
							dist[ e.to ] = dist[v] + e.cost;
							prevv[ e.to ] = v;
							preve[ e.to ] = i;
							update = true;
						}
					}
				}
			}

			if ( dist[t] == INF )
			{
				return -1;
			}

			int d = f;
			for ( int v = t; v != s; v = prevv[v] )
			{
				d = min( d, G[ prevv[v] ][ preve[v] ].cap );
			}
			f -= d;
			res += d * dist[t];
			for ( int v = t; v != s; v = prevv[v] )
			{
				Edge &e = G[ prevv[v] ][ preve[v] ];
				e.cap -= d;
				G[v][ e.rev ].cap += d;
			}
		}

		return res;
	}
};
