    mcf_graph<ll, ll> g(2 + cntk + cnts);
    for(int i = 0; i < cntk; ++i) {
        g.add_edge(0, i+1, 1, 0);
    }
    for(int i = 0; i < cnts; ++i) {
        g.add_edge(1+cntk+i, 1+cntk+cnts, 1, 0);
    }
    ll cnt_cntk = 0;
    rep(i, n) rep(j, m) {
        if(s[i][j] != 'o') continue;
        d.assign(n, vll(m, -1));
