//        }
    }
    for(int i = 1; i <= N; ++i){
        for(int j = 1; j <= M; ++j){
            if(arr[i][j] == 'o'){
                now.clear();
                memset(chk, 0, sizeof(chk));
                dfs(i, j);
                for(int k = N + M; k >= 2; --k){
