    for(int i = 0; i < (int)way.size(); ++i){
        int x = (l[i] - 1) / M + 1, y = (l[i] - 1) % M + 1;
        ans += x + y - pos[i].first - pos[i].second;
    }
    printf("%d\n", ans);
    return 0;
}

