pair<int,int > bfs(int x, int y) {
    static int vis[maxn][maxn], T, dep[maxn][maxn];
    ++T;
    queue<pair<int,int>> togo;
	vector<vector<pair<int,int>>> des(maxn << 1);

    togo.emplace(x, y);
	dep[x][y] = 0;

    auto valid = [&](int x, int y) {
        if (x == n || y == m) return false;
        return vis[x][y] < T && w[x][y] != 'o' && w[x][y] != '#';
    };
	int all = 0;
    while (!togo.empty()) {
        auto [x, y] = togo.front();
		des[x+y].pb(x, y);
        togo.pop();
        if (valid(x+1, y)) {
            vis[x+1][y] = T;
            togo.emplace(x+1, y);
        }
        if (valid(x, y+1)) {
            vis[x][y+1] = T;
            togo.emplace(x, y+1);
        }
		all = x + y;
    }
	shuffle(des[all].begin(), des[all].end(), gen);
	return des[all][0];
}
