pair<int,pair<int,int>> position(char** arr,int n,int m, int row, int col, int value){


    pair<int,pair<int,int>> ans;
    if(row>=n || col>=m || arr[row][col]=='o' || arr[row][col]=='#'){
        ans.first=-1;
        ans.second.first=-1;
        ans.second.second=-1;
        return ans;
    }

    pair<int,pair<int,int>> right=position(arr,n,m,row,col+1,value+1);
    pair<int,pair<int,int>> down=position(arr,n,m,row+1,col,value+1);
    if(right.first==-1 && down.first==-1){
        ans.first=value;
        ans.second.first=row;
        ans.second.second=col;
        return ans;
    }else if(right.first!=-1 && down.first==-1){
        return right;
    }else if(right.first==-1 && down.first!=-1){
        return down;
    }else{
        if(right.first>down.first){
            return right;
        }else{
            return down;
        }
    }

}





