        ll y = j + dy[k];
        if(x==n||y==m) continue;
        if(s[x][y]=='#') continue;
        dj.insert(i*m+j, x*m+y, 1);
      }
    }
  }

  for(int i=0;i<d.size();i++) g.add_edge(S, 2502+i, 1LL, 0LL);
  for(int i=0;i<n;i++){
    for(int j=0;j<m;j++){
      if(s[i][j]=='#') continue;
      g.add_edge(i*m+j, T, 1LL, 0LL);
    }
  }

  //各コマについて、各空きマスに辺を伸ばす
  for(int i=0;i<d.size();i++){
    ll x = d[i][0], y = d[i][1];
    dj.dijkstra(x*m+y);
    for(int j=0;j<n;j++){
      for(int k=0;k<m;k++){
        if(s[j][k]=='#') continue;
        ll dist = dj[j*m+k];
        if(dist==dj.INF) continue;
        g.add_edge(2502+i, j*m+k, 1, 1000000-dist);//dist回移動できる
      }
    }
  }
  ll L = g.flow(S, T, cnt).second - 1000000LL * cnt;
  std::cout << -L << '\n';
}

