template<typename T> struct HashMap2D {
	HashMap2D() {
		Hmax = 1000000007, Hmin = -1000000007;
		Wmax = 1000000007, Wmin = -1000000007;
		Height = Hmax - Hmin;
		Width = Wmax - Wmin;
	}
	HashMap2D(T H_max, T W_max, T H_min = 0, T W_min = 0) {
		Hmax = H_max; Hmin = H_min;
		Wmax = W_max; Wmin = W_min;
		Height = Hmax - Hmin;
		Width = Wmax - Wmin;
	}
	T hash(T h, T w) {
		h -= Hmin, w -= Wmin;
		return Width * h + w;
	}
	pair<T, T> inv(T index) {
		pair<T, T> p;
		p.first = index / Width;
		p.second = index % Width;
		p.first += Hmin;
		p.second += Wmin;
		return p;
	}

private:
	T Hmax, Hmin, Wmax, Wmin;
	T Height, Width;
};

