int cnt=1,h[3005],dis[3005],pre[3005],inq[3005],S,T,N,tot,id[55][55];
struct Edge {
	int to,next,flow,cost;
} e[1000005];
void Add_Edge(int x,int y,int z,int w) {
	e[++cnt]=(Edge) {y,h[x],z,w};
	h[x]=cnt;
	e[++cnt]=(Edge) {x,h[y],0,-w};
	h[y]=cnt;
}
bool SPFA(int s,int t) {
	memset(inq,0,sizeof(inq));
	memset(pre,0,sizeof(pre));
	memset(dis,0xc0,sizeof(dis));
	queue<int> q;
	q.push(s),inq[s]=1,dis[s]=0;
	while(!q.empty()) {
		int now=q.front();
		q.pop(),inq[now]=0;
		for(int i=h[now]; i; i=e[i].next) {
			if(!e[i].flow)continue;
			int y=e[i].to;
			if(dis[y]<dis[now]+e[i].cost) {
				dis[y]=dis[now]+e[i].cost,pre[y]=i;
				if(!inq[y])q.push(y),inq[y]=1;
			}
		}
	}
	return dis[t]>-1e9;
}
int Adjust(int t,int s) {
	int dlt=1e9;
	for(int i=t; i!=s; i=e[pre[i]^1].to)dlt=min(dlt,e[pre[i]].flow);
	for(int i=t; i!=s; i=e[pre[i]^1].to)e[pre[i]].flow-=dlt,e[pre[i]^1].flow+=dlt;
	return dlt*dis[t];
}
int EK(int s,int t) {
	int ret=0;
	while(SPFA(s,t))ret+=Adjust(t,s);
	return ret;
}
