#define WALL '#'
#define PATH '.'
#define PIECE 'o'

void chmax(ll &a, ll b){if(a<b) a=b;}

inline int solve(){
    atcoder::mcf_graph<ll, ll> graph(N*M+10);
    int s = N*M+2, t = N*M+3;
    ll INF = 1e6;
    vector<pii> Ps;
    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j < M; j++)
        {
            if(S[i][j]==PIECE){
                int to = M*i+j;
                Ps.emplace_back(i, j);
                graph.add_edge(s, to, 1, 0);
            }
            else if(S[i][j]==PATH){
                int to = M*i+j;
                graph.add_edge(to, t, 1, 0);
            }
        }
    }

    ll K = Ps.size();
    for (int k = 0; k < K; k++)
    {
        int x = Ps[k].first;
        int y = Ps[k].second;
        vector<vector<ll>> dist(N,vector<ll>(M,-INF));
        dist[x][y] = 0;
        for (int i = x; i < N; i++)
        {
            for (int j = y; j < M; j++)
            {
                if(S[i][j]==WALL) continue;
                if(i>=1 && dist[i-1][j]>=0) chmax(dist[i][j], dist[i-1][j] + 1);
                if(j>=1 && dist[i][j-1]>=0) chmax(dist[i][j], dist[i][j-1] + 1);
            }
        }
        for (int i = x; i < N; i++)
        {
            for (int j = y; j < M; j++)
            {
                if(S[i][j]==WALL) continue;
                if(S[i][j]==PIECE) continue;
                if(dist[i][j]==-INF) continue;
                graph.add_edge(x*M+y, i*M+j, 1, INF - dist[i][j] );
            }
        }
    }
    graph.add_edge(s, t, K, INF);
    ll  cap,cost;
    tie(cap,cost) = graph.flow(s, t, K);
    cout << (K*INF - cost) << endl;    
    return 0;
}   

int main()
{
    input();
    solve();
    return 0;
}

