	if (viss[ax][ay][bx][by]) return ok[ax][ay][bx][by]; viss[ax][ay][bx][by] = 1;
	if (F(ax+1,ay,bx,by)) return ok[ax][ay][bx][by] = 1;
	if (F(ax,ay+1,bx,by)) return ok[ax][ay][bx][by] = 1;
	return 0;
} 
int S,T,cntv,ans,INF = 100000000;

int dis[V],inq[V],Fr[V]; queue<int>Q;
inline bool spfa(){
	int i,p,x,y;
	for (i = 1; i <= cntv; ++i) dis[i] = INF;
	dis[S] = 0,Q.push(S); inq[S] = 1;
	while (!Q.empty()){
		x = Q.front(),Q.pop(); inq[x] = 0;
		for (p = He[x]; p ; p = Ne[p]) if (dis[y=To[p]] > dis[x] + Cost[p] && Flow[p]){
			dis[y] = dis[x] + Cost[p],Fr[y] = p; if (!inq[y]) inq[y] = 1,Q.push(y);
		}
	}
	return dis[T] < INF; 
}
inline void getnow(){
	memcpy(Now,He,cntv+1<<2);
}
int vis[V];
inline int DFS(int x,int flow){
	if (x == T || !flow) return flow;
	if (vis[x]) return 0; vis[x] = 1;
	int rest = flow,p,y,f;
	for (p = Now[x]; p ; p = Ne[p]){
		Now[x] = p;
		if (dis[y=To[p]] == dis[x] + Cost[p] && Flow[p]){
			f = DFS(y,min(rest,Flow[p]));
			Flow[p] -= f,Flow[p^1] += f,rest -= f;
			if (!rest) return flow;
		}
	}
	return flow - rest;
}
inline void work(){
	int f,x,p;
	while (spfa()){
		f = 10000;
		x = T;
		while (x ^ S) f = min(f,Flow[Fr[x]]),x = Frr[Fr[x]];
		ans += f * dis[T];
		x = T;
		while (x ^ S){
			p = Fr[x];
			Flow[p] -= f,Flow[p^1] += f;
			x = Frr[p];
		}
	//	cerr << f << ' ' << dis[T] << '\n';
	}
}
