const int N = 102;
const int M = 2505;
int n, m, k;
char s[N][N];
int a[N][2];
vector<int> g[M];
bool dp[N][N];
bool used[M];
int mt[N];
pii ord[M];
int sz;

bool dfs(int x) {
	if (used[x]) return false;
	used[x] = 1;
	for (int y : g[x]) {
		if (mt[y] == -1) {
			mt[y] = x;
			return true;
		}
	}
	for (int y : g[x]) {
		if (dfs(mt[y])) {
			mt[y] = x;
			return true;
		}
	}
	return false;
}

int main()
{
	startTime = clock();
//	freopen("input.txt", "r", stdin);
//	freopen("output.txt", "w", stdout);

	scanf("%d%d", &n, &m);
	for (int i = 0; i < n; i++) {
		scanf("%s", s[i]);
		for (int j = 0; j < m; j++) {
			if (s[i][j] == 'o') {
				a[k][0] = i;
				a[k][1] = j;
				k++;
				s[i][j] = '.';
			}
		}
	}
	for (int it = 0; it < k; it++) {
		for (int i = 0; i < n; i++)
			for (int j = 0; j < m; j++)
				dp[i][j] = 0;
		dp[a[it][0]][a[it][1]] = 1;
		for (int i = 0; i < n; i++)
			for (int j = 0; j < m; j++) {
				if (i + 1 < n && s[i + 1][j] != '#')
					dp[i + 1][j] |= dp[i][j];
				if (j + 1 < m && s[i][j + 1] != '#')
					dp[i][j + 1] |= dp[i][j];
			}
		for (int i = 0; i < n; i++)
			for (int j = 0; j < m; j++) {
				if (dp[i][j])
					g[i * m + j].push_back(it);
			}
	}
	for (int i = 0; i < n; i++)
		for (int j = 0; j < m; j++)
			ord[sz++] = mp(i + j, i * m + j);
	sort(ord, ord + sz);
	reverse(ord, ord + sz);
	for (int i = 0; i < k; i++)
		mt[i] = -1;
	int ans = 0;
	for (int i = 0; i < sz; i++) {
		if (dfs(ord[i].second)) {
			ans += ord[i].first;
			for (int j = 0; j < sz; j++)
				used[j] = 0;
		}
	}
	for (int i = 0; i < k; i++)
		for (int j = 0; j < 2; j++)
			ans -= a[i][j];
	printf("%d\n", ans);

	return 0;
}

