    const int S = m * n, T = m * n + 1;
    int idx = m * n + 2;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            if (s[i][j] == '#') continue;
            G.add_edge(i * m + j, T, 1, 0);
            if (s[i][j] == 'o') {
                G.add_edge(S, idx, 1, 0);
                int dist[n][m];
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < m; j++) dist[i][j] = -1;
                queue<pair<int, int> > q;
                q.push({i, j});
                dist[i][j] = 0;
                while (!q.empty()) {
                    auto [x, y] = q.front();
                    const int d = dist[x][y];
                    q.pop();
                    G.add_edge(idx, x * m + y, 1, M - d);
                    const int dx[] = {0, 1}, dy[] = {1, 0};
                    for (int k = 0; k < 2; k++) {
                        const int x1 = x + dx[k], y1 = y + dy[k];
