struct Z{
  ll y;
  ll x;
  ll depth;
};

ll H, W, K, y, x, depth, xs, ys, xg, yg, block = 10000;
vector<ll> y_vec = {-1, 0};
vector<ll> x_vec = {0, -1};
vector<ll> y_vec2 = {1, 0};
vector<ll> x_vec2 = {0, 1};
vector<vector<ll>> A, B, C;
vector<vector<bool>> D;
queue<Z> Q;


void bfs2(int flag){
  while(!Q.empty()){
    Z now = Q.front(); Q.pop();
    y = now.y, x = now.x, depth = now.depth;
    for(ll i=0; i<2; i++){
      Z next={y + y_vec2[i], x + x_vec2[i], depth + 1};
      if (A[next.y][next.x] == -1) continue;
      if (D[next.y][next.x]) continue;
      C[next.y][next.x] + flag;
      D[next.y][next.x] = true;
      Q.push(next);
//cout << " d:" << next.depth << endl;          
    }
  }
}

ll bfs(){
  ll keep = 0, point = 0, px=0, py=0;
  while(!Q.empty()){
    Z now = Q.front(); Q.pop();
    y = now.y, x = now.x, depth = now.depth;
    if(A[y][x] == block){
      if (keep < C[y][x]){
        point = C[y][x] * depth;
        keep = C[y][x];
        px = x;
        py = y;
      }
    }
    for(ll i=0; i<2; i++){
      Z next={y + y_vec[i], x + x_vec[i], depth + 1};
      if(B[next.y][next.x] == -1) continue;
      if(B[next.y][next.x] <= next.depth) continue;
      B[next.y][next.x] = next.depth;
      Q.push(next);
//cout << " d:" << next.depth << endl;          
    }
  }
  if (keep > 0){
    A[py][px] = oo;
    D.assign(H+2, vector<bool>(W+2, false));    
    Z st = {py, px, 0};
    Q.emplace(st);
    bfs2(-1);
  }
  return point;
}


//A[y][x], A(x,y)として管理
int main(){
  cin.tie(0);
  ios::sync_with_stdio(0);  
  cin >> H >> W;
  string S;  
  A.assign(H+2, vector<ll>(W+2, -1));
  vector<pair<ll, ll>> pos;
  for(int i=1; i<=H; i++){
    cin >> S;    
    for(int j=1; j<=W; j++){
      if (S[j-1] == '#') continue;
      if (S[j-1] == 'o'){
        A[i][j] = block;
        pos.push_back({i, j});
        continue;
      }
      A[i][j] = oo;
    }
  }
  ll pl = pos.size(), ans = 0;
  C.assign(H+2, vector<ll>(W+2, 0));
  rep(i, pl){
    D.assign(H+2, vector<bool>(W+2, false));
    xs = pos[i].second;
    ys = pos[i].first;
    C[ys][xs]++;
    Z start = {ys, xs, 0};
    Q.emplace(start);
    bfs2(1);
  }
  for(int k = H + W; k >= 2; k--){
    for(int i = H; i > 0; i--){
      int j = k - i;
      if (j > W)
        break;
      if (j <= 0)
        continue;
      B = A;
      xs = j;
      ys = i;
      if (A[ys][xs] == -1)
        continue;
      if (A[ys][xs] == block)
        continue;
//cout << "i:"<<i<<" j:"<<j<<endl;
      B[ys][xs] = 0;//探索開始
      Z start = {ys, xs, 0};
      Q.emplace(start);
      ll tmp = bfs();
      if(tmp > 0){
//cout << tmp << endl;
        A[ys][xs] = block;    
        ans += tmp;
      }
    }
  }
  cout << ans << endl;
}

