            {
                dis[e[i].to] = dis[now] + e[i].cost;
                if (!in[e[i].to])
                {
                    in[e[i].to] = true;
                    que.push(e[i].to);
                }
            }
        }
    }
    return dis[t] != -INF;
}
int dfs(int now, int v)
{
    // cout << now << ' ' << v << ' ' << sta << endl;
    if (now == t)
    {
        ans += v;
        return v;
    }
    in[now] = true;
    int res = 0;
    for (int i = NOW[now]; i && v; i = e[i].nxt)
    {
        NOW[now] = i;
        if (!in[e[i].to] && e[i].cap && dis[now] + e[i].cost == dis[e[i].to])
        {
            int tmp = dfs(e[i].to, min(v, e[i].cap));
            e[i ^ 0].cap -= tmp;
            e[i ^ 1].cap += tmp;
            v -= tmp;
            res += tmp;
            cost += e[i].cost * tmp;
        }
    }
    in[now] = false;
    return res;
}
