        dp[i][j]={x,y};
        return;
    }
    if(!valid(i+1,j))
    {
        int x1,y1;
        fun(i,j+1,grid,x1,y1);
        if(x1!=-1)
        {
            x=x1;
            y=y1;
        }
        else
        {
            x=i;
            y=j;
        }
        dp[i][j]={x,y};
            return ;
    }
    if(!valid(i,j+1))
    {
        int x1,y1;
        fun(i+1,j,grid,x1,y1);
        if(x1!=-1)
        {
            x=x1;
            y=y1;
        }
        else
        {
            x=i;
            y=j;
        }
        dp[i][j]={x,y};
            return ;
    }
    int x1,y1;
    fun(i+1,j,grid,x1,y1);
    int x2,y2;
    fun(i,j+1,grid,x2,y2);
    if(x1 == -1 && x2==-1)
    {
        x=i;
        y=j;
        dp[i][j]={x,y};
        return;
    }
    if(x1==-1)
    {
        x=x2;
        y=y2;
        dp[i][j]={x,y};
        return;
    }
    if(x2==-1)
    {
        x=x1;
        y=y1;
        dp[i][j]={x,y};
        return;
    }
    int d1=abs(x1-i)+abs(y1-j),d2=abs(x2-i)+abs(y2-j);
    if(d1>d2)
    {
        x=x1;
        y=y1;
    }
    else
    {
        x=x2;
        y=y2;
    }
    dp[i][j]={x,y};
    return; 
}

