const int N = 105, M = 105, inf = N * M;

struct edge {
	int to, nxt, cap, cost;
} g[N * M * 10];
int n, m, s, t, head[N * M * 10], cnt = 0;
char str[N][M];
void addedge(int u, int v, int cap, int cost) {
	edge e = {v, head[u], cap, cost};
	g[head[u] = cnt++] = e;
}

queue<int> que;
int par[N * M * 10], dist[N * M * 10], path[N * M * 10];
bool vis[N * M * 10];
bool spfa() {
	for (int i = s; i <= t; i++) vis[i] = false, dist[i] = -inf;
	dist[s] = 0, vis[s] = true, que.push(s);
	while (!que.empty()) {
		int u = que.front();
		for (int i = head[u]; ~i; i = g[i].nxt) {
			int v = g[i].to;
			if (g[i].cap && dist[v] < dist[u] + g[i].cost) {
				dist[v] = dist[u] + g[i].cost;
				par[v] = u, path[v] = i;
				if (!vis[v]) vis[v] = true, que.push(v);
			}
		}
		vis[u] = false, que.pop();
	}
	return dist[t] > -inf;
}

int id(int x, int y) {
	return x * m + y;
}
int main() {
	scanf("%d%d", &n, &m);
	for (int i = 0; i < n; i++) scanf("%s", str[i]);

	s = 0, t = n * m + 1;
	for (int i = s; i <= t; i++) head[i] = -1;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (str[i][j] == 'o') {
				addedge(s, id(i, j) + 1, 1, 0);
				addedge(id(i, j) + 1, s, 0, 0);
			}
			if (str[i][j] != '#') {
				addedge(id(i, j) + 1, t, 1, 0);
				addedge(t, id(i, j) + 1, 0, 0);
			}
		}
	}
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m - 1; j++) {
			if (str[i][j] != '#' && str[i][j + 1] != '#') {
				addedge(id(i, j) + 1, id(i, j + 1) + 1, inf, 1);
				addedge(id(i, j + 1) + 1, id(i, j) + 1, 0, -1);
			}
		}
	}
	for (int i = 0; i < n - 1; i++) {
		for (int j = 0; j < m; j++) {
			if (str[i][j] != '#' && str[i + 1][j] != '#') {
				addedge(id(i, j) + 1, id(i + 1, j) + 1, inf, 1);
				addedge(id(i + 1, j) + 1, id(i, j) + 1, 0, -1);
			}
		}
	}
	int ans = 0;
	while (spfa()) {
		ans += dist[t];
		for (int i = t; i != s; i = par[i]) g[path[i]].cap--, g[path[i] ^ 1].cap++;
	}
	printf("%d\n", ans);
	return 0;
}

