		for(int p=0;p<m;p++){
			if(arr[e][p]=='o'){
				memset(vis,0,sizeof(vis));
				int tot = 0;
				vector<pair<int,pi> > v;
				vis[e][p] = 1;
				v.push_back(mk(0,mk(e,p)));
				for(int y=e;y<n;y++){
					for(int x=p;x<m;x++){
