						if(arr[y][x]=='#') continue;
						bool suc = false;
						if(y>e&&vis[y-1][x]) suc = true;
						if(x>p&&vis[y][x-1]) suc = true;
						if(!suc) continue;
						vis[y][x] = 1;
						nn[num][y][x] = abs(y-e) + abs(x-p);
						v2[y*m+x].push_back(num);
						v.push_back(mk(abs(y-e)+abs(x-p),mk(y,x)));
						tot++;
