		int mx = -1,wh=-1;
		for(int p=1;p<num;p++){
			if(ck2[p]) continue;
			if(sz(s[p])==lim){
				set<pair<int,pi> >::iterator it = s[p].begin();
				int vv = -it->x;
				if(vv>mx){
					mx = vv;
					wh = p;
				}
			}
		}
		if(mx==-1) break;
		ck2[wh] = 1;
		ans += mx;
		set<pair<int,pi> >::iterator it = s[wh].begin();
		int y = it->y.x;
		int x = it->y.y;
		for(int p=0;p<sz(v2[y*m+x]);p++){
