        rep(i, max(0, s - (m - 1)), min(n - 1, s) + 1) {
            int j = s - i;
            assert(j >= 0 && j < m);
            ccc++;
            if (a[i][j] == '#') {
                continue;
            }
            fill(used.begin(), used.end(), false);
            dfs(i * m + j);
        }
    }
    assert(ccc == n * m);
    int ans = 0;
    rep(i, 0, c) {
        assert(mt[i] != -1);
        ans += mt[i] / m + mt[i] % m;
    }
    rep(i, 0, n) {
        rep(j, 0, m) {
            if (a[i][j] == 'o') {
                ans -= i;
                ans -= j;
            }
        }
    }
    cout << ans << "\n";
    return 0;
}

