const int KOMA = 100;

int main() {
    int h, w;
    cin >> h >> w;
    vector<string> ban(h);
    for (int i = 0; i < h; i++)cin >> ban[i];

    mf_graph<int> flow(1 + KOMA + h * w + 1);
    for (int i = 1; i <= KOMA; i++) flow.add_edge(0, i, 1);

    int next = 0, ret = 0;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (ban[i][j] == 'o') {
                ret -= i + j;

                vector<vector<bool>> dp(h, vector<bool>(w));
                dp[i][j] = true;
                for (int k = 0; k < h; k++) {
                    for (int l = 0; l < w; l++) {
                        if (ban[k][l] == '#')continue;
                        if (k > 0 && dp[k - 1][l])dp[k][l] = true;
                        if (l > 0 && dp[k][l - 1])dp[k][l] = true;

                        if (dp[k][l])flow.add_edge(1 + next, 1 + KOMA + k * w + l, 1);
                    }
                }

                next++;
            }
        }
    }

    int prevAmount = 0;
    for (int sum = (h - 1) + (w - 1); sum >= 0; sum--) {
        for (int i = 0; i < h; i++) {
            int j = sum - i;
            if (j < 0 || w <= j)continue;

            int tmp = flow.add_edge(1 + KOMA + i * w + j, 1 + KOMA + h * w, 1);

            if (flow.flow(0, 1 + KOMA + h * w) != prevAmount)ret += i + j;
            else flow.change_edge(tmp, 0, 0);
        }
    }

    cout << ret << endl;
    return 0;
}

