    ll V = h * w + 2;
    int s = V - 2, t = V - 1;
    mcf_graph<int, int> mcf(V);
    int koma_num = 0;
    vector<string> a(h);
    rep (i, h) cin >> a[i];

    ll sub = 0;
    int ma = 300;
    rep (i, h) {
        rep (j, w) {
            if (a[i][j] == '#') continue;
            int u = i * w + j;
            if (i != h - 1) {
                if (a[i + 1][j] != '#') {
                    int v = (i + 1) * w + j;
                    mcf.add_edge(u, v, inf, 0);
                }
            }
            if (j != w - 1) {
                if (a[i][j + 1] != '#') {
                    int v = i * w + j + 1;
                    mcf.add_edge(u, v, inf, 0);
                }
            }
            if (a[i][j] == 'o') {
                mcf.add_edge(s, u, 1, 0);
                koma_num++;
                sub += i + j;
            }
            mcf.add_edge(u, t, 1, ma - (i + j));
        }
    }

    pii res = mcf.flow(s, t);
    assert(res.first == koma_num);
    int dist = koma_num * ma - res.second;
