				y=a[k].y;
				if(a[k].c&&d[x]+a[k].d>d[y]) {
					d[y]=d[x]+a[k].d;
					pre[y]=k^1;
					if(!vis[y]) {
						q[r++]=y;
						if(r==N*N) r=1;
					}
				}
			}
		}
		if(!pre[ed]) return ;
		ans += d[ed]; int x=ed,k;
		while(x^st) {
			k=pre[x];
			a[k].c++;
			a[k^1].c--;
			x=a[k].y;
		}
	}
}

void solve() {
	qr(n); qr(m); st=n*m+1; ed=st+1;
	for(int i=1;i<=n;i++) scanf("%s",s[i]+1);
	for(int i=1;i<=n;i++)
		for(int j=1;j<=m;j++) {
			if(s[i][j]!='#') {
