				if(j<m&&s[i][j+1]!='#') add(id(i,j),id(i,j+1),inf,1);
				add(id(i,j),ed,1,0);
				if(s[i][j]=='o') add(st,id(i,j),1,0);
			}
		}
	EK(); pr2(ans);
}

