#endif

    int n, m;
    cin >> n >> m;
    for (int i = 0; i <= n + 1; i++) {
        for (int j = 0; j <= m + 1; j++) {
            a[i][j] = '#';
        }
    }
    vector<pii> pos;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            cin >> a[i][j];
            if (a[i][j] == 'o') {
                pos.pb({i, j});
            }
        }
    }
    int k = pos.size();
    int src = 0, tar = k + n * m + 1;
    mcSFlow f(n * m + k + 2, src, tar);
    for (int i = 1; i <= k; i++) {
        f.add_edge(src, i, 1, 0);
    }
    for (int i = k + 1; i <= k + n * m; i++) {
        f.add_edge(i, tar, 1, 0);
    }
    for (int l = 0; l < k; l++) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                dp[i][j] = 0;
            }
