            for (int j = 1; j <= m; j++) {
                if (a[i][j] != '#') {
                    dp[i][j] |= dp[i - 1][j] | dp[i][j - 1];
                    if (dp[i][j]) {
                        f.add_edge(l + 1, k + (i - 1) * m + j, 1, - (i - pos[l].F) - (j - pos[l].S));
                    }
                }
            }
        }
    }
    pair<ll, ll> ans = f.minCostMaxFlow();
    cout << -ans.S << "\n";

#ifdef LOCAL
    cerr << "\nTime elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << " s.\n";
#endif
    return 0;
}

