}
node dis(int x,int y,node a,node b){
	if(find(x,y,a)<=find(x,y,b))return b;
	return a;
}
void turn(int a,int b,node c){
	for(int i=n;i>=a;i--){
		if(i==a){
			for(int j=m;j>=b;j--){
				if(fl[i][j]){
					f[i][j].x=i;
					f[i][j].y=j;
					if(fl[i+1][j])f[i][j]=dis(i,j,f[i][j],f[i+1][j]);
					if(fl[i][j+1])f[i][j]=dis(i,j,f[i][j],f[i][j+1]);
				}
			}
		}else{
			for(int j=m;j>=1;j--){
				if(fl[i][j]){
					f[i][j].x=i;
					f[i][j].y=j;
					if(fl[i+1][j])f[i][j]=dis(i,j,f[i][j],f[i+1][j]);
					if(fl[i][j+1])f[i][j]=dis(i,j,f[i][j],f[i][j+1]);
