using namespace std;
const int N = 55;
int n, m, idx, res;
char g[55][55];
struct pt
{
	int x, y;
	pt(){}
	pt(int xx, int yy)
	{
		x = xx, y = yy;
	}
	bool operator <(const pt& s)
	{
		return x + y > s.x + s.y;
	}
} p[105];

pair<int, int> q[2550];
int st[55][55];
void bfs(int sx, int sy)
{
	static const int dx[2] = {0, 1}, dy[2] = {1, 0};
	int hh = 0, tt = 0, tx, ty;
	q[0] = {sx, sy};
	memset(st, 0, sizeof st);
	st[sx][sy] = 1;
	while(hh <= tt)
	{
		int x = q[hh].first, y = q[hh++].second;
		tx = x, ty = y;
		for(int i = 0; i < 2; ++i)
		{
			int a = x + dx[i], b = y + dy[i];
			if(a >= n || b >= m) continue;
			if(g[a][b] == '#') continue;
			if(st[a][b]) continue;
			st[a][b] = st[x][y] + 1;
			q[++tt] = {a, b};
		}
	}
	res += st[tx][ty] - 1;
	g[sx][sy] = '.';
	g[tx][ty] = '#';
}

int main()
{
	scanf("%d%d", &n, &m);
	for(int i = 0; i < n; ++i) scanf("%s", g[i]);
	for(int i = 0; i < n; ++i)
		for(int j = 0; j < m; ++j) if(g[i][j] == 'o')
			p[idx++] = pt(i, j);
	sort(p, p + idx);
	for(int i = 0; i < idx; ++i)
		bfs(p[i].x, p[i].y);
	printf("%d", res);
