namespace mcmf {

const intF infF = 1e9;
const intW infW = 1e9;

struct E { int nxt, v; intW w; intF f; } e[M]; int eh[N], ec;
int s, t, nc;
int cur[N];
queue<int> q; 
bool inq[N]; 
intW dis[N];

void clear (int n) { fill_n(eh + 1, nc = n, ec = -1); }

void adde (int u, int v, intW w, intF f) {
  e[++ ec] = { eh[u], v, w, f }; eh[u] = ec;
  e[++ ec] = { eh[v], u, - w, 0 }; eh[v] = ec;
}

bool spfa (void) {
  fill_n(dis + 1, nc, - infW); dis[s] = 0;
  q.push(s); inq[s] = 1;
  while (!q.empty()) {
    int u = q.front(); q.pop(); inq[u] = 0;
    for (int i = eh[u], v; ~ i; i = e[i].nxt) if (e[i].f > 0 && dis[v = e[i].v] < dis[u] + e[i].w) {
      dis[v] = dis[u] + e[i].w;
      if (!inq[v]) { q.push(v); inq[v] = 1; }
    }
  }
  return dis[t] != - infW;
}

intF dfs (int u, intF f) {
  if (u == t) return f;
  intF sf = 0; 
  inq[u] = 1;
  for (int & i = cur[u]; ~ i; i = e[i].nxt) if (e[i].f > 0 && dis[e[i].v] == dis[u] + e[i].w && !inq[e[i].v]) {
    intF df = dfs(e[i].v, min(f, e[i].f));
    sf += df; e[i].f -= df; e[i ^ 1].f += df; f -= df;
    if (f == 0) break;
  }
  inq[u] = 0; 
  return sf;
}

pair<intW, intF> mcmf (int _s, int _t, intF f = infF) {
  s = _s, t = _t;

  intW sc = 0; intF sf = 0, df;
  while (spfa()) {
    for (int i = 1; i <= nc; i ++)
      cur[i] = eh[i];
    df = dfs(s, f - sf);
    sc += df * dis[t];
    sf += df;
  }
  return { sc, sf };
}

};

