    for (int i = 1; i <= ball; ++i)
        g.add_edge(0, i, 1, 0);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            int idx = ball + i * m + j + 1;
            g.add_edge(idx, nodes - 1, 1, 0);
        }
    int ball_idx = 1;
    for (int i = 0; i < n; ++i)
