struct edge { int to, cap, cost, rev, id; };

class Graph
{
public:
    int N;
    vector<vector<edge>> G;
    vec h, dist, prevv, preve;

    Graph(int N): N(N){
        G.resize(N);
        h.resize(N);
        dist.resize(N);
        prevv.resize(N);
        preve.resize(N);
    }

    void add_Directed_edge(int from, int to, int cap, int cost, int id = -1){
        G[from].push_back((edge){to, cap, cost, (int)G[to].size(), -1});
        G[to].push_back((edge){from, 0, -cost, (int)G[from].size() - 1, id});
    }

    //無理なら-1返す
    int min_cost_flow(int s, int t, int f){
        int res = 0;
        fill(all(h), 0);
        while(f > 0){
            priority_queue<Pii, vector<Pii>, greater<Pii>> que;
            fill(all(dist), INF);
            dist[s] = 0;
            que.push(Pii(0, s));
            while(!que.empty()){
                Pii p = que.top(); que.pop();
                int v = p.second;
                if(dist[v] < p.first) continue;
                REP(i, G[v].size()){
                    edge &e = G[v][i];
                    if(e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]){
                        dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        que.push(Pii(dist[e.to], e.to));
                    }
                }
            }
            if(dist[t] == INF) return -1;
            REP(v, N) h[v] += dist[v];

            int d = f;
            for(int v = t; v != s; v = prevv[v]){
                d = min(d, G[prevv[v]][preve[v]].cap);
            }
            f -= d;
            res += d * h[t];
            for(int v = t; v != s; v = prevv[v]){
                edge &e = G[prevv[v]][preve[v]];
                e.cap -= d;
                G[v][e.rev].cap += d;
            }
        }
        return res;
    }

    //実際の流量を求める
    vector<int> calc_flow(int num_id){
        vector<int> flow(num_id, 0);
        REP(v, N) for(auto e: G[v]) if(e.id >= 0 && e.id < num_id) flow[e.id] = e.cap;
        return flow;
    }
};

signed main(){

    int N, M; cin >> N >> M;
    vector<string> S(N); cin >> S;

    Graph G(2 * N * M + 2);
    int s = 2 * N * M, t = s + 1;

    int n_o = 0;
    const int MM = 10000;

    REP(i, N) REP(j, M) if(S[i][j] == 'o'){

        G.add_Directed_edge(s, i * M + j, 1, 0);

        mat dp(N, vec(M, INF));
        dp[i][j] = 0;
        v_Pii cand;
        cand.pb(Pii(0, i * M + j));
        FOR(x, i, N) FOR(y, j, M) if(dp[x][y] < INF){
            if(x + 1 < N && S[x + 1][y] != '#' && dp[x + 1][y] == INF){
                dp[x + 1][y] = dp[x][y] + 1;
                cand.pb(Pii(dp[x + 1][y], (x + 1) * M + y));
            }
            if(y + 1 < M && S[x][y + 1] != '#' && dp[x][y + 1] == INF){
                dp[x][y + 1] = dp[x][y] + 1;
                cand.pb(Pii(dp[x][y + 1], x * M + y + 1));
            }
        }
        Sort(cand); Reverse(cand);
        //vdebug(cand);
        int num = min(SZ(cand), 100LL);
        REP(k, num) G.add_Directed_edge(i * M + j, cand[k].se + N * M, 1, MM - cand[k].fi);

        n_o++;
    }
    REP(i, N) REP(j, M) G.add_Directed_edge(i * M + j + N * M, t, 1, 0);

    int f = G.min_cost_flow(s, t, n_o);
    int ans = MM * n_o - f;
    Out(ans);

    return 0;
}

