void solver() {
    int n = input(), m = input();

    auto ss = make_vector(n, m, '.');
    for (auto &s: ss) for (auto &c: s) cin >> c;

    int S = 2 * n * m;
    int T = 2 * n * m + 1;
    mcf_graph< i64, i64 > G(2 * n * m + 2);

    auto to_idx = [m](int i, int j) {
        return i * m + j;
    };

    range(i, 0, n) range(j, 0, m) {
        if (ss[i][j] == 'o') {
            G.add_edge(S, to_idx(i, j), 1, 0);
        }

        G.add_edge(to_idx(i, j) + n * m, T, 1, 0);
    }

    auto add_edge = [&](int y, int x) {
        int u = to_idx(y, x);

        auto ds = make_vector(n, m, inf);
        ds[y][x] = 0;
        queue< pair< int, int > > que;
        que.emplace(y, x);

        vector< bool > used(n * m, false);

        while (!que.empty()) {
            int i, j;
            tie(i, j) = que.front();
            que.pop();

            if (used[to_idx(i, j)]) continue;
            used[to_idx(i, j)] = true;

            int v = to_idx(i, j) + n * m;
            i64 cost = inf - abs(y - i) - abs(x - j);
            G.add_edge(u, v, 1, cost);

            if (i + 1 < n && ss[i + 1][j] != '#') {
                que.emplace(i + 1, j);
            }
            if (j + 1 < m && ss[i][j + 1] != '#') {
                que.emplace(i, j + 1);
            }
        }

        range(i, 0, n) range(j, 0, m) {
            if (ss[i][j] != 'o') continue;
            if (ds[i][j] == inf) continue;
            int u = to_idx(i, j);
            int v = to_idx(y, x) + n * m;
            int cost = inf - ds[i][j];
            G.add_edge(u, v, 1, cost);
        }
    };

    range(i, 0, n) range(j, 0, m) {
        if (ss[i][j] != 'o') continue;
        add_edge(i, j);
    }

    auto f = G.flow(S, T);
    i64 ans = f.first * inf - f.second;
    cout << ans << endl;
}

signed main(int argc, char *argv[]) {
    solver();
}

