			while (!que.empty()) {
				int cy = que.front().first, cx = que.front().second;
				que.pop();

				REP(i, 2) {
					int ny = cy + dy[i], nx = cx + dx[i];
					if (!isin(ny, nx) || maps[ny][nx] == '#') continue;
					if (chmin(mind.back()[ny][nx], mind.back()[cy][cx] + 1)) {
						que.emplace(ny, nx);
					}
				}
			}

