			// 	}
			// 	puts("");
			// }

			starts.emplace_back(sty, stx);
		}
	}

	int source = N * M + starts.size(), sink = N * M + starts.size() + 1;
	atcoder::mcf_graph<int, int> g(sink + 100);

	int ansbase = 0;
	// koma i は N * M + i
	REP(i, starts.size()) {
		int dmax = 0;
		REP(y, N) REP(x, M) if (mind[i][y][x] != INF) chmax(dmax, mind[i][y][x]);
		ansbase += dmax;
		REP(y, N) REP(x, M) if (mind[i][y][x] != INF) {
			// コマ i から (y, x)
			g.add_edge(N * M + i, y * N + x, 1, dmax - mind[i][y][x]);

			// printf("koma %d -> (y,x)=(%d,%d)\n", i, y, x);
		}

		// source から コマ i
		g.add_edge(source, N * M + i, 1, 0);
	}

	REP(y, N) REP(x, M) {
		if (maps[y][x] != '#') {
			// (y, x) から sink
			g.add_edge(y * N + x, sink, 1, 0);
		}
	}

	pii fdat = g.flow(source, sink, starts.size());

	// printf("flow = %d\n", fdat.first);
	cout << ansbase - fdat.second;
	return 0;
}

