int min_cost_max_flow(int s = 0, int t = 1) {
	// debug(1);
	vector<int> p(N), d(N);
	vector<vector<int>> adj(N);
	vector<vector<int>> capacity(N, vector<int>(N)), cost(N, vector<int>(N));
	for(auto e : edges) {
		adj[e.from].push_back(e.to);
		adj[e.to].push_back(e.from);
		capacity[e.from][e.to] = e.capacity;
		cost[e.from][e.to] = -e.cost;
		cost[e.to][e.from] = e.cost;
	}

	// int new_flow;
	// cout << "YES" << '\n';
	int flow = 0, res = 0;
	// while(new_flow = spfa(adj, p, d, capacity, cost, s, t)) {
	// 	flow += new_flow;
	// 	res += d[t] * new_flow;
	// }

	while(true) {

		spfa(adj, p, d, capacity, cost, s, t);
		int del = INF;
		int u = t;
		while(u != s) {
			del = min(del, capacity[p[u]][u]);
			u = p[u];
		}

		if(d[t] == INF)
			break;

		flow += del;
		res += del * d[t];
		u = t;

		while(u != s) {
			capacity[p[u]][u] -= del;
			capacity[u][p[u]] += del;
			u = p[u];
		}
	}

	return res;
}

