struct Edge
{
	int v,f,c;
	Edge *next,*rev;
}pool[MAXM],*h[MAXN],*pe[MAXN];
int etot=0;
inline void addEdge(int u,int v,int f,int c)
{
	Edge *p=&pool[++etot],*q=&pool[++etot];
	p->v=v,p->f=f,p->c=c,p->next=h[u],h[u]=p,p->rev=q;
	q->v=u,q->f=0,q->c=-c,q->next=h[v],h[v]=q,q->rev=p;
}
int src,sink;
int q[MAXM],dis[MAXN],pv[MAXN];
bool inq[MAXN];
bool spfa()
{
	int front=1,rear=0;
	memset(dis,0x3f,sizeof(dis));
	dis[src]=0;q[++rear]=src;inq[src]=1;
	while(front<=rear)
	{
		int u=q[front++];
		inq[u]=0;
		for(Edge *p=h[u];p;p=p->next)
			if(p->f && dis[p->v]>dis[u]+p->c)
			{
				dis[p->v]=dis[u]+p->c;
				pv[p->v]=u,pe[p->v]=p;
				if(!inq[p->v])q[++rear]=p->v;
			}
	}
	return dis[sink]<INF;
}
int augment()
{
	int t=INF;
	for(int u=sink;u!=src;u=pv[u])chkmin(t,pe[u]->f);
	for(int u=sink;u!=src;u=pv[u])pe[u]->f-=t,pe[u]->rev->f+=t;
	return t;
}

