#define mp(a, b) make_pair(a, b)
typedef pair<int, int> pii;
const int maxn = 50 + 10;
const int maxm = maxn * maxn;
const int INF = 1e9;
int tot;
int h[maxm], dis[maxm]; //势和距离(dis'), dis' = true_dis - h, 所以每次做完以后h += dis', 从而h成为真实最短路 
int prevv[maxm], preve[maxm]; //最短路前驱结点和对应的边 
inline const int read() {
	register int x = 0;
	register char ch = getchar();
	while (ch < '0' || ch > '9') ch = getchar();
	while (ch >= '0' && ch <= '9') x = (x << 3) + (x << 1) + ch - '0', ch = getchar();
	return x;
}
struct Edge
{
	int v, cap, cost, rev;
};
vector<Edge> G[maxm];
void add_edge(int u, int v, int cap, int cost)
{
	G[u].push_back(Edge{v, cap, cost, G[v].size()});
	G[v].push_back(Edge{u, 0, -cost, G[u].size() - 1});
}
/*
求s到t，流量最多f的最小费用最大流
*/
int MCMF(int s, int t, int &f)
{
	int res = 0;
	/*
	初始情况下，如果所有的权值都为正，那么可以简单地将所有h[i]设置为0；
	如果有负权值，那么我们做一遍spfa，让h[]等于距离函数。
	如果初始网络为DAG，也可以采用递推h[i] = min(h[j] + w[j][i], g[j][i] = true)。
	*/
	fill(h, h + tot + 1, 0);
	while(f > 0)
	{
		priority_queue<pii, vector<pii>, less<pii> > Q; 
		fill(dis, dis + tot + 1, -INF);
		dis[s] = 0;
		Q.push(mp(0, s));
		while(!Q.empty())
		{
			pii x = Q.top(); Q.pop();
			int v = x.second;
			if(dis[v] < x.first) continue;
			for(int i = 0; i < G[v].size(); ++i)
			{
				auto e = G[v][i];
				if(e.cap > 0 && dis[e.v] < dis[v] + e.cost + h[v] - h[e.v])
				{
					dis[e.v] = dis[v] + e.cost + h[v] - h[e.v];
					prevv[e.v] = v;
					preve[e.v] = i;
					Q.push(mp(dis[e.v], e.v));
				}
			}					
		}
		if(dis[t] == -INF) return res;
		for(int i = 1; i <= tot; ++i) 
			h[i] += dis[i];
		int d = f;
		for(int v = t; v != s; v = prevv[v])
			d = min(d, G[prevv[v]][preve[v]].cap);
		f -= d;
		res += d * h[t];
		for(int v = t; v != s; v = prevv[v])
		{
			auto & e = G[prevv[v]][preve[v]];
			e.cap -= d;
			G[v][e.rev].cap += d;
		}
	}
	return res;	
}
