            if(i + 1 < n && field[i + 1][j] != '#')
                G.add_edge(i * m + j, (i + 1) * m + j, 100, 0);
            if(j + 1 < m && field[i][j + 1] != '#')
                G.add_edge(i * m + j, i * m + j + 1, 100, 0);
        }
    }

    ans += cnt * INF - G.flow(S, T).second;

