long long hungarianMethod() {
        int n = ns1, m = n1*m1, PHI = -1, NOL = -2;
        bool x[n][m], ss[n], st[m];
        initialise(x,0);
        initialise(ss,0);


        initialise(st,0);
        int u[n], v[m], p[m], ls[n], lt[m], a[n];
        int f = 0;

        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                f = max(f, w[i][j]);

        for(int xx=0;xx<n;xx++) u[xx]=f;
        for(int xx=0;xx<m;xx++) p[xx]=INF;
        for(int xx=0;xx<m;xx++) v[xx]=0;
        for(int xx=0;xx<m;xx++) lt[xx]=NOL;
        for(int xx=0;xx<n;xx++) ls[xx]=PHI;
        for(int xx=0;xx<n;xx++) a[xx]=-1;

        while (true) {
            f = -1;
            for (int i = 0; i < n && f == -1; i++)
                if (ls[i] != NOL && !ss[i])
                    f = i;

            if (f != -1) {
                ss[f] = true;
                for (int j = 0; j < m; j++)
                    if (!x[f][j] && u[f] + v[j] - w[f][j] < p[j]) {
                        lt[j] = f;
                        p[j] = u[f] + v[j] - w[f][j];
                    }
            } else {
                for (int i = 0; i < m && f == -1; i++)
                    if (lt[i] != NOL && !st[i] && p[i] == 0)
                        f = i;

                if (f == -1) {
                    int d1 = INF, d2 = INF, d;
                    for (int i : u)
                        d1 = min(d1, i);

                    for (int i : p)
                        if (i > 0)
                            d2 = min(d2, i);

                    d = min(d1, d2);

                    for (int i = 0; i < n; i++)
                        if (ls[i] != NOL)
                            u[i] -= d;

                    for (int i = 0; i < m; i++) {
                        if (p[i] == 0)
                            v[i] += d;
                        if (p[i] > 0 && lt[i] != NOL)
                            p[i] -= d;
                    }

                    if (d2 >= d1)
                        break;
                } else {
                    st[f] = true;
                    int s = -1;

                    for (int i = 0; i < n && s == -1; i++)
                        if (x[i][f])
                            s = i;

                    if (s == -1) {
                        for (int l, r; ; f = r) {
                            r = f;
                            l = lt[r];

                            if (r >= 0 && l >= 0)
                                x[l][r] = !x[l][r];
                            else
                                break;

                            r = ls[l];
                            if (r >= 0 && l >= 0)
                                x[l][r] = !x[l][r];
                            else
                                break;
                        }

                        for(int xx=0;xx<m;xx++) p[xx]=INF;
                        for(int xx=0;xx<m;xx++) lt[xx]=NOL;
                        for(int xx=0;xx<n;xx++) ls[xx]=NOL;
                        for(int xx=0;xx<n;xx++) ss[xx]=0;
                        for(int xx=0;xx<m;xx++) st[xx]=0;


                        for (int i = 0; i < n; i++) {
                            bool ex = true;
                            for (int j = 0; j < m && ex; j++)
                                ex = !x[i][j];
                            if (ex)
                                ls[i] = PHI;
                        }
                    } else
                        ls[s] = f;
                }
            }
        }

        long long ans=0;

        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (x[i][j])
                    ans+=w[i][j];
        return ans;
    }

