pii min_cost_max_flow(int s,int t)
{
    pii res;

    while (1){
//        p[t]=inf;
//        for (auto i:edges){
//            if (i.to == t){
//                p[t]=min(p[t],i.cost);
//            }
//        }

//        cout<<"min_cost_max_flow goes"<<"\n";
        set<pii> q;
        for (int i=s;i<=t;i++){
            dist[i]=inf;
            if (i==s){
                dist[i]=0;
            }
            q.insert(mp(dist[i],i));
        }

        while (!q.empty()){
            pii now=*q.begin();
            q.erase(q.begin());
            if (dist[now.sec]==inf){
                break;
            }
            for (auto wh_edge:reb[now.sec]){
                int to=edges[wh_edge].to;
                int flow=edges[wh_edge].flow;
                int cost=edges[wh_edge].cost;

                if (flow!=0 && dist[to] > dist[now.sec] + (cost + p[to] - p[now.sec])){
                    q.erase(mp(dist[to],to));
                    dist[to] = dist[now.sec] + (cost + p[to] - p[now.sec]);
                    q.insert(mp(dist[to],to));

                    pred[to]=mp(now.sec,wh_edge);
//                    cout<<"pred of "<<to<<" "<<"is "<<now.sec<<"\n";
                }
            }
        }

//        {
//            char wait;
//            cin>>wait;
//        }

        if (dist[t]==inf){
            return res;
        }

        // go_back

        int cur=t;
        int sum_cost=0;
        while (cur!=s){
//            cout<<"  cur :: "<<cur<<"\n";
            int pred_from=pred[cur].fir;
            int pred_edge=pred[cur].sec;
            sum_cost+=edges[pred_edge].cost;

            edges[pred_edge].flow--;
            edges[pred_edge^1].flow++;

            cur=pred_from;
        }

        res.fir++;
        res.sec+=sum_cost;

        for (int i=s;i<=t;i++){
            if (dist[i]!=inf){
                dist[i]+=p[i];
            }
        }

//        {
//            char wait;
//            cin>>wait;
//        }
    }
}

