template<typename T>
class maximum_flow{
public:
	class edge{
	public:
		int to,rev;
		T cap,ini;//if ini>0, flow on this edge is (ini-cap).
	};
	int n;
	vector<vector<edge>> ad;
	vector<int> level,itr;
	T inf;

	maximum_flow(int n){
		this->n=n;
		inf=numeric_limits<T>::max();
		ad.resize(n);
		level.resize(n);
		itr.resize(n);
		fill(level.begin(),level.end(),-1);
	}

	void add_edge(int from,int to,T cap){
		edge e0,e1;
		e0.to=to,e0.rev=ad[to].size(),e0.cap=cap,e0.ini=cap;
		e1.to=from,e1.rev=ad[from].size(),e1.cap=0,e1.ini=0;
		ad[from].push_back(e0);
		ad[to].push_back(e1);
	}

	void bfs(int s){
		fill(level.begin(),level.end(),-1);
		level[s]=0;
		queue<int> que;
		que.push(s);
		while(que.size()){
			int v=que.front();
			que.pop();
			for(int i=0;i<ad[v].size();i++){
				edge &e=ad[v][i];
				if(e.cap>0 && level[e.to]<0){
					level[e.to]=level[v]+1;
					que.push(e.to);
				}
			}
		}
	}

	T dfs(int v,int t,T f){
		if(v==t) return f;
		for(;itr[v]<ad[v].size();itr[v]++){
			edge &e=ad[v][itr[v]];
			if(e.cap>0 && level[v]<level[e.to]){
				T d=dfs(e.to,t,min(f,e.cap));
				if(d>0){
					e.cap-=d;
					ad[e.to][e.rev].cap+=d;
					return d;
				}
			}
		}
		return 0;
	}

	T flow(int s,int t){//s and t must be fixed.
		T res=0,f=0;
		bfs(s);
		while(level[t]>=0){
        	fill(itr.begin(),itr.end(),0);
			f=dfs(s,t,inf);
			while(f>0){
				res+=f;
				f=dfs(s,t,inf);
			}
			bfs(s);
		}
		return res;
	}
};
