struct mcmf {
    struct edg {
        int v,c,f,cost;
        edg *op;
        edg() : edg(0,0,0,0) {}
        edg(int a, int b, int c, edg *d) : v(a), c(b), f(0), cost(c), op(d) {}
        void flow(int a) {
            f += a;
            op->f -= a;
        }
    };
    vector<edg*> v[e+1];
    int dist[e+1];
    edg *p[e+1];
    char visit[e+1];

    void init() {
        for (int i = 0; i <= e; i++) {
            for (int j = 0; j < sz(v[i]); j++)
                delete v[i][j];
            v[i].clear();
        }
    }
    void aed(int a, int b, int f, int c) {
        edg *q = new edg(b, f, c, 0), *w = new edg(a, 0, -c, 0);
        q->op = w, w->op = q;
        v[a].push_back(q);
        v[b].push_back(w);
    }
    int spfa() {
        fill(dist, dist+e+1, MOD);

        queue<int> q;
        q.push(s);
        dist[s] = 0;

        while (!q.empty()) {
            int tv = q.front();
            q.pop();
            visit[tv] = 0;

            for (auto i : v[tv]) {
                if (dist[i->v] > dist[tv] + i->cost && i->c - i->f) {
                    dist[i->v] = dist[tv] + i->cost;
                    p[i->v] = i;
                    if (!visit[i->v]) {
                        visit[i->v] = 1;
                        q.push(i->v);
                    }
                }
            }
        }
        return dist[e] != MOD;
    }
    pii cal() {
        pii ret = {0, 0};
        while (spfa()) {
            int f = MOD;
            for (int i = e; i != s; i = p[i]->op->v) f = min(f, p[i]->c - p[i]->f);

            ll t = 0;
            for (int i = e; i != s; i = p[i]->op->v) {
                p[i]->flow(f);
                t += p[i]->cost * f;
            }
            // if (t >= 0) break;

            ret.first += f;
            ret.second += t;
        }
        return ret;
    }
} mf;

