const int MX = 55;
int n, m, vis[MX][MX];
ll res;
char a[MX][MX];

bool valid (int i, int j) {
	return i < n && j < m && a[i][j] == '.' && !vis[i][j];
}

int main () {
	ios_base::sync_with_stdio(0); cin.tie(0);

	cin >> n >> m;
	forn (i, n) cin >> a[i];

	for (int d = n + m; d >= 0; d--)
		for (int i = n - 1; i >= 0; i--) {
			int j = d - i;

			if (j < 0 || m <= j) continue;
			if (a[i][j] != 'o') continue;

			memset(vis, 0, sizeof(vis));

			ii mx(d, i);
			queue<ii> q;

			vis[i][j] = 1;
			q.emplace(i, j);

			while (q.size()) {
				int i = q.front().fi;
				int j = q.front().se;

				ii p(i + j, i);
				mx = max(mx, p);
				q.pop();

				if (valid(i + 1, j)) {
					q.emplace(i + 1, j);
					vis[i + 1][j] = 1;
				}

				if (valid(i, j + 1)) {
					q.emplace(i, j + 1);
					vis[i][j + 1] = 1;
				}
			}

			int x = mx.se;
			int y = mx.fi - mx.se;
			res += mx.fi - d;

			a[i][j] = '.';
			a[x][y] = 'o';
		}

	cout << res << endl;

	return 0;
}

