	while(!q.empty()) {
		int u = q.front();
		q.pop();
		in_queue[u] = 0;
		for(int v : adj[u]) {
			if(capacity[u][v] > 0 && d[u] + cost[u][v] < d[v]) {
				// in_queue[v] = 1;
				d[v] = d[u] + cost[u][v];
				p[v] = u;
				if(!in_queue[v]) {
