	RF(ss, s) { ss.PB('#'); }
	s.PB(string(w + 1, '#'));
	vout(s, "\n");

	vector<array<int, 3>> v;
	inc(i, h) {
	inc(j, w) {
		if(s[i][j] == 'o') { v.PB({ i + j, i, j }); }
	}
	}
	sort(RALL(v));

	function<array<int, 3>(int, int)> dfs = [&](int i, int j) {
		array<int, 3> ma = { -1, i, j };
		if(s[i + 1][j] == '.') { setmax(ma, dfs(i + 1, j)); }
		if(s[i][j + 1] == '.') { setmax(ma, dfs(i, j + 1)); }
		ma[0]++;
		return ma;
	};

	int ans = 0;
	SF(v, s_, i, j) {
		auto [sum, ii, jj] = dfs(i, j);
		// out(i, j, ":", sum, i, j);
		ans += sum;
		s[i][j] = '.';
		s[ii][jj] = '#';
	}
	out(ans);

