int N, M;
char A[55][55];
int dp[55][55];
int toid(int x, int y) {
	return x * M + y;
}
set<pii>bfs(int sx,int sy){
	set<pii>res;
	queue<pii>que;
	que.push({ sx,sy });
	res.insert({ sx,sy });
	while (!que.empty()) {
		pii p = que.front(); que.pop();
		int x = p.first, y = p.second;
		int nx = x + 1, ny = y + 1;
		if (nx < N&&A[nx][y] != '#' && !res.count({nx,y})) {
			res.insert({ nx,y });
			que.push({ nx,y });
		}
		pii nxt = { x,ny };
		if (ny < M&&A[x][ny] != '#' && !res.count(nxt)) {
			res.insert(nxt);
			que.push(nxt);
		}
	}
	return res;
}


void solve() {
	cin >> N >> M;
	int K = 0;
	vector<pii>v;
	REP(i, N) {
		REP(j, M) {
			cin >> A[i][j];
			if (A[i][j] == 'o') {
				K++;
				dp[i][j] = 1;
				v.push_back({ i,j });
			}
		}
	}
	mcf_graph<int, int> G(N*M+K+2);
	int s = N * M + K, t = N * M + K+1;

	int sum = N * M;
	REP(i, K) {
		pii p = v[i];
		int x = p.first, y = p.second;
		G.add_edge(s, sum + i, 1, 0);
		G.add_edge(sum + i, t, 1, INF);
		set<pii>res = bfs(p.first, p.second);
		//DEBUG(x);
		//DEBUG(y);
		for (auto p : res) {
			int nx = p.first, ny = p.second;
			//DEBUG(nx); DEBUG(ny);
			int c = nx - x + ny - y;
			G.add_edge(sum + i, toid(nx, ny), 1, 0);
		}
	}
	REP(i, N)REP(j, M) {
		G.add_edge(toid(i, j), t, 1, INF - (i + j));
	}
	ll need = 0;
	REP(i, K) {
		pii p = v[i];
		int x = p.first, y = p.second;
		need += x + y;
	}
	pii ret = G.flow(s, t);
	ll fl = ret.first;
	//DEBUG(fl);
	//DEBUG(K);
	ll ans = INF * K - ret.second - need;
	print(ans);
}




