int main() {
  int N, M;
  std::cin >> N >> M;
  std::vector<std::string> S(N);
  for (int i = 0; i < N; ++i) {
    std::cin >> S[i];
  }
  const int offset = N * M;
  const int source = offset + N * M;
  const int sink = source + 1;
  atcoder::mcf_graph<int, int> graph(sink + 1);
  const int kInfinity = N + M;
  int num_stones = 0;
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < M; ++j) {
      const auto node = M * i + j;
      if (S[i][j] == '.') {
        graph.add_edge(offset + node, sink, 1, 0);
      } else if (S[i][j] == 'o') {
        ++num_stones;
        graph.add_edge(offset + node, sink, 1, 0);
        graph.add_edge(source, node, 1, 0);
        std::vector<std::vector<bool>> seen(N, std::vector<bool>(M));
        std::queue<std::tuple<int, int>> queue;
        queue.emplace(i, j);
        while (!queue.empty()) {
          auto [y, x] = queue.front();
          queue.pop();
          graph.add_edge(node, offset + M * y + x, 1, kInfinity - (y - i) - (x - j));
          ++y;
          if (y < N && !seen[y][x] && S[y][x] != '#') {
            queue.emplace(y, x);
            seen[y][x] = true;
          }
          --y;
          ++x;
          if (x < M && !seen[y][x] && S[y][x] != '#') {
            queue.emplace(y, x);
            seen[y][x] = true;
          }
        }
      }
    }
  }
  const auto [capacity, cost] = graph.flow(source, sink);
  std::cout << (kInfinity * num_stones - cost) << std::endl;
  return 0;
}

