    vector<string> s(n); cin >> s;
    auto valid = [&](int i, int j) {
        return (0 <= i && i < n &&
                0 <= j && j < m &&
                s[i][j] != '#');
    };
    auto id = [&](int i, int j) {
        return i*m+j;
    };

    int cnt = 0;

    mcf_graph<int,int> g(n*n*2 + 2);
    const int S = 2*n*n, T = S+1;
    rep (i,n) rep (j,n) if (s[i][j] == 'o') {
        cnt++;
        g.add_edge(S,id(i,j),1,0);
    }
    rep (i,n) rep (j,n) if (s[i][j] != '#') {
        g.add_edge(id(i,j),T,1,2*(n-1)-(i+j));
    }

    rep (i,n) rep (j,n) if (s[i][j] == 'o') {
        auto d = make_v<int,2>(n,m,INF);
        queue<pair<int,int>> q;
        d[i][j] = 0;
        q.emplace(i,j);
        while (q.size()) {
            auto [x,y] = q.front(); q.pop();
            auto push = [&](int nx, int ny) {
                if (valid(nx,ny) && chmin(d[nx][ny], d[x][y] + 1)) {
                    q.emplace(nx,ny);
                }
            };
            push(x+1,y);
            push(x,y+1);
        }

        rep (x,n) rep (y,n) if (d[x][y] < INF) {
            g.add_edge(id(i,j),id(x,y),1,0);
        }
    }

    auto [flow,cost] = g.flow(S,T);
    dump(flow,cost);
    assert(flow == cnt);

    int init = 0;
    rep (i,n) rep (j,n) if (s[i][j] == 'o') {
        init += 2*(n-1)-(i+j);
    }

    cout << init-cost << endl;

}

