	vector<string> s(N);
	rep(i, N)cin >> s[i];

	vector<pair<ll, ll>> koma;

	rep(i, N)rep(j, M) {
		if (s[i][j] == 'o') { koma.push_back({ i,j }); }
	}

	ll K = koma.size();

	vvvll reach(K, vvll(N, vll(M, 0)));
	rep(i, K) {
		queue<pair<ll,ll>> q;
		q.push(koma[i]);

		reach[i][koma[i].first][koma[i].second] = 1;

		vll dx = { 1,0 };
		vll dy = { 0,1 };

		while (!q.empty()) {
			auto p = q.front();
			q.pop();

			ll x = p.first;
			ll y = p.second;
			rep(j, 2) {
				ll xx = x + dx[j];
				ll yy = y + dy[j];

				if (xx == N || yy == M || reach[i][xx][yy] == 1 || s[xx][yy] == '#') { continue; }
				reach[i][xx][yy] = 1;
				q.push({ xx,yy });
			}	
		}
	}

	ll BIG = 1e9;

	mcf_graph<ll, ll> g(N* M + K + 2);
	ll st = N * M + K;
	ll tar = N * M + K + 1;

	rep(k, K) {
		rep(i, N)rep(j, M) {
			if (reach[k][i][j] == 1) {
				//cout << i << j << k << endl;
				g.add_edge(i * M + j, N * M + k, 1, BIG - (i + j - koma[k].first - koma[k].second));
			}
		}
	}

	rep(i, N* M) {
		g.add_edge(st, i, 1, 0);
	}
	rep(i, K) {
		g.add_edge(N * M + i, tar, 1, 0);
	}

	ll ans = g.flow(st, tar, K).second;
	ans = BIG * K - ans;
	cout << ans << endl;

}

