  }
  Flow::S = N * M * 2 + 1, Flow::T = N * M * 2 + 2;
  rep(i, 1, N) rep(j, 1, M) 
    Flow::addline(N * M + id(i, j), Flow::T, 1, 0);
  rep(i, 1, N) rep(j, 1, M) if (A[i][j] == 'o') {
    Flow::addline(Flow::S, id(i, j), 1, 0);
    vec.clear();
    dfs(i, j, 0);
    for (pii p : vec) {
      Flow::addline(id(i, j), N * M + id(p.first, p.second), 1, -dis[p.first][p.second]);
    }
  }
  cout << -Flow::EK() << endl;
}

