	const int MAXN = 5e5 + 19, MAXM = 1e6 + 19;
	struct Edge{
		int to, next, c, dist;
	}edge[MAXM << 1];
	int cnt = -1, head[MAXN];
	inline void add(int from, int to, int c, int dist){
		edge[++cnt].to = to;
		edge[cnt].c = c;
		edge[cnt].dist = dist;
		edge[cnt].next = head[from];
		head[from] = cnt;
	}
	int n, m, s, t;
	int pre[MAXN], dist[MAXN], flow[MAXN];
	int ans1, ans2;
	int spfa(void){
		std::queue<int>q; q.push(s);
		std::memset(dist, 0x3f, sizeof dist); dist[s] = 0;
		std::memset(flow, 0x3f, sizeof flow);
		while(!q.empty()){
			int node = q.front(); q.pop();
			for(int i = head[node]; i != -1; i = edge[i].next)
				if(edge[i].c && dist[edge[i].to] > dist[node] + edge[i].dist){
					dist[edge[i].to] = dist[node] + edge[i].dist;
					flow[edge[i].to] = std::min(flow[node], edge[i].c);
					pre[edge[i].to] = i;
					q.push(edge[i].to);
				}
		}
		if(dist[t] == 0x3f3f3f3f)
			return 0;
		return flow[t];
	}
	void edmonds_karp(int& flow, int& fee){
		int stream;
		while(stream = spfa()){
			flow += stream, fee += stream * dist[t];
			for(int i = t; i != s; i = edge[pre[i] ^ 1].to)
				edge[pre[i]].c -= stream, edge[pre[i] ^ 1].c += stream;
		}
	}
}
