int n, m;
void dfs(vector<string> &data, pair<int,int> check, int &count) {
    vector<vector<int>> dist(n,vector<int>(m,-1000));
    int x = check.first, y = check.second;
    bool start = false;
  int save = 0;
    rep(i,n) rep(j,m) {
        if (x == i && y == j) {
            start = true;
            dist[i][j] = 0;
            save = 0;
        }
        if (!start) continue;
        if (i+1 < n && data[i+1][j] == '.') {
            chmax(dist[i+1][j], dist[i][j] + 1);
            chmax(save, dist[i+1][j]);
        }
        if (j+1 < m && data[i][j+1] == '.') {
            chmax(dist[i][j+1], dist[i][j] + 1);
            chmax(save, dist[i][j+1]);
        }
    }
    if(save == 0) return;
    int xx = -1, yy = -1;
    rep(i,n) rep(j,m) if (dist[i][j] == save) { xx = i; yy = j; break; }
    count += save;
    data[x][y] = '.';
    data[xx][yy] = 'o';
    return;
}

