void bfs(int sx, int sy) {
    rep(x, n) rep(y, m) dist[sx][sy][x][y] = mod;
    dist[sx][sy][sx][sy] = 0;
    queue<pii> que;
    que.emplace(sx, sy);
    while (!que.empty()) {
        auto [x, y] = que.front();
        que.pop();
        rep(dx, 2) rep(dy, 2) if (dx ^ dy) {
            int nx = x + dx, ny = y + dy;
            if (0 <= nx && nx < n && 0 <= ny && ny < m && c[nx][ny] != '#') {
                if (chmin(dist[sx][sy][nx][ny], dist[sx][sy][x][y] + 1))
                    que.emplace(nx, ny);
            }
        }
    }
}

