                                         vector<pair<cost_t, int>>, greater<>>>
using MaxGainFlow = MinCostFlow<flow_t, cost_t, Heap, -1>;

signed main() {
  cin.tie(0);
  ios::sync_with_stdio(0);
  int N, M;
  cin >> N >> M;
  string S[N];
  for (int i = 0; i < N; i++) cin >> S[i];
  MaxGainFlow<long long, long long> mgf;
  mgf.add_vertices(N * M);
  auto node = [&](int i, int j) { return i * M + j; };
  auto ij = [&](int v) { return make_pair(v / M, v % M); };
  int s = mgf.add_vertex(), t = mgf.add_vertex();
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < M; j++) {
      if (S[i][j] == '#') continue;
      mgf.add_edge(node(i, j), t, 0, 1, 0);
      if (S[i][j] == 'o') {
        queue<int> que;
        int ori = node(i, j);
        mgf.add_edge(s, ori, 0, 1, 0);
        que.push(ori);
        bool used[N * M];
        fill(used, used + N * M, false);
        while (!que.empty()) {
          int v = que.front();
          que.pop();
          if (used[v]) continue;
          used[v] = true;
          int ci, cj;
          tie(ci, cj) = ij(v);
          mgf.add_edge(ori, v, 0, 1, ci - i + cj - j);
          if (ci + 1 < N && S[ci + 1][cj] != '#') que.push(node(ci + 1, cj));
          if (cj + 1 < M && S[ci][cj + 1] != '#') que.push(node(ci, cj + 1));
        }
      }
    }
  }
