int cod[300];

int rez;

int k;
pair <int, int> poz[MAX_N * MAX_N + 1];

int viz[MAX_N + 1][MAX_N + 1];
int dp[MAX_N + 1][MAX_N + 1];

void init0()
{
    for(int i = 1; i<= n; i ++)
    {
        for(int j = 1; j <= m; j ++)
        {
            viz[i][j] = 0;
            dp[i][j] = 0;
        }
    }

}

pair<int, int> que[MAX_N * MAX_N + 1];

const int dl[] = {1, 0};
const int dc[] = {0, 1};

void bfs(int sl, int sc)
{
    init0();

    int st = 1, dr = 0;
    que[++ dr] = {sl, sc};
  //  viz[sl][sc] = 1;
    dp[sl][sc] = 0;

    while(st <= dr)
    {
        int l = que[st].xx;
        int c = que[st].yy;
        st ++;

        for(int dir = 0; dir <= 1; dir ++)
        {
            int nl = l + dl[dir];
            int nc = c + dc[dir];
            if(nl >= 1 && nl <= n && nc >= 1 && nc <= m)
            {
                if(a[nl][nc] == 0)
                {
                    if(dp[l][c] + 1 > dp[nl][nc])
                    {
                        dp[nl][nc] = dp[l][c] + 1;
                        que[++ dr] = {nl, nc};
                    }
                }
            }
        }
    }
}

void solve()
{
    sort(poz + 1, poz + k + 1);

    int ok = 1;
    for(int y = 1; ok == 1; y ++)
    {
        int apn = 0;
        int mn = n * n + 1;
        int el, ec, fl, fc;
        int care;
        for(int x = k; x >= 1; x --)
        {
            int apx = 0;
            int l = poz[x].xx;
            int c = poz[x].yy;


            bfs(l, c);

            int mx = 0, lx, cx;
            for(int i = l; i <= n; i ++)
            {
                for(int j = c; j <= m; j ++)
                {
                    if(dp[i][j] > mx)
                    {
                        mx = dp[i][j];
                        lx = i;
                        cx = j;
                        apx = 0;
                    }

                    if(dp[i][j] == mx)
                        apx ++;
                }
            }

            if(mx != 0)
            {
                if(mx < mn || (mx == mn && apx < apn))
                {
                    care = x;
                    mn = mx;
                    el = l;
                    ec = c;
                    fl = lx;
                    fc = cx;
                    apn = apx;
                }
            }
        }

        if(mn != n * n + 1)
        {
           // cout << "MUTAM " << mn << " PE " << el << " " << ec << " IN " << fl << " " << fc << "\n";

            rez += mn;
            poz[care] = {fl, fc};
            a[el][ec] = 0;
            a[fl][fc] = 2;
        }

        else
            ok = 0;
    }

    cout << rez << "\n";
}

int main()
{
    cod['.'] = 0;
    cod['#'] = 1;
    cod['o'] = 2;

    cin >> n >> m;
    for(int i = 1; i <=n ; i ++)
    {
        cin >> s;
        for(int j = 1; j <= m; j ++)
        {
            a[i][j] = cod[s[j - 1]];

            if(a[i][j] == 2)
            {
                poz[++ k] = {i, j};
            }
        }
    }

    solve();

    return 0;
}

