#define MF MincostMaxflow
#define flow_t int
#define cost_t int
const flow_t foo = (flow_t) 1e9;
const cost_t coo = (cost_t) 1e9;
namespace MincostMaxflow {
    const int maxv = 1e5 + 5;
    const int maxe = 1e6 + 5;
    int n, s, t, E;
    int adj[maxe], nxt[maxe], lst[maxv], frm[maxv], vis[maxv];
    flow_t cap[maxe], flw[maxe], totalFlow;
    cost_t cst[maxe], dst[maxv], totalCost;

    void init(int nn, int ss, int tt) {
        n = nn, s = ss, t = tt;
        fill_n(lst, n, -1), E = 0;
    }
    void add(int u, int v, flow_t ca, cost_t co) {
        adj[E] = v, cap[E] = ca, flw[E] = 0, cst[E] = +co, nxt[E] = lst[u], lst[u] = E++;
        adj[E] = u, cap[E] =  0, flw[E] = 0, cst[E] = -co, nxt[E] = lst[v], lst[v] = E++;
    }
    int spfa() {
        fill_n(dst, n, coo), dst[s] = 0;
        queue<int> que; que.push(s);
        while (que.size()) {
            int u = que.front(); que.pop();
            for (int e = lst[u]; e != -1; e = nxt[e]) if (flw[e] < cap[e]) {
                int v = adj[e];
                if (dst[v] > dst[u] + cst[e]) {
                    dst[v] = dst[u] + cst[e];
                    frm[v] = e;
                    if (!vis[v]) {
                        vis[v] = 1;
                        que.push(v);
                    }
                }
            }
            vis[u] = 0;
        }
        return dst[t] < coo;
    }
    cost_t mincost() {
        totalCost = 0, totalFlow = 0;
        while (1) {
            if (!spfa()) break;
            flow_t mn = foo;
            for (int v = t, e = frm[v]; v != s; v = adj[e ^ 1], e = frm[v]) mn = min(mn, cap[e] - flw[e]);
            for (int v = t, e = frm[v]; v != s; v = adj[e ^ 1], e = frm[v]) {
                flw[e] += mn;
                flw[e ^ 1] -= mn;
            }
            totalFlow += mn;
            totalCost += mn * dst[t];
        }
        return totalCost;
    }
}

void chemthan() {
    int n, m; cin >> n >> m;
    vector<string> s(n);
    FOR(i, 0, n) cin >> s[i];
    int tot = n * m * 2;
    int S = tot++, t = tot++;
    MF::init(tot, S, t);
    int num = 0;
    FOR(i, 0, n) FOR(j, 0, m) if (s[i][j] == 'o') {
        MF::add(S, i * m + j, 1, 0);
        num++;
        vector<vi> dp(n, vi(m, INF));
        queue<int> que;
        dp[i][j] = 0, que.push(i), que.push(j);
        while (sz(que)) {
            int u = que.front(); que.pop();
            int v = que.front(); que.pop();
            if (u + 1 < n && s[u + 1][v] != '#') {
                if (chkmin(dp[u + 1][v], dp[u][v] + 1)) {
                    que.push(u + 1), que.push(v);
                }
            }
            if (v + 1 < n && s[u][ v + 1] != '#') {
                if (chkmin(dp[u][v + 1], dp[u][v] + 1)) {
                    que.push(u), que.push(v + 1);
                }
            }
        }
        vector<tuple<int, int, int>> vals;
        FOR(u, 0, n) FOR(v, 0, m) if (dp[u][v] < INF) {
            MF::add(i * m + j, n * m + u * m + v, 1, 100000 - dp[u][v]);
        }
    }
    FOR(i, 0, n * m) {
        MF::add(n * m + i, t, 1, 0);
    }
    cout << (long long) 100000 * num - MF::mincost() << "\n";
}

