    used[x][y] = true;
    int cost = (n - x) + (m - y);
    graph.add_edge(c, 100 + x * m + y, 1, cost);
    if(x < n - 1 && !used[x + 1][y]) dfs(x + 1, y, rx, ry, c, used);
    if(y < m - 1 && !used[x][y + 1]) dfs(x, y + 1, rx, ry, c, used);
    return;
}

