void solve(int N, int M, vector<string> S) {
  int ans = 0;
  vp ps;
  rrep(i, N)rrep(j, M) if (S[i][j] == 'o') ps.emplace_back(i, j);
  each(p, ps) {
    auto [x, y] = p;
    vvb used(N, vb(M));
    int tmp = 0, mx = x, my = y;
    queue<pii> q;
    q.push(p);
    while (!q.empty()) {
      auto [tx, ty] = q.front();
      if (tmp < tx - x + ty - y) {
        tmp = tx - x + ty - y;
        mx = tx;
        my = ty;
      }
      q.pop();
      if (tx < N - 1 && !used[tx + 1][ty] && S[tx + 1][ty] == '.') {
        used[tx + 1][ty] = true;
        q.emplace(tx + 1, ty);
      }
      if (ty < M - 1 && !used[tx][ty + 1] && S[tx][ty + 1] == '.') {
        used[tx][ty + 1] = true;
        q.emplace(tx, ty + 1);
      }
    }
    ans += tmp;
    S[x][y] = '.';
    S[mx][my] = 'o';
  }
  COUT(ans);
}


