			g.add_edge(N * M, p(i, j), 1, 0); // (1,0) sから
		}
	}
	rep(i, N) rep(j, M) {
		if (S[i][j] == '#') continue;
		if (i < N - 1 and S[i + 1][j] != '#') g.add_edge(p(i, j), p(i + 1, j), N * M, 0); // (NM,0) 隣のマスへ
		if (j < M - 1 and S[i][j + 1] != '#') g.add_edge(p(i, j), p(i, j + 1), N * M, 0);
	}
	rep(i, N) rep(j, M) {
		if (S[i][j] == '#') continue;
		g.add_edge(p(i, j), N * M + 1, 1, MAX - (i + j)); // tへ
	}
	pii cf = g.flow(N * M, N * M + 1);
	// dbs(cf.first, cf.second);
	// for (mcf_graph<int, int>::edge e : g.edges()) {
	// 	dbs(e.from, e.to, e.cap, e.flow, e.cost);
	// }
	int ans = MAX * cf.first - cf.second;
	rep(i, N) rep(j, M) if (S[i][j] == 'o') ans -= i + j;

	cout << ans << endl;
}

