int main(){
    setIO("");
    int n, m;
    re(n, m);
    map<pi, int> id;
    map<int, pi> cid;
    int cnt = 0;
    vpi loc;
    f0r(i, n){
        string line; re(line);
        f0r(j, m){
            if(line[j]=='.') grid[i][j] = 0;
            else if(line[j]=='#') grid[i][j] = 1;
            else grid[i][j] = 2, loc.eb(i, j), id[{i,j}]=cnt,cid[cnt] = {i, j}, cnt++;
        }
    }
    for(auto x: loc){
        list<pi> que;
        int idx = id[x];
        vis[idx][x.f][x.s] = true;
        que.push_back(x);
        while(!que.empty()){
            auto s = que.front();
            que.pop_front();
            int i = s.f;
            int j = s.s;
            if(i<n&&!vis[i+1][j]){
                vis[idx][i+1][j] = true;
                que.emplace_back(i+1,j);
            }
            if(j<m&&!vis[i][j+1]){
                vis[idx][i][j+1] = true;
                que.emplace_back(i,j+1);
            }
        }
    }
    mcf_graph<int, int> g(n*m + cnt+3);
    int s = n+m+cnt+1;
    int t = n+m+cnt+2;
    f0r(i, cnt){
        g.add_edge(s, n*m+i, 1, 0);
    }
    f0r(i, n){
        f0r(j, m){
            g.add_edge(i*m+j, t, 1, 0);
        }
    }
    f0r(i, cnt){
        int x = cid[i].f;
        int y = cid[i].s;
        f0r(j, n){
            f0r(k, m){
                if(!vis[i][j][k]) continue;
                int dist = j+k-x-y;
                g.add_edge(n*m+i, i*m+j, 1, -dist);
            }
        }
    }
    auto res = (g.flow(s, t));
    ps(-res.s);
    return 0;
}

