void bfs(ll r, ll c, ll piece) {
	queue<pair<pair<ll, ll>, ll>> q;

	q.push(make_pair(make_pair(r, c), 0));

	ll mdist = 0;

	while (!q.empty()) {
		pair<pair<ll, ll>, ll> x = q.front();

		q.pop();

		pair<ll, ll> p = x.f;

		if (vis[p.f][p.s]) continue;
		vis[p.f][p.s] = 1;

		mdist = max(mdist, x.s);

		for (ll d = 0; d < 2; d++) {
			ll nr = p.f + dr[d];
			ll nc = p.s + dc[d];

			if (valid(nr, nc) && ss[nr][nc] != '#') {
				q.push(make_pair(make_pair(nr, nc), x.s + 1));
			}
		}
	}

	q = queue<pair<pair<ll, ll>, ll>>();

	q.push(make_pair(make_pair(r, c), 0));

	memset(vis, 0, sizeof(vis));

	while (!q.empty()) {
		pair<pair<ll, ll>, ll> x = q.front();

		q.pop();

		pair<ll, ll> p = x.f;

		if (vis[p.f][p.s]) continue;
		vis[p.f][p.s] = 1;

		flow.add_edge(piece, 102 + p.f * m + p.s, 1, mdist - x.s);
