        if (!ban[diag][i]) {
            // close one
            if (rs.size() && *rs.begin() < i) {
                // bad
                return false;
            }
            if (rs.size()) {
                rs.erase(rs.begin());
            }
        }
    }

    return rs.size() == 0;
}

