/*
求s到t，流量最多f的最小费用最大流
*/
int MCMF(int s, int t, int &f)
{
	int res = 0;
	/*
	初始情况下，如果所有的权值都为正，那么可以简单地将所有h[i]设置为0；
	如果有负权值，那么我们做一遍spfa，让h[]等于距离函数。
	如果初始网络为DAG，也可以采用递推h[i] = min(h[j] + w[j][i], g[j][i] = true)。
	*/
	fill(h, h + tot + 1, 0);
	while(f > 0)
	{
		priority_queue<pii, vector<pii>, less<pii> > Q; 
		fill(dis, dis + tot + 1, -INF);
		dis[s] = 0;
		Q.push(mp(0, s));
		while(!Q.empty())
		{
			pii x = Q.top(); Q.pop();
			int v = x.second;
			if(dis[v] > x.first) continue;
			for(int i = 0; i < G[v].size(); ++i)
			{
				auto e = G[v][i];
				if(e.cap > 0 && dis[e.v] < dis[v] + e.cost + h[v] - h[e.v])
				{
					dis[e.v] = dis[v] + e.cost + h[v] - h[e.v];
					prevv[e.v] = v;
					preve[e.v] = i;
					Q.push(mp(dis[e.v], e.v));
				}
			}					
		}
		if(dis[t] == -INF) return res;
		for(int i = 1; i <= tot; ++i) 
			h[i] += dis[i];
		int d = f;
		for(int v = t; v != s; v = prevv[v])
			d = min(d, G[prevv[v]][preve[v]].cap);
		f -= d;
		res += d * h[t];
		for(int v = t; v != s; v = prevv[v])
		{
			auto & e = G[prevv[v]][preve[v]];
			e.cap -= d;
			G[v][e.rev].cap += d;
		}
	}
	return res;	
}
