pair<int,pair<int,int>> dfs(pair<int,int> p){
    pair<int,pair<int,int>> right,down;
    right={0,{0,0}}; down={0,{0,0}};
    int row=p.first; int col= p.second;
    g[row][col]=true;
    if(col<50 && g[row][col+1]){
        right= dfs({row,col+1});
    }
    if(row<50 && g[row+1][col]){
        down= dfs({row+1,col});
    }
    int v= 1+max(right.first,down.first);
    pair<int,int> dest={row,col};

    if(right.first>down.first){
        dest=right.second;
    }else if(down.first>0){
        dest=down.second;
    }
    return {v,{dest}};
}

