void solve(ostringstream& aout, long long N, long long M, std::vector<std::string> S) {
	Graph G(N*M);
	create_from_grid(G, N, M, S, '#');
	int H = N, W = M;

	const Weight INF = std::numeric_limits<Weight>::max() / 8;

	// 動かせるピースを数える
	int maxCost = INF;
	int pieceCnt = 0;
	rep(y, H) {
		rep(x, W) {
			if (S[y][x] == 'o') {
				int id = y * W + x;
				auto res = dijkstra(G, id);
				bool found = false;
				for (auto i : res) {
					if (i != INF && i != 0) {
						found = true;
					}
				}
				if (found) {
					pieceCnt++;
				}
				else {
					// 行先の無いコマは壁とみなす
					S[y][x] = '#';
				}
			}

		}
	}

	// コマの数 + グリッドのマス目の数 + 始点終点
	// [0, pieceCnt): コマ
	// [pieceCnt, H*W): マス目
	// pieceCnt + H*W: s
	// pieceCnt + H*W + 1: t
	atcoder::mcf_graph<int, int> mcf(pieceCnt + H * W + 2);

	Graph G2(H*W);
	create_from_grid(G2, H, W, S, '#');

	// left: コマがあるグリッドのID
	int left = 0;
	rep(y, H) {
		rep(x, W) {
			if (S[y][x] == 'o') {
				int id = y * W + x;
				auto res = dijkstra(G2, id);
				rep(n, H*W) {
					int i = res[n];

					if (i == INF || i == 0) {
						continue;
					}

					int right = n + pieceCnt;
