void dfs(int x, int y){
    if(chk[x][y] || x < 1 || y < 1|| arr[x][y] == '#') return;
    chk[x][y] = 1;
    dfs(x - 1, y), dfs(x, y - 1);
}

int aug(int x){
    for(auto&i:way[x]){
        if(augchk[i] == chkN) continue;
        augchk[i] = chkN;
        if(r[i] == -1 || aug(r[i])){
            r[i] = x; l[x] = i;
            return 1;
        }
    }
    return 0;
}

int main(){
    scanf("%d %d", &N, &M);
