//        }
    }
    for(int I = N + M; I >= 2; --I){
        int i = 1, j = I - i;
        while(j >= 1){
            if(i <= N && j <= M && arr[i][j] != '#'){
                now.clear();
                memset(chk, 0, sizeof(chk));
                dfs(i, j);
                for(int k = N + M; k >= 2; --k){
                    int a = 1, b = k - 1;
                    while(b >= 1){
                        if(a <= N && b <= M && chk[a][b] && arr[a][b] == 'o'){
                            now.push_back((a - 1) * M + b);
                        }
                        ++a, --b;
                    }
                }
                way.push_back(now);
                pos.push_back(make_pair(i, j));
            }
            ++i, --j;
        }
    }
    memset(r, -1, sizeof(r));
    for(int i = 0; i < (int)way.size(); ++i){
        ++chkN;
        aug(i);
    }
    int ans = 0;
    for(int i = 0; i < (int)way.size(); ++i){
