//            printf("%d %d %d %d\n", pos[i].first, pos[i].second, x, y);
            ans += -(x + y - pos[i].first - pos[i].second);
        }
    }
    printf("%d\n", ans);
    return 0;
}

#include <bits/stdc++.h>
#define F first
#define S second
using namespace std;
typedef long long LL;
const LL INF = 0x3f3f3f3f3f3f3f3fLL;
const int MAXN = 2505;
typedef pair<int, int> pii;
struct KM { LL W[MAXN][MAXN]; int V;
  LL mx[MAXN], my[MAXN]; LL lx[MAXN], ly[MAXN];
  bool x[MAXN], y[MAXN];
  void init(int _V) { V = _V; memset(W, 0, sizeof(W)); }
  bool augment(int u) { x[u] = 1;
    for (int i = 0 ; i < V ; i++)
      if (!y[i] && W[u][i] == lx[u]+ly[i] && (y[i]=1))
         if (!~my[i] || augment(my[i]))
          return my[i] = u, true;
    return false;
  }
  LL run() { memset(mx, -1, sizeof(mx));
    memset(my, -1, sizeof(my));
    for (int i = 0 ; i < V ; i++)
      lx[i] = -INF, ly[i] = 0;
    for (int i = 0 ; i < V ; i++)
      for (int j = 0 ; j < V ; j++)
        lx[i] = max(lx[i], W[i][j]);
    for (int i = 0 ; i < V ; i++) { while (1) {
        memset(x, false, sizeof(x));
        memset(y, false, sizeof(y));
        if (augment(i)) break; LL d = INF;
        for (int j = 0 ; j < V ; j++) {
          if (!x[j]) continue;
          for (int k = 0 ; k < V ; k++) {
            if (y[k]) continue;
            d = min(d, lx[j] + ly[k] - W[j][k]);
          }
        }
        if (d == INF) break;
        for (int j = 0 ; j < V ; j++) {
          if (x[j]) lx[j] -= d; if (y[j]) ly[j] += d;
        }
      }
    }
    LL ret = 0; for (int i = 0 ; i < V ; i++)
      if (~my[i]) ret += W[my[i]][i];
    return ret;
  }
} solver;
int dx[] = {0, 1};
int dy[] = {1, 0};
vector<vector<LL>> go(auto &G, pii s) {
    int n = G.size(), m = G[0].size();
    vector<vector<LL>> d(n, vector<LL>(m, -INF));
    queue<pii> q; q.push(s); d[s.F][s.S] = 0; while (q.size()) {
        pii p = q.front(); q.pop();
        for (int _ = 0 ; _ < 2 ; _++) {
            pii nx = {p.F + dx[_], p.S + dy[_]};
            if (nx.F < 0 || nx.F >= n || nx.S < 0 || nx.S >= m)
                continue;
            if (G[nx.F][nx.S] == '#')
                continue;
            if (d[nx.F][nx.S] != -INF)
                continue;
            d[nx.F][nx.S] = d[p.F][p.S] + 1;
            q.push(nx);
        }
    }
    return d;
}
int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);
    int n, m; cin >> n >> m;
    solver.init(n * m);
    vector<vector<char>> G(n, vector<char>(m));
    for (auto &vv : G)
        for (auto &v : vv)
            cin >> v;
    for (int i = 0 ; i < n ; i++) {
        for (int j = 0 ; j < m ; j++) {
            if (G[i][j] != 'o')
                continue;
            auto res = go(G, {i, j});
            for (int x = 0 ; x < n ; x++) {
                for (int y = 0 ; y < m ; y++) {
                    int uid = i * m + j;
                    int vid = x * m + y;
                    solver.W[uid][vid] = res[x][y];
//                    cout << "add " << uid << ' ' << vid << ' ' << res[x][y] << '\n';
                }
            }
        }
    }
