#define int ll
using cost_type = ll;
const cost_type COST_INF = (int)1e18;
const int FLOW_INF = (int)1e9;
struct MinCost {
	explicit MinCost(int n) {
		g.resize(n);
	}
	struct edge {
		int from, to;
		int cap;
		cost_type cost;
		int flow;
	};
	vector<edge> edges;
	vector<vector<int>> g;
	void add_edge(int from, int to, cost_type cost, int cap) {
		edge e = { from, to, cap, cost, 0 };
		g[from].push_back(edges.size());
		edges.push_back(e);
		edge e2 = { to, from, 0, -cost, 0 };
		g[to].push_back(edges.size());
		edges.push_back(e2);
	}

	pair<int, cost_type> min_cost(int n, int s, int t, bool need_max_flow, int max_flow_value = FLOW_INF) {
		cost_type cost = 0;
		int flow = 0;
		vector<cost_type> potential;
		{
			vector<int> p(n, -1);
			vector<cost_type> d(n);
			d[s] = 0;
			p[s] = s;
			bool changed = true;
			while (changed) {
				changed = false;
				for (size_t i = 0; i <
					edges.size(); ++i) {
					edge &e = edges[i];
					if (e.cap == e.flow ||
						p[e.from] == -1)
						continue;
					if (p[e.to] == -1 ||
						d[e.to] >
						d[e.from] + e.cost) {
						d[e.to] =
							d[e.from] + e.cost;
						p[e.to] = i;
						changed = true;
					}
				}
			}
			potential = std::move(d);
		}
		while (flow < max_flow_value) {
			vector<cost_type> d(n);
			vector<int> p(n, -1);
			using queue_type = pair<cost_type, int>;
			priority_queue<queue_type, vector<queue_type>, greater<queue_type>> q;
			q.push({ 0, s });
			while (!q.empty()) {
				int v = q.top().second;
				cost_type oldD = q.top().first;
				q.pop();
				if (oldD != d[v])
					continue;
				for (int id : g[v]) {
					edge &e = edges[id];
					if (e.to == s)
						continue;
					if (e.cap > e.flow) {
						cost_type newd = d[v]
							+ e.cost +
							potential[e.from]
							- potential[e.to];
						if (p[e.to] == -1 ||
							d[e.to] > newd) {
							d[e.to] = newd;
							p[e.to] = id;
							q.push({ d[e.to], e.to });
						}
					}
				}
			}
			if (p[t] == -1) {
				break;
			}
			if (d[t] + potential[t] >= 0 && !need_max_flow) {
				break;
			}
			int cur = t;
			int maxAdd = max_flow_value - flow;
			while (cur != s) {
				edge &e = edges[p[cur]];
				cur = e.from;
				maxAdd = min(maxAdd, e.cap - e.flow);
			}
			flow += maxAdd;
			cost += (potential[t] + d[t]) * maxAdd;
			cur = t;
			while (cur != s) {
				int id = p[cur];
				edges[id].flow += maxAdd;
				edges[id ^ 1].flow -= maxAdd;
				cur = edges[id].from;
			}

