void solve(ostream& cout) {
	int p = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			p += (a[i][j] == 'o');
		}
	}
	int N = p + n * m + 2;
	int S = N - 2;
	int T = N - 1;
	MinCost mc(N);
	for (int i = 0; i < p; i++) {
		mc.add_edge(S, i, 0, 1);
	}
	for (int i = 0; i < n * m; i++) {
		mc.add_edge(p + i, T, 0, 1);
	}
	for (int i = 0, id = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (a[i][j] != 'o') {
				continue;
			}
			queue<pair<int, int>> q;
			q.push({ i, j });
			vector<vector<bool>> was(n, vector<bool>(m));
			was[i][j] = true;
			while (!q.empty()) {
				int ii = q.front().first;
				int jj = q.front().second;
				q.pop();
				int d = llabs(i - ii) + llabs(j - jj);
				mc.add_edge(id, p + ii * m + jj, -d, 1);
				if (ii + 1 < n && a[ii + 1][jj] != '#' && !was[ii + 1][jj]) {
					q.push({ ii + 1, jj });
					was[ii + 1][jj] = true;
				}
				if (jj + 1 < m && a[ii][jj + 1] != '#' && !was[ii][jj + 1]) {
					q.push({ ii, jj + 1 });
					was[ii][jj + 1] = true;
				}
			}
			id++;
		}
	}
	cout << -mc.min_cost(N, S, T, true).second << endl;
}

