  int s = N * M * 2, t = N * M * 2 + 1;
  int n = 0;
  REP(i, N) REP(j, M) {
    g.add_edge((i * M + j) + N * M, t, 1, 0);
    if (S[i][j] == 'o') {
      g.add_edge(s, i * M + j, 1, 0);
      n++;
      queue<int> q;
      vector<int> dist(N * M, INF);
      q.push(i * M + j);
      dist[i * M + j] = 0;
      while (!q.empty()) {
        int v = q.front();
        int y = v / M, x = v % M;
        q.pop();
        g.add_edge(i * M + j, (y * M + x) + N * M, 1, INF - dist[y * M + x]);
        if (y < N - 1 && S[y + 1][x] != '#' && dist[(y + 1) * M + x] == INF) {
          dist[(y + 1) * M + x] = dist[v] + 1;
          q.push((y + 1) * M + x);
        }
        if (x < M - 1 && S[y][x + 1] != '#' && dist[y * M + x + 1] == INF) {
          dist[y * M + x + 1] = dist[v] + 1;
          q.push(y * M + x + 1);
        }
      }
    }
  }
  // g.add_edge(s, t, n, INF);
  auto res = g.flow(s, t, n);
  io.writeln(INF * n - res.second);
