    dps.push_back(dp);
  }

  int src = sz(p) + n * m, dst = src + 1;
  atcoder::mcf_graph<int, int> g(dst + 1);
  const int big = n * m * 2;
  rep(i, sz(p)) {
    g.add_edge(src, i, 1, 0);
    rep(r, n) rep(c, m) if (int cap = dps[i][r][c]; cap != -1) {
      int index = sz(p) + m * r + c;
      g.add_edge(i, index, 1, big - cap);
