  }
  rep(r, n) rep(c, m) {
    int index = sz(p) + m * r + c;
    g.add_edge(index, dst, 1, 0);
  }

  auto [cap, cost] = g.flow(src, dst);
  wt(cap * big - cost);

  // Debug
  V<string> res(s);
  rep(r, n) rep(c, m) if (res[r][c] == 'o') res[r][c] = '.';
  for (const auto& e : g.edges()) {
    if (e.to == dst && e.flow == 1) {
      int rc = e.from - sz(p);
      res[rc / m][rc % m] = 'o';
    }
  }
  rep(i, n) dbg(res[i]);
}

