        return result;
    }

  private:
    int _n;

    struct _edge {
        int to, rev;
        Cap cap;
        Cost cost;
    };

    std::vector<std::pair<int, int>> pos;
    std::vector<std::vector<_edge>> g;
};


int main(int argc, char *argv[]) {
  i64 N, M, i, j;
  cin >> N >> M;
  vector<string> S(N);
  REP(0, N, i) {
    cin >> S[i];
  }

  mcf_graph<i64, i64> g(N * M + 2);
  i64 source = N * M;
  i64 sink = N * M + 1;

  auto id = [&](i64 i, i64 j) {
    return i * M + j;
  };

  auto cost = [&](i64 i, i64 j) {
    return (N - 1 - i) + (M - 1 - j);
  };

  i64 CAP = N * M;
  i64 c_init = 0;
  // source, sink edges
  REP(0, N, i) {
    REP(0, M, j) {
      if(S[i][j] == 'o') {
	g.add_edge(source, id(i, j), 1, 0);
	c_init += cost(i, j);
      }
      if(S[i][j] != '#') {
	g.add_edge(id(i, j), sink, 1, cost(i, j));
      }
    }
  }

  // vertical edges
  REP(0, N, i) {
    REP(0, M, j) {
      if(i != N-1 && S[i][j] != '#' && S[i+1][j] != '#') {
	g.add_edge(id(i, j), id(i+1, j), CAP, 0);
      }
      if(j != M-1 && S[i][j] != '#' && S[i][j+1] != '#') {
	g.add_edge(id(i, j), id(i, j+1), CAP, 0);
      }
    }
  }

  auto p = g.flow(source, sink);
  //cerr << "cost " << p.second << " flow " << p.first << endl;
  cout << c_init - p.second << endl;

  return 0;
}

