void solve() {
  ini(N, M);
  vs S(N);
  in(S);

  mcf_graph<int, ll> graph(N * M + 2);
  int start = N * M;
  int goal = N * M + 1;

  auto id = [&](int i, int j) { return i * M + j; };
  auto co = [&](int i, int j) { return inf - i - j; };
  ll pre = 0;
  ll cnt = 0;

  rep(i, N) rep(j, M) {
    if (S[i][j] == '.') {
      graph.add_edge(id(i, j), goal, 1, co(i, j));
    } else if (S[i][j] == 'o') {
      graph.add_edge(start, id(i, j), 1, 0);
      pre += co(i, j);
      graph.add_edge(id(i, j), goal, 1, co(i, j));
      cnt++;
    }

    if (i != N - 1) {
      if (S[i][j] != '#' && S[i + 1][j] != '#') {
        graph.add_edge(id(i, j), id(i + 1, j), 100, 0);
      }
    }
    if (j != M - 1) {
      if (S[i][j] != '#' && S[i][j + 1] != '#') {
        graph.add_edge(id(i, j), id(i, j + 1), 100, 0);
      }
    }
  }

  ll mf = graph.flow(start, goal, cnt).second;
  out(pre - mf);
}

