void solve()
{
    int n, m;
    scanf("%d%d", &n, &m);
    int i, j;
    for (i = 0; i < n; i++) {
        scanf("%s", str[i]);
    }
#define POSI(i,j) ((i)*m+(j))

    int num = n * m;
    for (i = 0; i < num; i++) {
        for (j = 0; j < num; j++) {
            d[i][j] = (i == j ? 0 : INF2);
        }
    }

    vector<int> v;
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
            if (str[i][j] == '#') continue;
            if (str[i][j] == 'o') v.push_back(POSI(i, j));

            {
                int i2 = i + 1, j2 = j;
                if (i2 < n && str[i2][j2]!='#') {
                    d[POSI(i, j)][POSI(i2, j2)] = 1;
                }
            }
            {
                int i2 = i, j2 = j+1;
                if (j2 < m && str[i2][j2] != '#') {
                    d[POSI(i, j)][POSI(i2, j2)] = 1;
                }
            }
        }
    }

    {
        for (int k = 0; k < num; ++k)
            for (int i = 0; i < num; ++i)
                for (int j = 0; j < num; ++j) d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
    }

    int sizv = v.size();
    /**
     * generate (s -> o -> all -> t) graph
     * i-th o    correspond to vertex i
     * i-th posi correspond to vertex sizv + i
     **/
    mcf_graph<int, long long> g(sizv + num + 2);
    int s = sizv+num, t = s+1;
    const long long BIG = 1'000'000'000;

    // we can "waste" the flow
    g.add_edge(s, t, num, BIG);

    int k;
    for (k = 0; k < sizv; k++) {
        g.add_edge(s, k, 1, 0);
    }
    for (i = 0; i < num; i++) {
        g.add_edge(sizv+i, t, 1, 0);
    }
    for (k = 0; k < sizv; k++) {
        for (i = 0; i < num; i++) {
            if (d[v[k]][i] == INF2) {
                ;
            }
            else {
                g.add_edge(k, sizv + i, 1, -d[v[k]][i]);
            }
        }
    }
    auto result = g.flow(s, t, sizv);
    printf("%lld\n", -result.second);

    return;
}

