  for(int i=0;i<d.size();i++) g.add_edge(S, 2700+i, 1LL, 0LL);
  for(int i=0;i<n;i++){
    for(int j=0;j<m;j++){
      if(s[i][j]=='#') continue;
      g.add_edge(i*m+j, T, 1LL, 0LL);
    }
  }

  //各コマについて、各空きマスに辺を伸ばす
  for(int i=0;i<d.size();i++){
    ll x = d[i][0], y = d[i][1];
    dj.dijkstra(x*m+y);
    for(int j=0;j<n;j++){
      for(int k=0;k<m;k++){
        if(s[j][k]=='#') continue;
        ll dist = dj[j*m+k];
        if(dist==dj.INF) continue;
        g.add_edge(2700+i, j*m+k, 1, -dist);//dist回移動できる
      }
    }
  }

  auto L = g.flow();

  std::cout << -L.second << '\n';
}

