int64 N, M;
int64 ptoi(int64 y, int64 x) {
  return y * M + x;
}

PLL itop(int64 p) {
  return PLL(p / M, p % M);
}

int64 dy[2] = {1, 0};
int64 dx[2] = {0, 1};

int main(void){
	cin.tie(0);
	ios::sync_with_stdio(false);

	constexpr int64 inf = 1000000, inf2 = INF*1000;
	cin >> N >> M;
	vector<string> s(N);
	REP(i, N) cin >> s[i];
	mcf_graph<int64, int64> mcf(2*N*M+2);
	int64 S = 2*N*M, G = 2*N*M+1;
	int64 cnt = 0;
	auto ok = make_v<int>(N*M, N*M);
	REP(i, N) {
	  REP(j, M) {
	    ok[ptoi(i, j)][ptoi(i, j)] = 1;
	    if (s[i][j] == '#') continue;
	    mcf.add_edge(N*M+ptoi(i, j), G, 1, 0);
	    if (s[i][j] == 'o') {
	      mcf.add_edge(S, ptoi(i, j), 1, 0);
	      cnt++;
	    }
	    REP(k, 2) {
	      int64 yy = i + dy[k], xx = j + dx[k];
	      if (yy >= N || xx >= M || s[yy][xx] == '#') continue;
	      ok[ptoi(i, j)][ptoi(yy, xx)] = 1;
	    }
	  }
	}
	REP(k, N*M) {
	  REP(i, N*M) {
	    REP(j, N*M) {
	      ok[i][j] |= ok[i][k] & ok[k][j];
	    }
	  }
	}
	REP(i, N*M) {
	  REP(j, N*M) {
	    if (!ok[i][j]) continue;
	    PLL p1 = itop(i), p2 = itop(j);
	    if (s[p1.fs][p1.sc] != 'o') break;
	    mcf.add_edge(i, j+N*M, 1, INF-abs(p1.fs - p2.fs)-abs(p1.sc-p2.sc));
	  }
	}
	PLL ret = mcf.flow(S, G, cnt);
	int64 res = cnt * INF - ret.sc;
	for (auto &e : mcf.edges()) {
	  if (e.cap != 0 && e.flow != 0) {
	    if (e.from <= N*M && e.to <= 2*N*M) {
	      PLL p1 = itop(e.from), p2 = itop(e.to-N*M);
	    }
	  }
	}
	cout << res << endl;
}

