inline void add(int u,int v,int w,int c){
	to[++cnt]=v,flow[cnt]=w,cost[cnt]=c,nxt[cnt]=head[u],head[u]=cnt;
	to[++cnt]=u,flow[cnt]=0,cost[cnt]=-c,nxt[cnt]=head[v],head[v]=cnt;
}
bool vis[N]; int pre[N],dep[N];
inline bool spfa(int s,int t){
	memset(vis,0,sizeof(vis));
	memset(pre,-1,sizeof(pre));
	memset(dep,128,sizeof(dep));
	std::queue<int> q;
	q.push(s),dep[s]=0,vis[s]=1;
	int inf=dep[0];
	while(!q.empty()){
		int u=q.front(); q.pop();
		vis[u]=0;
		for(int i=head[u];i;i=nxt[i]){
			if(flow[i]&&dep[to[i]]<dep[u]+cost[i]){
				dep[to[i]]=dep[u]+cost[i],pre[to[i]]=i;
				if(!vis[to[i]]) vis[to[i]]=1,q.push(to[i]);
			}
		}
	}
	return dep[t]!=inf;
}
inline std::pair<int,int> mcmf(int s,int t){
	std::pair<int,int> ret(0,0);
	while(spfa(s,t)){
		int mi=2e9;
		for(int i=t;i!=s;i=to[pre[i]^1]) mi=std::min(mi,flow[pre[i]]);
		for(int i=t;i!=s;i=to[pre[i]^1]) flow[pre[i]]-=mi,flow[pre[i]^1]+=mi;
		ret.first+=mi,ret.second+=dep[t]*mi;
	}
	return ret;
}
