ll hungarian() { // Return the matching job->worker but in 1-indexing -> job[1] = 2
    vi mtch(m + 1) ; // mtch[i] = job assigned to person i in current matching
    vll u(n + 1) ;
    vll v(m + 1) ;
    vi way(m + 1) ;
    vi pre(m + 1) ;
    rep(i,1,n) { // Augment from i by finding an increasing chain - Kuhn
            vll dist(m + 1, infl) ;
            vb vis(m + 1, false) ;
            int cur_per = 0 ;
            mtch[cur_per] = i ;
            while(mtch[cur_per]) { // While there is an not an unsaturated person
                int cur_job = mtch[cur_per] ;
                vis[cur_per] = true ;
                ll delta = infl ;
                int nxt_per ;
                rep(j,1,m) {
                        if(!vis[j]) {
                            ll val = a[cur_job][j] - u[cur_job] - v[j] ;
                            if(val < dist[j]) {
                                dist[j] = val ;
                                way[j] = cur_per ;
                            }
                            if(dist[j] < delta) {
                                delta = dist[j] ;
                                nxt_per = j ;
                            }
                        }
                }
                rep(j,0,m) {
                        if(vis[j]) {
                            u[mtch[j]] += delta ;
                            v[j] -= delta ;
                        }
                        else {
                            dist[j] -= delta ;
                        }
                }
                cur_per = nxt_per ;
            }
            while(cur_per) { // Flip the matching
                int prev_per = way[cur_per] ;
                mtch[cur_per] = mtch[prev_per] ;
                cur_per = prev_per ;
            }
    }
    return -v[0];
}
