	}
	rep(i, n){
		rep(j, m){
			if(c[i][j] == 'o') {
				v.pb(Edge(sink, i * m + j + 1, 1, 0));
			}
		}
	}
	rep(i, n){
		rep(j, m){
			if(c[i][j] != 'o') continue;
			int id = i * m + j + 1;
			vector<vector<int> > u(n, vector<int> (m));
			queue<pair<int, pii> > q;
			q.push({i, {j, 0}});
			u[i][j] = 1;
			while(!q.empty()){
				pair<int, pii> p = q.front();
				q.pop();
				int curid = p.S.F + p.F * m + 1;
				Edge e1(id, curid, 1, -p.S.S);
				// Edge e2(curid, id, 1, p.S.S);
				v.pb(e1); //v.pb(e2);
				if(p.S.F + 1 < m and p.S.S + 1 > u[p.F][p.S.F + 1] and c[p.F][p.S.F + 1] != '#') {
					u[p.F][p.S.F + 1] = p.S.S + 1;
					q.push({p.F, {p.S.F + 1, p.S.S + 1}});
				}
				if(p.F + 1 < n and p.S.S + 1 > u[p.F + 1][p.S.F] and c[p.F + 1][p.S.F] != '#'){
					u[p.F + 1][p.S.F] = p.S.S + 1;
					q.push({p.F + 1, {p.S.F, p.S.S + 1}});
				}
			}
		}
	}
	rep(i, n){
		rep(j, m){
			if(c[i][j] == '.' || c[i][j] == 'o') {
				v.pb(Edge(i * m + j + 1, flow, 1, 0));
			}
		}
	}
	cout << -min_cost_flow(flow + 2, v, inf, sink, flow);
