    vector<pair<ll, ll>> p;
    REP(i, n) REP(j, m) {
        if (s[i][j] == 'o') {
            p.emplace_back(i, j);
        }
    }

    mcf_graph<ll, ll> g(p.size()+n*m+2);

    REP(w, p.size()) {
        auto [i, j] = p[w];
        vector d(n, vector(m, LINF));
        deque<pair<ll, ll>> q;
        d[i][j] = 0;
        q.emplace_back(i, j);
        while (q.size()) {
            auto [u, v] = q.front();
            q.pop_front();
            if (u+1 < n && s[u+1][v] != '#') {
                if (chmin(d[u+1][v], d[u][v] + 1)) {
                    q.emplace_back(u+1, v);
                }
            }
            if (v+1 < m && s[u][v+1] != '#') {
                if (chmin(d[u][v+1], d[u][v] + 1)) {
                    q.emplace_back(u, v+1);
                }
            }
        }

        REP(i, n) REP(j, m) {
            if (d[i][j] < LINF) {
                g.add_edge(w, p.size()+i*m+j, 1, n*m-d[i][j]);
            }
        }
    }

    REP(w, p.size())
        g.add_edge(p.size()+n*m, w, 1, 0);

    REP(i, n) REP(j, m)
        g.add_edge(p.size()+i*m+j, p.size()+n*m+1, 1, 0);

    auto [cap, cost] = g.flow(p.size()+n*m, p.size()+n*m+1);

    DUMP(tuple(cap, cost));
    say(cap*n*m-cost);

}

