  int N, M;
  cin >> N >> M;
  vector<string> S(N);
  for(int i = 0; i < N; ++i){
    cin >> S[i];
  }
  MinCostFlowGraph G(N*M+2);
  int source = N*M, sink = source+1;
  int c = 0, INF = 1e9;
  for(int i = 0; i < N; ++i){
    for(int j = 0; j < N; ++j){
      if(S[i][j] == '#') continue;
      int v = i*M+j;
