class CMovingPieces {

    static const int MAX = 100;

public:
	void solve(std::istream& in, std::ostream& out) {
        int n, m;
        in >> n >> m;
        vector<str> grid(n);
        in >> grid;
        SimpleGraph graph(n * m);
        FOR(i, 0, n) {
            FOR(j, 0, m) {
                if (grid[i][j] != '#') {
                    int u = i * m + j;
                    if (i + 1 < n and grid[i + 1][j] != '#') {
                        int v = (i + 1) * m + j;
                        graph.addEdge(u, v);
                    }
                    if (j + 1 < m and grid[i][j + 1] != '#') {
                        int v = i * m + j + 1;
                        graph.addEdge(u, v);
                    }
                }
            }
        }
        int source = 2 * n * m, sink = source + 1, N = sink + 1;
        atcoder::mcf_graph<int, int> mcf(N);
        FOR(i, 0, n) {
            FOR(j, 0, m) {
                mcf.add_edge((n + i) * m + j, sink, 1, 0);
                if (grid[i][j] == 'o') {
                    int u = i * m + j;
                    mcf.add_edge(source, u, 1, 0);
                    vi dists = bfsDistances(graph, u);
                    FOR(v, 0, n * m) {
                        if (dists[v] != -1) {
                            mcf.add_edge(u, n * m + v, INT_MAX, MAX - dists[v]);
                        }
                    }
                }
            }
        }
        auto result = mcf.flow(source, sink);
        int res = result.f * MAX - result.s;
        out << res << '\n';
	}

	void setup() {}
};


