int N, M;
vector<vector<char>> grid;

int solve(int cury, int curx) {
	vector<vi> dp (N, vi (M, -2));
	dp[cury][curx] = 0;
	R0F(i, N) R0F(j, M) if (grid[i][j] == '.' || grid[i][j] == 'o') {
		dp[i][j] = 0;
		if (i + 1 < N) dp[i][j] = max(dp[i][j], 1 + dp[i+1][j]);
		if (j + 1 < M) dp[i][j] = max(dp[i][j], 1 + dp[i][j+1]);
		if (grid[i][j] == 0 && dp[i][j] == 0) dp[i][j] = -2;
	}

	int cur_ans = dp[cury][curx];

	grid[cury][curx] = '.';

	int ny = cury;
	int nx = curx;
	while (dp[ny][nx] != 0) {
		int oldx = nx;
		int oldy = ny;

		if (ny + 1 < N && dp[ny][nx] == 1 + dp[ny+1][nx]) ++ny;
		else if (nx + 1 < M && dp[ny][nx] == 1 + dp[ny][nx+1]) ++nx;
		if (grid[ny][nx] == 'o') {
			swap(grid[ny][nx], grid[oldy][oldx]); cur_ans--;
		}
	}

	grid[ny][nx] = 'x';
	return cur_ans;
}

int main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> N >> M;
	grid = vector<vector<char>> (N, vector<char> (M, '.'));
	F0R(i, N) F0R(j, M) cin >> grid[i][j];

	int ans = 0;
	F0R(i, N) F0R(j, M) while (grid[i][j] == 'o'){
		ans += solve(i, j);
	}
	print(ans);
}

