// Successive shortest paths algorithm.
template <class cap_t, class cost_t, bool density_tag = false>
class min_cost_flow : public flow_base<cap_t, cost_t> {
  using base = flow_base<cap_t, cost_t>;
  using edge_t = typename base::edge_t;
  using base::adjs;
  using base::nil;

  cost_t min_cost, total_cost;
  std::vector<cap_t> supp;
  std::vector<cost_t> ptnl;

  void copy_member(const min_cost_flow &other) {
    min_cost = other.min_cost;
    total_cost = other.total_cost;
    supp = other.supp;
    ptnl = other.ptnl;
  }

  void Dijkstra(std::vector<edge_t *> &last) {
    const cost_t infty(total_cost + 1);
    std::vector<cost_t> nptnl(size(), infty);
    if constexpr (density_tag) {
      // O(V^2)
      std::vector<bool> used(size());
      for (size_t src{}; src != size(); ++src) {
        if (static_cast<cap_t>(0) < supp[src]) {
          used[src] = true;
          nptnl[src] = 0;
          for (edge_t &e : adjs[src]) {
            if (static_cast<cap_t>(0) < supp[e.dst]) continue;
            if (e.avbl() && e.cost < nptnl[e.dst]) {
              nptnl[e.dst] = e.cost;
              last[e.dst] = &e;
            }
          }
        }
      }
      for (;;) {
        size_t src{nil};
        cost_t sp{infty};
        for (size_t node{}; node != size(); ++node) {
          if (used[node] || nptnl[node] == infty) continue;
          cost_t dist{nptnl[node] - ptnl[node]};
          if (dist < sp) {
            sp = dist;
            src = node;
          }
        }
        if (src == nil) break;
        used[src] = true;
        for (edge_t &e : adjs[src]) {
          if (e.avbl() && nptnl[src] + e.cost < nptnl[e.dst]) {
            nptnl[e.dst] = nptnl[src] + e.cost;
            last[e.dst] = &e;
          }
        }
      }
    } else {
      // O((V + E)logV)
      struct node_t {
        size_t id;
        cost_t dist;
        node_t(size_t id, cost_t dist) : id(id), dist(dist) {}
        bool operator<(const node_t &rhs) const { return rhs.dist < dist; }
      };
      std::priority_queue<node_t> que;
      for (size_t src{}; src != size(); ++src) {
        if (supp[src] > static_cast<cap_t>(0)) {
          nptnl[src] = 0;
          for (edge_t &e : adjs[src]) {
            if (supp[e.dst] > static_cast<cap_t>(0)) continue;
            if (e.avbl() && nptnl[e.dst] > e.cost) {
              que.emplace(e.dst, (nptnl[e.dst] = e.cost) - ptnl[e.dst]);
              last[e.dst] = &e;
            }
          }
        }
      }
      while (!que.empty()) {
        auto [src, ndist] = que.top();
        que.pop();
        if (ndist + ptnl[src] != nptnl[src]) continue;
        for (edge_t &e : adjs[src]) {
          if (e.avbl() && nptnl[e.dst] > nptnl[src] + e.cost) {
            que.emplace(e.dst,
                        (nptnl[e.dst] = nptnl[src] + e.cost) - ptnl[e.dst]);
            last[e.dst] = &e;
          }
        }
      }
    }
    ptnl.swap(nptnl);
  }

 public:
  using base::size;

  min_cost_flow(size_t n = 0)
      : base::flow_base(n), min_cost(0), total_cost(0), supp(n), ptnl(n) {}

  min_cost_flow(const min_cost_flow &other) : base::flow_base(other) {
    copy_member(other);
  }

  min_cost_flow &operator=(const min_cost_flow &other) {
    base::operator=(other);
    copy_member(other);
    return *this;
  }

  edge_t *add_edge(size_t src, size_t dst, const cost_t &cost);

  edge_t *add_edge(size_t src, size_t dst, const cap_t &cap,
                   const cost_t &cost) override {
    assert(src != dst);
    if (cost < static_cast<cost_t>(0)) {
      supp[src] -= cap;
      supp[dst] += cap;
      min_cost += cap * cost;
      total_cost -= cap * cost;
      return base::add_edge(dst, src, cap, -cost);
    }
    total_cost += cap * cost;
    return base::add_edge(src, dst, cap, cost);
  }

  edge_t *add_edge(size_t src, size_t dst, const cap_t &lower,
                   const cap_t &upper, const cost_t &cost) {
    assert(!(upper < lower));
    supp[src] -= lower;
    supp[dst] += lower;
    min_cost += lower * cost;
    return add_edge(src, dst, upper - lower, cost);
  }

  const cap_t &supply(size_t node, const cap_t &vol = 0) {
    assert(node < size());
    return supp[node] += vol;
  }

  const cap_t &demand(size_t node, const cap_t &vol) {
    return supply(node, -vol);
  }

  bool flow() {
    for (bool aug = true; aug;) {
      aug = false;
      std::vector<edge_t *> last(size());
      Dijkstra(last);
      std::vector<bool> shut(size());
      for (size_t dst{}; dst != size(); ++dst) {
        if (supp[dst] < static_cast<cap_t>(0) and last[dst]) {
          cap_t resid{-supp[dst]};
          size_t src{dst}, block{nil};
          while (last[src] && !shut[src]) {
            if (!(resid < last[src]->cap)) resid = last[block = src]->cap;
            src = last[src]->src;
          }
          if (shut[src])
            block = src;
          else {
            if (!(resid < supp[src])) {
              resid = supp[src];
              block = src;
            }
            for (edge_t *e{last[dst]}; e; e = last[e->src]) {
              e->cap -= resid;
              e->rev->cap += resid;
            }
            supp[src] -= resid;
            supp[dst] += resid;
            min_cost += ptnl[dst] * resid;
            aug = true;
          }
          if (~block) {
            for (size_t node{dst};; node = last[node]->src) {
              shut[node] = true;
              if (node == block) break;
            }
          }
        }
      }
    }
    return std::none_of(begin(supp), end(supp),
                        [](const cap_t &s) { return s < 0 || 0 < s; });
  }

  cost_t optimal() {
    assert(flow());
    return min_cost;
  }
};  // class min_cost_flow
