int Hungarian(int x, int y){
//    fill(U, U+x+1, 0);
//    fill(V, V+y+1, 0);
//    fill(match, match+y+1, 0);
//    fill(way, way+y+1, 0);

    for(int i = 1; i<=x; i++){
        match[0] = i;
        int lastJ = 0;
        fill(minV, minV+y+1, inf);
        fill(used, used+y+1, false);
        do{
            used[lastJ] = true;
            int lastI = match[lastJ], delta = inf, nextJ;
            for(int j = 1; j<=y; j++){
                if(used[j]) continue;
                int diffCost = matrix[lastI][j] - U[lastI] - V[j];
                if(diffCost < minV[j]) minV[j] = diffCost, way[j] = lastJ;
                if(minV[j] < delta) delta = minV[j], nextJ = j;
            }
            for(int j = 0; j<=y; j++){
                if(used[j]) U[match[j]] += delta, V[j] -= delta;
                else        minV[j] -= delta;
            }
            lastJ = nextJ;
        } while(match[lastJ] != 0);
        do{
            int prevJ = way[lastJ];
            match[lastJ] = match[prevJ];
            lastJ = prevJ;
        } while(lastJ != 0);
    }
    return -V[0];
}

