struct UnionFind
{
    vector<int> par, rank, sz, maxv;
    UnionFind(int N) : par(N), rank(N), sz(N), maxv(N)
    {
        REP(i, N)
        {
            par[i] = i;  //the parent of the node
            rank[i] = 0; //the rank of the tree
            sz[i] = 1;
            maxv[i] = 1;
        }
    }
    int find(int x)
    { //Find the root of x
        if (par[x] == x)
        {
            return x;
        }
        else
        {
            return par[x] = find(par[x]);
        }
    }
    int size(int x)
    {
        return sz[find(x)];
    }
    int maxval(int x)
    {
        return maxv[find(x)];
    }
    void unite(int x, int y)
    { //Unite (the set of x) and (the set of y)
        x = find(x), y = find(y);
        if (x == y)
            return;
        if (rank[x] < rank[y])
        { //larger rank is above
            sz[y] += sz[x];
            maxv[y] = max(maxv[y], maxv[x]);
            par[x] = y;
        }
        else
        {
            sz[x] += sz[y];
            maxv[x] = max(maxv[y], maxv[x]);
            par[y] = x;
            if (rank[x] == rank[y])
                rank[x]++;
        }
    }
    bool same(int x, int y)
    {
        return find(x) == find(y);
    }
};


void solve() {
    int n, m;
    cin >> n >> m;
    vector<vector<char>> G(n, vector<char>(m));
    set<pint> maru;
    REP(i, n) {
        REP(j, m) {
            cin >> G[i][j];
            if (G[i][j] == 'o') {
                maru.insert(make_pair(i,j));
            }
        }
    }
    ll ans = 0;
    IREP(i, n) {
        REP(j, m) {
            pint st = make_pair(i,j);
            if (maru.find(st) != maru.end()) {
                queue<pint> que;
                que.push(st);
                vector<vector<int>> dist(n, vector<int>(m, 0));
                int maxdist = 0;
                pint maxdistpos = st;
                while (que.size()) {
                    pint now = que.front(); que.pop();
                    pint newnow {now.FI + 1, now.SE};
                    if (newnow.FI <= n - 1 && newnow.SE <= m - 1 && G[newnow.FI][newnow.SE] == '.') {
                        dist[newnow.FI][newnow.SE] = dist[now.FI][now.SE] + 1;
                        if (maxdist < dist[newnow.FI][newnow.SE]) {
                            maxdistpos = newnow;
                        }
                        maxdist = max(maxdist, dist[newnow.FI][newnow.SE]);
                        que.push(newnow);
                    }
                    newnow = make_pair(now.FI, now.SE + 1);
                    if (newnow.FI <= n - 1 && newnow.SE <= m - 1 && G[newnow.FI][newnow.SE] == '.') {
                        dist[newnow.FI][newnow.SE] = dist[now.FI][now.SE] + 1;
                        if (maxdist < dist[newnow.FI][newnow.SE]) {
                            maxdistpos = newnow;
                        }
                        maxdist = max(maxdist, dist[newnow.FI][newnow.SE]);
                        que.push(newnow);
                    }
                }
                ans += maxdist;
                G[st.FI][st.SE] = '.';
                G[maxdistpos.FI][maxdistpos.SE] = 'o';
            }
        }
    }
    cout << ans << endl;
}

