constexpr int kN = int(1E4 + 10), kInf = int(1E9 + 10);

#define F first
#define S second
struct Edge {
  int to, rev, cost, flow;
};
vector<Edge> graph[kN];
pair<int, int> dis[kN];
int from[kN];
void AddEdge(int u, int v, int f, int c) {
  graph[u].push_back(
    {v, int(graph[v].size()), c, f});
  graph[v].push_back(
    {u, int(graph[u].size()) - 1, -c, 0});
  return;
}
pair<int, int> MCMF(int s, int t) {
  priority_queue<pair<int, int>,
    vector<pair<int, int>>,
    greater<pair<int, int>>>
    pq;
  pair<int, int> nxt;
  int now, flow;
  for (int i = 0; i < kN; i++)
    dis[i] = {
      kInf, 0};  // don't necessarily need kN
  dis[s] = {0, kInf};

  pq.push({dis[s].F, s});
  while (!pq.empty()) {
    nxt = pq.top();
    pq.pop();
    if (nxt.F > dis[nxt.S].F) continue;
    for (Edge i : graph[nxt.S])
      if (i.flow > 0 &&
        i.cost + nxt.F < dis[i.to].F) {
        dis[i.to] = {nxt.F + i.cost,
          min(dis[nxt.S].S, i.flow)};
        from[i.to] = i.rev;
        pq.push({dis[i.to].F, i.to});
      }
  }
  if (dis[t].F >= kInf) return dis[t];
  flow = dis[t].S;
  now = t;
  while (now != s) {
    graph[now][from[now]].flow += flow;
    graph[graph[now][from[now]].to]
         [graph[now][from[now]].rev]
           .flow -= flow;
    now = graph[now][from[now]].to;
  }
  return dis[t];
}


