template <class T>
std::vector<T> vec(int len, T elem) { return std::vector<T>(len, elem); }

const std::vector<std::pair<int, int>> dxys{{0, 1}, {1, 0}};

constexpr int M = 5000;

void solve() {
    int h, w;
    std::cin >> h >> w;

    auto enc = [&](int x, int y) { return x * w + y; };

    std::vector<std::string> ss(h);
    for (auto& s : ss) std::cin >> s;

    int s = h * w * 2, g = s + 1;
    ac::mcf_graph<int, int> graph(h * w * 2 + 2);

    int snum = 0;
    for (int x = 0; x < h; ++x) {
        for (int y = 0; y < w; ++y) {
            if (ss[x][y] == 'o') {
                graph.add_edge(s, enc(x, y), 1, 0);
                ++snum;
            }
            graph.add_edge(enc(x, y) + h * w, g, 1, 0);
        }
    }

    for (int sx = 0; sx < h; ++sx) {
        for (int sy = 0; sy < w; ++sy) {
            if (ss[sx][sy] != 'o') continue;

            auto dist = vec(h, vec(w, -1));
            dist[sx][sy] = 0;
            std::queue<std::pair<int, int>> que;
            que.emplace(sx, sy);

            while (!que.empty()) {
                auto [x, y] = que.front();
                que.pop();

                for (auto [dx, dy] : dxys) {
                    int nx = x + dx,
                        ny = y + dy;
                    if (nx < 0 || h <= nx ||
                        ny < 0 || w <= ny ||
                        ss[nx][ny] == '#' ||
                        dist[nx][ny] != -1) continue;

                    dist[nx][ny] = dist[x][y] + 1;
                    que.emplace(nx, ny);
                }
            }

            for (int x = 0; x < h; ++x) {
                for (int y = 0; y < w; ++y) {
                    if (dist[x][y] == -1) continue;
                    graph.add_edge(enc(sx, sy), enc(x, y) + h * w, 1, M - dist[x][y]);
                }
            }
        }
    }

    auto [f, c] = graph.flow(s, g, snum);
    std::cout << M * f - c << "\n";
}

int main() {
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    solve();

    return 0;
}

