int N, M;
vector<vector<char>> grid;

int solve(int cury, int curx) {
	vector<vi> dp (N, vi (M, -2));
	dp[cury][curx] = 0;
	R0F(i, N) R0F(j, M) if (grid[i][j] == '.' || (i == cury && j == curx)) {
		dp[i][j] = 0;
		if (i + 1 < N) dp[i][j] = max(dp[i][j], 1 + dp[i+1][j]);
		if (j + 1 < M) dp[i][j] = max(dp[i][j], 1 + dp[i][j+1]);
	}

	int ny = cury;
	int nx = curx;
	while (dp[ny][nx] != 0) {
		if (ny + 1 < N && dp[ny][nx] == 1 + dp[ny+1][nx]) ++ny;
		else if (nx + 1 < M && dp[ny][nx] == 1 + dp[ny][nx+1]) ++nx;
	}
	grid[cury][curx] = '.';
	grid[ny][nx] = 'x';
	return dp[cury][curx];
}

