struct Edge
{
    int from, to, capacity, cost;
    Edge() {}
    Edge(int from, int to, int capacity, int cost) : from(from), to(to), capacity(capacity), cost(cost) {}
};

vector<vector<int>> adj, cost, capacity;

const int INF = 1e9;

void shortest_paths(int n, int v0, vector<int>& d, vector<int>& p) {
    d.assign(n, INF);
    d[v0] = 0;
    vector<bool> inq(n, false);
    queue<int> q;
    q.push(v0);
    p.assign(n, -1);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inq[u] = false;
        for (int v : adj[u]) {
            if (capacity[u][v] > 0 && d[v] > d[u] + cost[u][v]) {
                d[v] = d[u] + cost[u][v];
                p[v] = u;
                if (!inq[v]) {
                    inq[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

vector<int> min_cost_flow(int N, vector<Edge> edges, int K, int s, int t) {
    adj.assign(N, vector<int>());
    cost.assign(N, vector<int>(N, 0));
    capacity.assign(N, vector<int>(N, 0));
    for (Edge e : edges) {
        adj[e.from].push_back(e.to);
        adj[e.to].push_back(e.from);
        cost[e.from][e.to] = e.cost;
        cost[e.to][e.from] = -e.cost;
        capacity[e.from][e.to] = e.capacity;
    }
    vector<int> res;
    int flow = 0;
    int cost = 0;
    vector<int> d, p;
    while (flow < K) {
        shortest_paths(N, s, d, p);
        if (d[t] == INF)
            break;

        // find max flow on that path
        int f = K - flow;
        int cur = t;
        while (cur != s) {
            f = min(f, capacity[p[cur]][cur]);
            cur = p[cur];
        }

        // apply flow
        flow += f;
        cost += f * d[t];
        cur = t;
        res.pb(cost);
        while (cur != s) {
            capacity[p[cur]][cur] -= f;
            capacity[cur][p[cur]] += f;
            cur = p[cur];
        }
    }

    return res;
}
void solve()
{ 
	int n, m;
	cin >> n >> m;
	int sink = 0, flow = n * m + (n - 1) * m + 1;
	char c[n][m];
	vector<Edge> v;
	rep(i, n) rep(j, m){
		cin >> c[i][j];
	}
	for(int i = 0; i < n; ++i){
		for(int j = 0; j < m; ++j){
			if(c[i][j] == 'o') {
				v.pb(Edge(sink, i * m + j + 1, 1, 0));
			}
			else if(c[i][j] == '.') {
				v.pb(Edge(n * m + i * m + j + 1, flow, 1, 0));
			}
		}
	}
	rep(i, n){
		rep(j, m){
			if(c[i][j] != 'o') continue;
			int id = i * m + j + 1;
			vector<vector<bool> > u(n, vector<bool> (m));
			queue<pair<int, pii> > q;
			q.push({i, {j, 0}});
			u[i][j] = 1;
			while(!q.empty()){
				pair<int, pii> p = q.front();
				q.pop();
				int curid = n * m + p.S.F + p.F * m + 1;
				Edge e1(id, curid, 1, -p.S.S);
				v.pb(e1);
				if(p.S.F + 1 < m and !u[p.F][p.S.F + 1] and c[p.F][p.S.F + 1] != '#') {
					u[p.F][p.S.F + 1] = 1;
					q.push({p.F, {p.S.F + 1, p.S.S + 1}});
				}
				if(p.F + 1 < n and !u[p.F + 1][p.S.F] and c[p.F + 1][p.S.F] != '#'){
					u[p.F + 1][p.S.F] = 1;
					q.push({p.F + 1, {p.S.F, p.S.S + 1}});
				}
			}
		}
	}
	vector<int> ans = min_cost_flow(flow * 10, v, inf, sink, flow);
	cout << -ans.back() << '\n';
}



