template<class T, T oo> struct Hungary {
    static const int MAXN = 4000 + 5;
    static const int MAXM = 4000 + 5;
    int nx, ny, maty[MAXM], frm[MAXM], used[MAXM];
    T cst[MAXN][MAXM], fx[MAXN], fy[MAXM], dst[MAXM];
    void init(int nx, int ny) {
        this->nx = nx, this->ny = ny;
        fill_n(fx, nx + 1, 0), fill_n(fy, ny + 1, 0);
        fill_n(maty, nx + 1, 0);
        for (int i = 0; i <= nx; i++) {
            fill_n(cst[i], ny + 1, oo);
        }
    }
    void add(int x, int y, int c) {
        cst[x][y] = c;
    }
    T mincost() {
        for (int x = 1; x <= nx; x++) {
            int y0 = 0;
            maty[0] = x;
            for (int y = 0; y <= ny; y++) {
                dst[y] = oo + 1;
                used[y] = 0;
            }
            do {
                used[y0] = 1;
                int x0 = maty[y0], y1;
                T delta = oo + 1;
                for (int y = 1; y <= ny; y++) if (!used[y]) {
                    T curdst = cst[x0][y] - fx[x0] - fy[y];
                    if (dst[y] > curdst) {
                        dst[y] = curdst;
                        frm[y] = y0;
                    }
                    if (delta > dst[y]) {
                        delta = dst[y];
                        y1 = y;
                    }
                }
                for (int y = 0; y <= ny; y++) if (used[y]) {
                    fx[maty[y]] += delta;
                    fy[y] -= delta;
                }
                else {
                    dst[y] -= delta;
                }
                y0 = y1;
            }
            while (maty[y0] != 0);
            do {
                int y1 = frm[y0];
                maty[y0] = maty[y1];
                y0 = y1;
            }
            while (y0);
        }
        T res = 0;
        for (int y = 1; y <= ny; y++) {
            int x = maty[y];
            if (cst[x][y] < oo) res += cst[x][y];
        }
        return res;
    }
};
Hungary<long long, (long long) 1e18> hungary;

void chemthan() {
    int n, m; cin >> n >> m;
    vector<string> s(n);
    FOR(i, 0, n) cin >> s[i];
    hungary.init(n * m, n * m);
    int num = 0;
    FOR(i, 0, n) FOR(j, 0, m) if (s[i][j] == 'o') {
        num++;
        vector<vi> dp(n, vi(m, INF));
        queue<int> que;
        dp[i][j] = 0, que.push(i), que.push(j);
        while (sz(que)) {
            int u = que.front(); que.pop();
            int v = que.front(); que.pop();
            if (u + 1 < n && s[u + 1][v] != '#') {
                if (chkmin(dp[u + 1][v], dp[u][v] + 1)) {
                    que.push(u + 1), que.push(v);
                }
            }
            if (v + 1 < m && s[u][ v + 1] != '#') {
                if (chkmin(dp[u][v + 1], dp[u][v] + 1)) {
                    que.push(u), que.push(v + 1);
                }
            }
        }
        FOR(u, 0, n) FOR(v, 0, m) if (dp[u][v] < INF) {
            hungary.add(i * m + j + 1, u * m + v + 1, 100000 - dp[u][v]);
        }
    }
    cout << (long long) 100000 * num - hungary.mincost() << "\n";
}

