bool dfs(int32 sy, int32 sx, int32 ty, int32 tx){
  cachekey ck = make_tuple(sy,sx,ty,tx);
  if(cache.count(ck) > 0)return cache[ck];
  if(s[sy][sx] == '#')return cache[ck] = false;
  if(s[ty][tx] == '#')return cache[ck] = false;
  if(sy == ty && sx == tx)return cache[ck] = true;
  if(sy > ty || sx > tx)return cache[ck] = false;
