	int H, W; cin >> H >> W;
	vector<string> vs(H); for (int i = 0; i < H; i++) cin >> vs[i];
	auto cnv = [&](int h, int w)->int {
		return h * W + w;
	};
	PrimalDual g(H * W + 2);
	int s = H * W;
	int t = H * W + 1;
	int cnt = 0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (vs[i][j] == '#') continue;
			if (vs[i][j] == 'o') {
