double kyori(pair<int, int> f, pair<int, int> s) {
    double ans = 0;
    double t = fabs(f.first - s.first);
    double y = fabs(f.second - s.second);
    ans = sqrt(t * t + y * y);
    return ans;
}

double kyori(Dot f, Dot s) {
    double ans = 0;
    double t = fabs(f.x - s.x);
    double y = fabs(f.y - s.y);
    ans = sqrt(t * t + y * y);
    return ans;
}

