public void solve() {
	int h = ni();
	int w = ni();
	Grids g = new Grids(h, w);
	char c[][] = nc(h, w);
	boolean b[][] = new boolean[h][w];
	int start[][] = new int[h][w];
	fill(start, -1);
	int numStart = 0;
	for(int i = 0; i < h; i ++) {
		for(int j = 0; j < w; j ++) {
			b[i][j] = c[i][j] == '#';
			if(c[i][j] == 'o') start[i][j] = numStart ++;
		}
	}
	g.init(b);

	int numNode = numStart + h * w + 1;
	long d[] = new long[numNode];
	for(int i = 0; i < numStart; i ++) d[i] = 1;
	d[numNode - 1] = - numStart;
	NormalizedMinCostFlow mcf = new NormalizedMinCostFlow(numNode, d);
	for(int i = 0; i < h; i ++) {
		for(int j = 0; j < w; j ++) {
			if(b[i][j]) continue;
			if(start[i][j] >= 0) {
				long dist[] = bfs(g, g.get(i, j), h, w);
				for(int i2 = 0; i2 < h; i2 ++) {
					for(int j2 = 0; j2 < w; j2 ++) {
						int idx2 = g.get(i2, j2).i;
						if(isINF(dist[idx2])) continue;
						mcf.addEdge(start[i][j], idx2 + numStart, 1, - dist[idx2]);
					}
				}
			}
			mcf.addEdge(g.get(i, j).i + numStart, numNode - 1, 1, 0);
		}
	}
	PairLL p = mcf.minCostFlow();
	prtln(- p.b);
}

long[] bfs(Grids g, Grid start, int h, int w) {
	long dist[] = new long[h * w];
	fill(dist, INF);

	Deque<Grid> s = new ArrayDeque<>();
	s.addLast(start);
	dist[start.i] = 0;
	while(!s.isEmpty()) {
		Grid crt = s.removeFirst();
		for(int add = 2; add <= 4; add += 2) {
			Grid next = g.next(crt, add);
			if(next == null || next.b) continue;
			if(isINF(dist[next.i])) {
				dist[next.i] = dist[crt.i] + 1;
				s.addLast(next);
			}
		}
	}

	return dist;
}

// WeightedCapEdge(source, target, cap, cost)
// PairLL(flow, cost)
class NormalizedMinCostFlow extends MinCostFlow { // V=numNode, E=numEdge, F=in
	long in;
	long sum;
	int s;
	int t;
	long d[];
	int idx[];
	int tsIdx;
	NormalizedMinCostFlow(int numNode, long[] d) { // O(V)
		super(numNode + 2);
		this.d = d;
		in = 0;
		sum = 0;
		s = numNode;
		t = numNode + 1;
		idx = new int[numNode];

		for(int i = 0; i < numNode; i++) {
			if(d[i] >= 0) {
				idx[i] = super.addEdge(s, i, d[i], 0);
				super.addEdge(i, t, 0, 0);
				in += d[i];
			}else {
				super.addEdge(s, i, 0, 0);
				idx[i] = super.addEdge(i, t, - d[i], 0);
			}
		}
	}

	void addDemand(int i, long addD) { if(i >= d.length) return; changeDemand(i, d[i] + addD); } // O(1)
	void changeDemand(int i, long newD) { // O(1)
		if(i >= d.length) return;
		if(d[i] > 0) in -= d[i];
		edgesList.get(idx[i]).cap = 0;
		d[i] = newD;
		if(d[i] >= 0) idx[i] &= ~1; else idx[i] |= 1;
		if(d[i] > 0) in += d[i];
		edgesList.get(idx[i]).cap = abs(d[i]);
	}

	int addEdge(int source, int target, long cap, long cost) { return addEdge(source, target, 0, cap, cost); } // O(1)
	int addEdge(int source, int target, long minCap, long maxCap, long cost) { // O(1)
		if(cost < 0) {
			sum += cost * maxCap;
			addDemand(source, - maxCap);
			addDemand(target, maxCap);
			return super.addEdge(target, source, maxCap - minCap, - cost);
		}else {
			sum += cost * minCap;
			addDemand(source, - minCap);
			addDemand(target, minCap);
			return super.addEdge(source, target, maxCap - minCap, cost);
		}
	}

	// O(F(V+E)logV)
	PairLL minCostFlow() {
		PairLL ans = minCostFlow(s, t, in);
		ans.b += sum;
		return ans;
	}
}

// WeightedCapEdge(source, target, cap, cost)
// PairLL(flow, cost)
class MinCostFlow { // V=numNode, E=numEdge
	class WeightedCapEdge {
		int source;
		int target;
		long cap;
		long cost;
		int rev;
		WeightedCapEdge(int source, int target, long cap, long cost, int rev) {
			this.source = source;
			this.target = target;
			this.cap = cap;
			this.cost = cost;
			this.rev = rev;
		}

		long getFlow() { return edges[target][rev].cap; }

		@Override
		public String toString() { return source+" - ("+cap+", "+cost+") -> "+target; }
		@Override
		public int hashCode() { return Objects.hash(source, target); }
		@Override
		public boolean equals(Object obj) {
			if(this == obj) return true;
			if(obj == null) return false;
			if(this.getClass() != obj.getClass()) return false;
			Edge that = (Edge) obj;
			if(this.source != that.source) return false;
			if(this.target != that.target) return false;
			return true;
		}
	}

	int numNode;
	int numEdge;
	List<WeightedCapEdge> edgesList;
	int len[];
	WeightedCapEdge edges[][];
	long potential[];

	MinCostFlow(int numNode) { // O(V)
		this.numNode = numNode;
		edgesList = new ArrayList<>();
		len = new int[numNode];
		edges = new WeightedCapEdge[numNode][];
		potential = new long[numNode];
		fill(potential, 0);
	}

	int addEdge(int source, int target, long cap, long cost) { // O(1)
		WeightedCapEdge e = new WeightedCapEdge(source, target, cap, cost, len[target]);
		len[source] ++;
		len[target] ++;
		edgesList.add(e);
		return numEdge ++;
	}

	void init() { // O(E)
		for(int i = 0; i < numNode; i ++) edges[i] = new WeightedCapEdge[len[i]];
		int idx[] = new int[numNode];
		for(WeightedCapEdge e : edgesList) {
			edges[e.target][idx[e.target] ++] = new WeightedCapEdge(e.target, e.source, 0, - e.cost, idx[e.source]);
			edges[e.source][idx[e.source] ++] = e;
		}
	}
	void clearFlow() { // O(V+E)
		fill(potential, 0);
		for(WeightedCapEdge e : edgesList) {
			long flow = e.getFlow();
			e.cap += flow;
			edges[e.target][e.rev].cap -= flow;
		}
	}

	// O(f(V+E)logV)
	PairLL minCostMaxFlow(int s, int t) { return minCostFlow(s, t, INF); }
	PairLL minCostFlow(int s, int t, long flowLimit) {
		PairLL[] slope = minCostSlope(s, t, flowLimit);
		return slope[slope.length - 1];
	}
	PairLL[] minCostSlope(int s, int t) { return minCostSlope(s, t, INF); }
	PairLL[] minCostSlope(int s, int t, long flowLimit) {
		if(s == t) return null;
		init();
		List<PairLL> slopeList = new ArrayList<>();
		long prvCost = -1;
		long flow = 0;
		long cost = 0;
		while(true) {
			slopeList.add(new PairLL(flow, cost));
			PairLL add = dijkstra(s, t, flowLimit - flow);
			if(add.a == 0) break;
			flow += add.a;
			cost += add.a * add.b;
			if(add.b == prvCost) slopeList.remove(slopeList.size() - 1);
			prvCost = add.b;
		}
		PairLL slope[] = new PairLL[slopeList.size()];
		for(int i = 0; i < slopeList.size(); i ++) slope[i] = slopeList.get(i);
		return slope;
	}
	PairLL dijkstra(int s, int t, long maxFlow) { // O((V+E)logV)
		long dist[] = new long[numNode];
		fill(dist, INF);
		dist[s] = 0;
		WeightedCapEdge prv[] = new WeightedCapEdge[numNode];

		Queue<Edge> pq = new PriorityQueue<>();
		pq.add(new Edge(s, s, dist[s]));
		while(!pq.isEmpty()) {
			Edge crt = pq.poll();
			if(dist[crt.target] < crt.cost) continue;
			for(WeightedCapEdge e : edges[crt.target]) {
				if(e.cap <= 0) continue;
				long cost = dist[e.source] + e.cost + potential[e.source] - potential[e.target];
				if(dist[e.target] > cost) {
					dist[e.target] = cost;
					prv[e.target] = e;
					pq.add(new Edge(e.source, e.target, dist[e.target]));
				}
			}
		}
		if(dist[t] == INF) return new PairLL(0, INF);
		for(int i = 0; i < numNode; i ++) potential[i] += dist[i];
		PairLL add = new PairLL(maxFlow, 0);
		for(int v = t; v != s; ) {
			WeightedCapEdge e = prv[v];
			add.b += e.cost;
			add.a = min(add.a, e.cap);
			v = e.source;
		}
		for(int v = t; v != s;) {
			WeightedCapEdge e = prv[v];
			e.cap -= add.a;
			edges[v][e.rev].cap += add.a;
			v = e.source;
		}
		return add;
	}
}

	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Set;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		int n = Integer.parseInt(sa[0]);
		int m = Integer.parseInt(sa[1]);
		char[][] s = new char[n][m];
		for (int i = 0; i < n; i++) {
			s[i] = br.readLine().toCharArray();
		}
		br.close();

		long BIG = 1000000000;
		MinCostFlow mf = new MinCostFlow(n * m + 2);
		int x = n * m;
		int y = x + 1;
		mf.addEdge(x, y, x, BIG);

//		test(mf, BIG, x, y);

		Queue<Integer> starts = new ArrayDeque<>();
		Set<Integer> ends = new HashSet<>();
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (s[i][j] == 'o') {
					int start = i * m + j;
					starts.add(start);
					Queue<Integer> que = new ArrayDeque<>();
					que.add(start);
					int[][] d = new int[n][m];
					d[i][j] = 1;
					while (!que.isEmpty()) {
						int cur = que.poll();
						int cx = cur / m;
						int cy = cur % m;
						if (cx < n - 1) {
							int nx = cx + 1;
							int ny = cy;
							if (d[nx][ny] == 0 && s[nx][ny] != '#') {
								d[nx][ny] = d[cx][cy] + 1;
								int next = nx * m + ny;
								que.add(next);
								if (s[nx][ny] != 'o') {
									ends.add(next);
								}
								mf.addEdge(start, next, 1, BIG - d[cx][cy]);
							}
						}
						if (cy < m - 1) {
							int nx = cx;
							int ny = cy + 1;
							if (d[nx][ny] == 0 && s[nx][ny] != '#') {
								d[nx][ny] = d[cx][cy] + 1;
								int next = nx * m + ny;
								que.add(next);
								if (s[nx][ny] != 'o') {
									ends.add(next);
								}
								mf.addEdge(start, next, 1, BIG - d[cx][cy]);
							}
						}
					}
				}
			}
		}
		while (!starts.isEmpty()) {
			mf.addEdge(x, starts.poll(), 1, 0);
		}
		for (Integer end : ends) {
			mf.addEdge(end, y, 1, 0);
		}

		long[] result = mf.flow(x, y);
		long ans = result[1] % BIG;
		ans = BIG - ans;
		ans %= BIG;
		System.out.println(ans);
	}

	static void test(MinCostFlow mf, long BIG, int x, int y) {
		mf.addEdge(0, 1, 1, BIG - 1);
		mf.addEdge(0, 2, 1, BIG - 2);
		mf.addEdge(0, 3, 1, BIG - 1);
		mf.addEdge(0, 4, 1, BIG - 2);
		mf.addEdge(0, 6, 1, BIG - 2);
		mf.addEdge(0, 5, 1, BIG - 3);
		mf.addEdge(0, 7, 1, BIG - 3);
		mf.addEdge(6, 7, 1, BIG - 1);
		mf.addEdge(x, 0, 1, 0);
		mf.addEdge(x, 6, 1, 0);
		mf.addEdge(1, y, 1, 0);
		mf.addEdge(2, y, 1, 0);
		mf.addEdge(3, y, 1, 0);
		mf.addEdge(4, y, 1, 0);
		mf.addEdge(5, y, 1, 0);
//		mf.addEdge(6, y, 1, 0);
		mf.addEdge(7, y, 1, 0);
		int cnt = 2;
		long[] result = mf.flow(x, y);
		System.out.println(BIG * cnt - result[1]);
	}
}

/**
 * 最小費用流
 */
class MinCostFlow {
	private final int n;
	private List<int[]> pos;
	private List<List<Edge2>> g;

	class Edge {
		/** 有向辺の始点 */
		final int from;
		/** 有向辺の終点 */
		final int to;
		/** 最大容量 */
		long cap;
		/** 流量 */
		long flow;
		/** コスト */
		long cost;

		public Edge(int from, int to, long cap, long flow, long cost) {
			this.from = from;
			this.to = to;
			this.cap = cap;
			this.flow = flow;
			this.cost = cost;
		}
	}

	private class Edge2 {
		final int to, rev;
		long cap, cost;

		public Edge2(int to, int rev, long cap, long cost) {
			this.to = to;
			this.rev = rev;
			this.cap = cap;
			this.cost = cost;
		}
	}

	private class Q {
		final long key;
		final int to;

		public Q(long key, int to) {
			this.key = key;
			this.to = to;
		}
	}

	/**
	 * n頂点0辺のグラフを作る。<br>
	 * O(n)
	 * 
	 * @param n 頂点数
	 */
	public MinCostFlow(int n) {
		this.n = n;
		pos = new ArrayList<>();
		g = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			g.add(new ArrayList<>());
		}
	}

	/**
	 * fromからtoへ最大容量cap、コストcostの辺を追加する。<br>
	 * ならしO(1)
	 * 
	 * @param from 有向辺の始点（0≦from＜n）
	 * @param to 有向辺の終点（0≦to＜n）
	 * @param cap 最大容量（0≦cap）
	 * @param cost コスト（0≦cost）
	 * @return 何番目に追加された辺か
	 */
	int addEdge(int from, int to, long cap, long cost) {
		assert 0 <= from && from < n : "from=" + from;
		assert 0 <= to && to < n : "to=" + to;
		assert 0 <= cap : "cap=" + cap;
		assert 0 <= cost : "cost=" + cost;

		int m = pos.size();
		pos.add(new int[] { from, g.get(from).size() });
		g.get(from).add(new Edge2(to, g.get(to).size(), cap, cost));
		g.get(to).add(new Edge2(from, g.get(from).size() - 1, 0, -cost));
		return m;
	}

	/**
	 * i番目に追加された辺を取得する。<br>
	 * O(1)
	 * 
	 * @param i 辺のインデックス（0≦i＜辺数）
	 * @return 辺情報
	 */
	Edge getEdge(int i) {
		assert 0 <= i && i < pos.size() : "i=" + i + ", size=" + pos.size();

		Edge2 e = g.get(pos.get(i)[0]).get(pos.get(i)[1]);
		Edge2 re = g.get(e.to).get(e.rev);
		return new Edge(pos.get(i)[0], e.to, e.cap + re.cap, re.cap, e.cost);
	}

	/**
	 * 全ての辺を取得する。<br>
	 * O(辺数)
	 * 
	 * @return 辺情報リスト
	 */
	List<Edge> edges() {
		int m = pos.size();
		List<Edge> result = new ArrayList<>(m);
		for (int i = 0; i < m; i++) {
			result.add(getEdge(i));
		}
		return result;
	}

	/**
	 * 最小費用流。頂点sからtへ流せるだけ流す。<br>
	 * Fを流量、mを辺数として、O(F(n + m) log n)
	 * 
	 * @param s 始点（0≦s＜n）
	 * @param t 終点（0≦t＜n）
	 * @return [0]：流せた量、[1]：その時のコスト
	 */
	long[] flow(int s, int t) {
		return flow(s, t, Long.MAX_VALUE);
	}

	/**
	 * 最小費用流。頂点sからtへflowLimitに達するまで流せるだけ流す。<br>
	 * Fを流量、mを辺数として、O(F(n + m) log n)
	 * 
	 * @param s 始点（0≦s＜n）
	 * @param t 終点（0≦t＜n）
	 * @param flowLimit 流量制限
	 * @return [0]：流せた量、[1]：その時のコスト
	 */
	long[] flow(int s, int t, long flowLimit) {
		List<long[]> result = slope(s, t, flowLimit);
		return result.get(result.size() - 1);
	}

	/**
	 * <pre>
	 * 流量とコストの関係の折れ線を取得する。
	 * 戻り値の最初の要素は(0, 0)
	 * 戻り値の[0]、[1]は共に狭義単調増加
	 * 辺のコストの最大をxとして、最後の要素の[0]はx
	 * 
	 * ■制約
	 * sからtへ流したフローの流量がlongに収まる。
	 * 流したフローのコストの総和がlongに収まる。
	 * 0≦nx≦8×10^18＋1000
	 * </pre>
	 * 
	 * @param s 始点（0≦s＜n、s≠t）
	 * @param t 終点（0≦t＜n、s≠t）
	 * @return ＜[0]：流量、[1]：その時のコスト＞のリスト
	 */
	List<long[]> slope(int s, int t) {
		return slope(s, t, Long.MAX_VALUE);
	}

	/**
	 * <pre>
	 * 流量とコストの関係の折れ線を取得する。
	 * 戻り値の最初の要素は(0, 0)
	 * 戻り値の[0]、[1]は共に狭義単調増加
	 * 辺のコストの最大をxとして、最後の要素の[0]はmin(x, flowLimit)
	 * 
	 * ■制約
	 * sからtへ流したフローの流量がlongに収まる。
	 * 流したフローのコストの総和がlongに収まる。
	 * 0≦nx≦8×10^18＋1000
	 * </pre>
	 * 
	 * @param s 始点（0≦s＜n、s≠t）
	 * @param t 終点（0≦t＜n、s≠t）
	 * @param flowLimit 流量制限
	 * @return ＜[0]：流量、[1]：その時のコスト＞のリスト
	 */
	List<long[]> slope(int s, int t, long flowLimit) {
		assert 0 <= s && s < n : "s=" + s;
		assert 0 <= t && t < n : "t=" + t;
		assert s != t : "s=t=" + s;

		long[] dual = new long[n];
		long[] dist = new long[n];
		int[] pv = new int[n];
		int[] pe = new int[n];
		boolean[] vis = new boolean[n];

		long flow = 0;
		long cost = 0;
		long prevCost = -1;
		List<long[]> result = new ArrayList<>();
		result.add(new long[] { flow, cost });
		while (flow < flowLimit) {
			if (!dualRef(s, t, dual, dist, pv, pe, vis)) {
				break;
			}
			long c = flowLimit - flow;
			for (int v = t; v != s; v = pv[v]) {
				c = Math.min(c, g.get(pv[v]).get(pe[v]).cap);
			}
			for (int v = t; v != s; v = pv[v]) {
				Edge2 e = g.get(pv[v]).get(pe[v]);
				e.cap -= c;
				g.get(v).get(e.rev).cap += c;
			}
			long d = -dual[s];
			flow += c;
			cost += c * d;
			if (prevCost == d) {
				result.remove(result.size() - 1);
			}
			result.add(new long[] { flow, cost });
			prevCost = cost;
		}
		return result;
	}

	private boolean dualRef(int s, int t, long[] dual, long[] dist, int[] pv, int[] pe, boolean[] vis) {
		Arrays.fill(dist, Long.MAX_VALUE);
		Arrays.fill(pv, -1);
		Arrays.fill(pe, -1);
		Arrays.fill(vis, false);
		PriorityQueue<Q> que = new PriorityQueue<>((o1, o2) -> Long.compare(o1.key, o2.key));
		dist[s] = 0;
		que.add(new Q(0, s));
		while (!que.isEmpty()) {
			int v = que.poll().to;
			if (vis[v]) {
				continue;
			}
			vis[v] = true;
			if (v == t) {
				break;
			}
			for (int i = 0; i < g.get(v).size(); i++) {
				Edge2 e = g.get(v).get(i);
				if (vis[e.to] || e.cap == 0) {
					continue;
				}
				long cost = e.cost - dual[e.to] + dual[v];
				if (dist[e.to] - dist[v] > cost) {
					dist[e.to] = dist[v] + cost;
					pv[e.to] = v;
					pe[e.to] = i;
					que.add(new Q(dist[e.to], e.to));
				}
			}
		}
		if (!vis[t]) {
			return false;
		}

		for (int v = 0; v < n; v++) {
			if (vis[v]) {
				dual[v] -= dist[t] - dist[v];
			}
		}
		return true;
	}
}

import java.io.*;
import java.util.*;

class MinCostFlow {
	public class WeightedCapEdge {
		private final int from, to;
		private long cap;
		private long cost;
		private final int rev;
		WeightedCapEdge(int from, int to, long cap, long cost, int rev) {
			this.from = from;
			this.to = to;
			this.cap = cap;
			this.cost = cost;
			this.rev = rev;
		}
		public int getFrom()  {return from;}
		public int getTo()    {return to;}
		public long getCap()  {return cap;}
		public long getCost() {return cost;}
		public long getFlow() {return g[to][rev].cap;}
	}

	private static final long INF = Long.MAX_VALUE;

	private final int n;
	private int m;
	private final java.util.ArrayList<WeightedCapEdge> edges;
	private final int[] count;
	private final WeightedCapEdge[][] g;
	private final long[] potential;

	private final long[] dist;
	private final WeightedCapEdge[] prev;

	public MinCostFlow(int n) {
		this.n = n;
		this.edges = new java.util.ArrayList<>();
		this.count = new int[n];
		this.g = new WeightedCapEdge[n][];
		this.potential = new long[n];
		this.dist = new long[n];
		this.prev = new WeightedCapEdge[n];
	}

	public int addEdge(int from, int to, long cap, long cost) {
		rangeCheck(from, 0, n);
		rangeCheck(to, 0, n);
		nonNegativeCheck(cap, "Capacity");
		nonNegativeCheck(cost, "Cost");
		WeightedCapEdge e = new WeightedCapEdge(from, to, cap, cost, count[to]);
		count[from]++; count[to]++;
		edges.add(e);
		return m++;
	}

	private void buildGraph() {
		for (int i = 0; i < n; i++) {
			g[i] = new WeightedCapEdge[count[i]];
		}
		int[] idx = new int[n];
		for (WeightedCapEdge e : edges) {
			g[e.to][idx[e.to]++] = new WeightedCapEdge(e.to, e.from, 0, -e.cost, idx[e.from]);
			g[e.from][idx[e.from]++] = e;
		}
	}

	private long addFlow;
	private long addCost;

	public long[] minCostMaxFlow(int s, int t) {
		return minCostFlow(s, t, INF);
	}

	public long[] minCostFlow(int s, int t, long flowLimit) {
		rangeCheck(s, 0, n);
		rangeCheck(t, 0, n);
		if (s == t) {
			throw new IllegalArgumentException(String.format("s = t = %d", s));
		}
		nonNegativeCheck(flowLimit, "Flow");
		buildGraph();
		long flow = 0;
		long cost = 0;
		while (true) {
			dijkstra(s, t, flowLimit - flow);
			if (addFlow == 0) break;
			flow += addFlow;
			cost += addFlow * addCost;
		}
		return new long[]{flow, cost};
	}

	public java.util.ArrayList<long[]> minCostSlope(int s, int t) {
		return minCostSlope(s, t, INF);
	}

	public java.util.ArrayList<long[]> minCostSlope(int s, int t, long flowLimit) {
		rangeCheck(s, 0, n);
		rangeCheck(t, 0, n);
		if (s == t) {
			throw new IllegalArgumentException(String.format("s = t = %d", s));
		}
		nonNegativeCheck(flowLimit, "Flow");
		buildGraph();
		java.util.ArrayList<long[]> slope = new java.util.ArrayList<>();
		long prevCost = -1;
		long flow = 0;
		long cost = 0;
		while (true) {
			slope.add(new long[]{flow, cost});
			dijkstra(s, t, flowLimit - flow);
			if (addFlow == 0) return slope;
			flow += addFlow;
			cost += addFlow * addCost;
			if (addCost == prevCost) {
				slope.remove(slope.size() - 1);
			}
			prevCost = addCost;
		}
	}

	private void dijkstra(int s, int t, long maxFlow) {
		final class State implements Comparable<State> {
			final int v;
			final long d;
			State(int v, long d) {this.v = v; this.d = d;}
			public int compareTo(State s) {return d == s.d ? v - s.v : d > s.d ? 1 : -1;}
		}
		java.util.Arrays.fill(dist, INF);
		dist[s] = 0;
		java.util.PriorityQueue<State> pq = new java.util.PriorityQueue<>();
		pq.add(new State(s, 0l));
		while (pq.size() > 0) {
			State st = pq.poll();
			int u = st.v;
			if (st.d != dist[u]) continue;
			for (WeightedCapEdge e : g[u]) {
				if (e.cap <= 0) continue;
				int v = e.to;
				long nextCost = dist[u] + e.cost + potential[u] - potential[v];
				if (nextCost < dist[v]) {
					dist[v] = nextCost;
					prev[v] = e;
					pq.add(new State(v, dist[v]));
				}
			}
		}
		if (dist[t] == INF) {
			addFlow = 0;
			addCost = INF;
			return;
		}
		for (int i = 0; i < n; i++) {
			potential[i] += dist[i];
		}
		addCost = 0;
		addFlow = maxFlow;
		for (int v = t; v != s;) {
			WeightedCapEdge e = prev[v];
			addCost += e.cost;
			addFlow = java.lang.Math.min(addFlow, e.cap);
			v = e.from;
		}
		for (int v = t; v != s;) {
			WeightedCapEdge e = prev[v];
			e.cap -= addFlow;
			g[v][e.rev].cap += addFlow;
			v = e.from;
		}
	}

	public void clearFlow() {
		java.util.Arrays.fill(potential, 0);
		for (WeightedCapEdge e : edges) {
			long flow = e.getFlow();
			e.cap += flow;
			g[e.to][e.rev].cap -= flow;
		}
	}

	public WeightedCapEdge getEdge(int i) {
		rangeCheck(i, 0, m);
		return edges.get(i);
	}

	public java.util.ArrayList<WeightedCapEdge> getEdges() {
		return edges;
	}

	private void rangeCheck(int i, int minInlusive, int maxExclusive) {
		if (i < 0 || i >= maxExclusive) {
			throw new IndexOutOfBoundsException(
					String.format("Index %d out of bounds for length %d", i, maxExclusive)
					);
		}
	}

	private void nonNegativeCheck(long cap, java.lang.String attribute) {
		if (cap < 0) {
			throw new IllegalArgumentException(
					String.format("%s %d is negative.", attribute, cap)
					);
		}
	}
}

