public class Main implements Runnable {

	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * ACL Contest 1 C問題
		 * 考察メモ
		 * コマ→最終座標、のグラフを考える
		 * あるコマがある座標における時、そのコマからその座標へcap1/cost(B-距離)とする
		 * また、S→コマへcap1/cost0、座標からTへcap1/cost0とする
		 * すると、Sからコマ数Oだけの流量を流すとき、その最小費用流はO(B-距離総和)
		 * ここからOBを引くと距離の総和の最大化
		 *
		 * あるコマがある座標へ置けるかどうかは、制約小さいし適当に計算できる
		 */
		io.setAutoFlush(false);
		io.setAutoOutFlush(false);
		int N = io.nextInt(), M = io.nextInt();
		char[][] S = io.nextChars(N, '#');
		ACL.MinCostFlow flow = new ACL.MinCostFlow(2 * N * M + 2);
		int START = 0, END = 2 * N * M + 1;
		IntBinaryOperator f = (x, y) -> (x - 1) * N + y + 1, f2 = (x, y) -> (x - 1) * N + y + 1 + N * M;
		final int BIG = 1000;
		int piece = 0;
		for (int y = 1;y <= N;++ y) {
			for (int x = 1;x <= N;++ x) {
				if (S[y][x] == '#') continue;
				flow.addEdge(f2.applyAsInt(x, y), END, 1, 0);
				if (S[y][x] == 'o') {
					++ piece;
					flow.addEdge(START, f.applyAsInt(x, y), 1, 0);
					Queue<Point> que = new ArrayDeque<>();
					int[][] bfs = new int[S.length][S[0].length];
					for (int[] i : bfs) Arrays.fill(i, 1000000);
					bfs[y][x] = 0;
					que.add(new Point(x, y));
					while(!que.isEmpty()) {
						Point p = que.poll();
						flow.addEdge(f.applyAsInt(x, y), f2.applyAsInt(p.x, p.y), 1, BIG - bfs[p.y][p.x]);
						if (S[p.y][p.x + 1] != '#' && bfs[p.y][p.x] + 1 < bfs[p.y][p.x + 1]) {
							bfs[p.y][p.x + 1] = bfs[p.y][p.x] + 1;
							que.add(new Point(p.x + 1, p.y));
						}
						if (S[p.y + 1][p.x] != '#' && bfs[p.y][p.x] + 1 < bfs[p.y + 1][p.x]) {
							bfs[p.y + 1][p.x] = bfs[p.y][p.x] + 1;
							que.add(new Point(p.x, p.y + 1));
						}
					}
				}
			}
		}
		io.println(BIG * piece - flow.minCostFlow(START, END, piece)[1]);

	}

	/** デバッグ用コードのお供に */
