		Queue<Integer> starts = new ArrayDeque<>();
		Set<Integer> ends = new HashSet<>();
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (s[i][j] == 'o') {
					int start = i * m + j;
					starts.add(start);
					Queue<Integer> que = new ArrayDeque<>();
					que.add(start);
					int[][] d = new int[n][m];
					d[i][j] = 1;
					while (!que.isEmpty()) {
						int cur = que.poll();
						int cx = cur / m;
						int cy = cur % m;
						if (cx < n - 1) {
							int nx = cx + 1;
							int ny = cy;
							if (d[nx][ny] == 0 && s[nx][ny] != '#') {
								d[nx][ny] = d[cx][cy] + 1;
								int next = nx * m + ny;
								que.add(next);
								ends.add(next);
								mf.addEdge(start, next, 1, BIG - d[cx][cy]);
							}
						}
						if (cy < m - 1) {
							int nx = cx;
							int ny = cy + 1;
							if (d[nx][ny] == 0 && s[nx][ny] != '#') {
								d[nx][ny] = d[cx][cy] + 1;
								int next = nx * m + ny;
								que.add(next);
								ends.add(next);
								mf.addEdge(start, next, 1, BIG - d[cx][cy]);
							}
						}
					}
				}
			}
		}
		while (!starts.isEmpty()) {
			mf.addEdge(x, starts.poll(), 1, 0);
		}
		for (Integer end : ends) {
			if (s[end / m][end % m] == 'o') {
				mf.addEdge(end, y, 1, BIG);
			} else {
				mf.addEdge(end, y, 1, 0);
			}
		}

		long[] result = mf.flow(x, y);
		long ans = result[1] % BIG;
		ans = BIG - ans;
		ans %= BIG;
		System.out.println(ans);
	}

