// (づ°ω°)づﾐe★゜・。。・゜゜・。。・゜☆゜・。。・゜゜・。。・゜
public class Solver
{
    int[] Hungarian(int[,] a, int n, int m)
    {
        const int INF = int.MaxValue / 2;
        var u = new int[n + 1];
        var v = new int[m + 1];
        var p = new int[m + 1];
        var way = new int[m + 1];
        for (int i = 1; i <= n; ++i)
        {
            p[0] = i;
            int j0 = 0;
            var minv = Enumerable.Repeat(INF, m + 1).ToArray();
            var used = new bool[m + 1];
            do
            {
                used[j0] = true;
                int i0 = p[j0], delta = INF, j1 = 0;
                for (int j = 1; j <= m; ++j)
                    if (!used[j])
                    {
                        int cur = a[i0, j] - u[i0] - v[j];
                        if (cur < minv[j])
                        {
                            minv[j] = cur;
                            way[j] = j0;
                        }
                        if (minv[j] < delta)
                        {
                            delta = minv[j];
                            j1 = j;
                        }
                    }
                for (int j = 0; j <= m; ++j)
                    if (used[j])
                    {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    }
                    else
                    {
                        minv[j] -= delta;
                        j0 = j1;
                    }
            } while (p[j0] != 0);
            do
            {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0 != 0);
        }

        Write(v[0]);

        return p;
    }

    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        var a = ReadLines(n);

        var id = new int[n, m];
        int cnt = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (a[i][j] != '#')
                {
                    id[i, j] = cnt++;
                }

        var g = new List<List<(int, int)>>();
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (a[i][j] == 'o')
                {
                    var f = new bool[n, m];
                    var list = new List<(int, int)>();
                    var q = new Queue<(int, int)>();
                    q.Enqueue((i, j));
                    f[i, j] = true;
                    int step = 0;
                    while (q.Count > 0)
                    {
                        var nq = new Queue<(int, int)>();
                        while (q.Count > 0)
                        {
                            var t = q.Dequeue();
                            list.Add((id[t.Item1, t.Item2], step));
                            if (t.Item1 < n - 1 && a[t.Item1 + 1][t.Item2] != '#' && !f[t.Item1 + 1, t.Item2])
                            {
                                f[t.Item1 + 1, t.Item2] = true;
                                nq.Enqueue((t.Item1 + 1, t.Item2));
                            }
                            if (t.Item2 < m - 1 && a[t.Item1][t.Item2 + 1] != '#' && !f[t.Item1, t.Item2 + 1])
                            {
                                f[t.Item1, t.Item2 + 1] = true;
                                nq.Enqueue((t.Item1, t.Item2 + 1));
                            }
                        }
                        q = nq;
                        step++;
                    }
                    g.Add(list);
                }

        int no = g.Count;
        var g2 = new int[no + 1, cnt + 1];
        for (int i = 1; i <= no; i++)
            for (int j = 1; j <= cnt; j++)
                g2[i, j] = int.MaxValue / 2;
        for (int i = 0; i < no; i++)
            foreach (var e in g[i])
                g2[i + 1, e.Item1 + 1] = -e.Item2;

        Hungarian(g2, no, cnt);
    }

