class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int h, w;
        sc.Multi(out h, out w);
        var s = new string[h];
        for (int i = 0; i < h; i++)
        {
            s[i] = sc.Str;
        }
        var mf = new MinCostFlow(h * w + 2);
        int S = h * w;
        int T = h * w + 1;
        int c = 0;
        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
            {
                if (s[i][j] == 'o')  {
                    mf.addEdge(S, i * w + j, 1, 0);
                    ++c;
                }
                if (s[i][j] != '#') {
                    mf.addEdge(i * w + j, T, 1, 0);
                }
                if (i + 1 < h && s[i][j] != '#' && s[i + 1][j] != '#') {
                    mf.addEdge(i * w + j, (i + 1) * w + j, M, -1);
                }
                if (j + 1 < w && s[i][j] != '#' && s[i][j + 1] != '#') {
                    mf.addEdge(i * w + j, i * w + j + 1, M, -1);
                }
            }
        }
        Prt(-mf.run(S, T, c));

    }
}

