	sourceNum := 0

	var dx = []int{1, 0}
	var dy = []int{0, 1}

	for y := 0; y < N; y++ {
		for x := 0; x < M; x++ {
			if grid[y][x] != '#' {
				for i := 0; i < 2; i++ {
					nx, ny := x+dx[i], y+dy[i]
					if 0 <= nx && nx < M && 0 <= ny && ny < N && grid[ny][nx] != '#' {
						AddEdge(toID(x, y), toID(nx, ny), 10000, -1)
					}
				}
				AddEdge(toID(x, y), t, 1, 0)
			}
			if grid[y][x] == 'o' {
				sourceNum++
				AddEdge(sourceNum, toID(x, y), 1, 0)
			}
		}
	}

	for i := 1; i <= sourceNum; i++ {
