	}
	fmt.Println(-MinCostFlow(s, t, sources))
}

const Inf = 1 << 60

type Edge struct {
	To, Cap, Cost, Rev int
}

var adjL [][]*Edge

// 最小費用流 O(F|E|log|V|)
// sからtへの流量fの最小費用流を求める。流せない場合は-1
func MinCostFlow(s, t, f int) int {
	V := len(adjL)
	res := 0
	h, prevv, preve := make([]int, V), make([]int, V), make([]int, V)
	for f > 0 {
		q := Heapq{}
		dist := make([]int, V)
		for i := 0; i < V; i++ {
			dist[i] = Inf
		}
		dist[s] = 0
		q.push(State{Dist: 0, Node: s})
		for len(q) > 0 {
			now := q.pop()
			v := now.Node
			if dist[v] < now.Dist {
				continue
			}
			for i, edge := range adjL[v] {
				if edge.Cap > 0 && dist[edge.To] > dist[v]+edge.Cost+h[v]-h[edge.To] {
					dist[edge.To] = dist[v] + edge.Cost + h[v] - h[edge.To]
					prevv[edge.To] = v
					preve[edge.To] = i
					q.push(State{Dist: dist[edge.To], Node: edge.To})
				}
			}
		}
		if dist[t] == Inf {
			return -1
		}
		for v := 0; v < V; v++ {
			h[v] += dist[v]
		}
		d := f
		for v := t; v != s; v = prevv[v] {
			d = Min(d, adjL[prevv[v]][preve[v]].Cap)
		}
		f -= d
		res += d * h[t]
		for v := t; v != s; v = prevv[v] {
			edge := adjL[prevv[v]][preve[v]]
			edge.Cap -= d
			adjL[v][edge.Rev].Cap += d
		}
	}
	return res
}

func AddEdge(from, to, cap, cost int) {
	adjL[from] = append(adjL[from], &Edge{
		To:   to,
		Cap:  cap,
		Cost: cost,
		Rev:  len(adjL[to]),
	})
	adjL[to] = append(adjL[to], &Edge{
		To:   from,
		Cap:  0,
		Cost: -cost,
		Rev:  len(adjL[from]) - 1,
	})
}

func Min(xs ...int) int {
	min := xs[0]
	for _, x := range xs[1:] {
		if min > x {
			min = x
		}
	}
	return min
}

