// Dijkstra
class MinCostFlow(Capa, Cost, Capa CAPA_EPS = 0) {
  int n, m;
  int[][] g;
  int[] as, bs;
  Capa[] capa;
  Cost[] cost, pot;
  Capa tof;
  Cost toc;
  this(int n) {
    this.n = n; m = 0; g = new int[][n]; as = []; bs = []; capa = []; cost = [];
  }
  int addEdge(int u, int v, Capa w, Cost c) {
    debug {
      writeln("addEdge ", u, " ", v, " ", w, " ", c);
    }
    const i = m;
    g[u] ~= m; as ~= u; bs ~= v; capa ~= w; cost ~= c; ++m;
    g[v] ~= m; as ~= v; bs ~= u; capa ~= 0; cost ~= -c; ++m;
    return i;
  }
  bool solve(int source, int sink, Capa flow) {
    pot = new Cost[n];
    pot[] = 0;
    for (; ; ) {
      bool cont;
      foreach (u; 0 .. n) foreach (i; g[u]) if (capa[i] > CAPA_EPS) {
        const v = bs[i];
        if (pot[v] > pot[u] + cost[i]) {
          pot[v] = pot[u] + cost[i];
          cont = true;
        }
      }
      if (!cont) break;
    }
    auto dist = new Cost[n];
    auto prei = new int[n];
    auto vis = new bool[n];
    for (tof = 0, toc = 0; tof + CAPA_EPS < flow; ) {
      alias Entry = Tuple!(Cost, "c", int, "u");
      BinaryHeap!(Array!Entry, "a > b") que;
      dist[] = -1;
      prei[] = -1;
      vis[] = false;
      dist[source] = 0;
      prei[source] = -2;
      que.insert(Entry(0, source));
      for (; !que.empty(); ) {
        const c = que.front.c;
        const u = que.front.u;
        que.removeFront;
        if (vis[u]) continue;
        vis[u] = true;
        if (u == sink) break;
        foreach (i; g[u]) if (capa[i] > CAPA_EPS) {
          const v = bs[i];
          if (vis[v]) continue;
          const cc = c + cost[i] + pot[u] - pot[v];
          if (prei[v] == -1 || dist[v] > cc) {
            dist[v] = cc;
            prei[v] = i;
            que.insert(Entry(cc, v));
          }
        }
      }
      if (!vis[sink]) return false;
      Capa f = flow - tof;
      for (int v = sink; v != source; ) {
        const i = prei[v];
        if (f > capa[i]) f = capa[i];
        v = as[i];
      }
      for (int v = sink; v != source; ) {
        const i = prei[v];
        capa[i] -= f; capa[i ^ 1] += f;
        v = as[i];
      }
      tof += f;
      toc += f * (dist[sink] - pot[source] + pot[sink]);
      pot[] += dist[];
    }
    return true;
  }
}


void main() {
  try {
    for (; ; ) {
      const M = readInt();
      const N = readInt();
      auto S = new string[M];
      foreach (x; 0 .. M) {
        S[x] = readToken();
      }

      int cnt;
      auto mcf = new MinCostFlow!(int, int)(M * N + 2);
      foreach (x; 0 .. M) foreach (y; 0 .. N) {
        if (S[x][y] == 'o') {
          ++cnt;
          mcf.addEdge(M * N, x * N + y, 1, 0);
        }
      }
      foreach (x; 0 .. M) foreach (y; 0 .. N) {
        if (S[x][y] != '#') {
          mcf.addEdge(x * N + y, M * N + 1, 1, 0);
        }
      }
      foreach (x; 0 .. M) foreach (y; 0 .. N) {
        if (S[x][y] != '#') {
          if (x - 1 >= 0 && S[x - 1][y] != '#') {
            mcf.addEdge((x - 1) * N + y, x * N + y, cnt, -1);
          }
          if (y - 1 >= 0 && S[x][y - 1] != '#') {
            mcf.addEdge(x * N + (y - 1), x * N + y, cnt, -1);
          }
        }
      }
      const res = mcf.solve(M * N, M * N + 1, cnt);
      assert(res);
      writeln(-mcf.toc);
    }
  } catch (EOFException e) {
  }
}

