fn exit_index(pones: &Vec<(usize, usize)>, x: usize, y: usize, w: usize) -> usize {
    pones.len() + x + y * w
}

fn main() {
    let v = read_vec::<usize>();
    let (h, w) = (v[0], v[1]);
    let mut grid = vec![vec![]; h];
    for i in 0..h {
        grid[i] = read::<String>().chars().collect::<Vec<_>>();
    }

    let mut pones = vec![];
    for y in 0..h {
        for x in 0..w {
            if grid[y][x] == 'o' {
                pones.push((x, y));
            }
        }
    }

    let exit_size = h * w;

    let inf = 1000000000i64;
    let mut flow = MinCostFlowGraph::<i64>::new(pones.len() + exit_size + 2);
    // [0 - pones.len()): pones
    // [pones.len(), h * w): exits
    let s = pones.len() + exit_size;
    let t = s + 1;

    for i in 0..pones.len() {
        flow.add_edge(s, i, 1, 0);
    }
    for y in 0..h {
        for x in 0..w {
            if grid[y][x] == '#' {
                continue;
            }
            flow.add_edge(exit_index(&pones, x, y, w), t, 1, 0);
        }
    }
    for (i, &(start_x, start_y)) in pones.iter().enumerate() {
        let mut reachable = vec![vec![false; w]; h];
        reachable[start_y][start_x] = true;
        for y in start_y..h {
            for x in start_x..w {
                if grid[y][x] == '#' {
                    continue;
                }
                if (y > 0 && reachable[y - 1][x]) || (x > 0 && reachable[y][x - 1]) {
                    reachable[y][x] = true;
                }
                if reachable[y][x] {
                    let manhatten_dist = (y - start_y + x - start_x) as i64;
                    flow.add_edge(i, exit_index(&pones, x, y, w), 1, inf - manhatten_dist);
                }
            }
        }
    }
    let (max_flow, min_cost) = flow.flow(s, t, pones.len() as i64);
    println!("{}", inf * max_flow as i64 - min_cost);
}

