fn main() {
    let mut buf = ngtio::Buffer::new();
    let h = buf.usize();
    let w = buf.usize();
    let grid = iter::repeat_with(|| buf.string().chars().collect::<Vec<_>>())
        .take(h)
        .collect::<Vec<_>>();

    let encode = |i: usize, j: usize| i * w + j;
    let alive = seq::cartesian_product(0..h, 0..w)
        .filter(|&(i, j)| grid[i][j] != '#')
        .collect::<Vec<_>>();

    let n = h * w;
    let mut mcf = mincostflow::MinCostFlowGraph::new(n + 2);
    let shift = 1_000_000_000;
    let s = n;
    let t = n + 1;
    for &(i, j) in &alive {
        if grid[i][j] == 'o' {
            mcf.add_edge(s, encode(i, j), 1, (i + j) as i64);
        }
        mcf.add_edge(encode(i, j), t, 1, shift - (i + j) as i64);
        if i != h - 1 && grid[i + 1][j] != '#' {
            mcf.add_edge(encode(i, j), encode(i + 1, j), std::i64::MAX, 0);
        }
        if j != w - 1 && grid[i][j + 1] != '#' {
            mcf.add_edge(encode(i, j), encode(i, j + 1), std::i64::MAX, 0);
        }
    }
    let (flow, cost) = mcf.flow(s, t, std::i64::MAX);
    let ans = flow * shift - cost;
    assert!(0 <= ans);
    println!("{}", ans);
}

