        let PrimalDualBuilder {
            vsize,
            capacities,
            costs,
            ..
        } = self;
        PrimalDual {
            graph,
            capacities,
            costs,
            potential: std::iter::repeat(0).take(vsize).collect(),
            dist: Vec::with_capacity(vsize),
