                graph.add_edge(from, to, INF, -1);
            }
            graph.add_edge(from, sink, 1, 0);
            if board[i][j] == 'o' {
                graph.add_edge(source, from, 1, 0);
                flow += 1;
            }
        }
    }
    let ans = graph.solve(source, sink, flow);
